    INSERT INTO GT_DMF0021_COLUMN_SETUP VALUES ( 'F', 'CELL_MODEL_NICK_NAME', 'NVL(F.NICK_NAME,'''') AS CELL_MODEL_NICK_NAME', 1 );
    INSERT INTO GT_DMF0021_COLUMN_SETUP VALUES ( 'G', 'BIZ_TYPE_NAME',  'G.BIZ_TYPE AS BIZ_TYPE_NAME', 1 );
