                           , NVL(P_USER_ID, COALESCE(JT.USER_ID_2, JT.USER_ID_3))
                           , COALESCE(JT.FIX_1, JT.FIX_2, JT.FIX_3)
                           , COALESCE(JT.LOC_FLAG_1, JT.LOC_FLAG_2, JT.LOC_FLAG_3)
                           , COALESCE(JT.PROGRAM_ID_1, JT.PROGRAM_ID_2, JT.PROGRAM_ID_3)
                           , 'F'
                           , COALESCE(JT.ORIGIN_DIVISION_ID_1, JT.ORIGIN_DIVISION_ID_2, JT.ORIGIN_DIVISION_ID_3)
                           , COALESCE(JT.ELECTRODE_TYPE_1, JT.ELECTRODE_TYPE_2, JT.ELECTRODE_TYPE_3)
                           , COALESCE(JT.BUCKET_TYPE_1, JT.BUCKET_TYPE_2, JT.BUCKET_TYPE_3)
                           , COALESCE(JT.FROM_YYYYMMDD_1, JT.FROM_YYYYMMDD_2, JT.FROM_YYYYMMDD_3)
                           , COALESCE(JT.TO_YYYYMMDD_1, JT.TO_YYYYMMDD_2, JT.TO_YYYYMMDD_3))
          BULK COLLECT INTO V_SCP0013
          FROM JSON_TABLE(P_DATA, '$[*]' ERROR ON ERROR
                   COLUMNS (
                       A1                     VARCHAR2(1 CHAR)        PATH '$.A'                          NULL ON EMPTY ERROR ON ERROR
                     , A2                     VARCHAR2(1 CHAR)        PATH '$.a'                          NULL ON EMPTY ERROR ON ERROR
                     , ACTIVE_FLAG_1          VARCHAR2(1 CHAR)        PATH '$.ACTIVE_FLAG'                NULL ON EMPTY ERROR ON ERROR
                     , ACTIVE_FLAG_2          VARCHAR2(1 CHAR)        PATH '$.p_active_flag'              NULL ON EMPTY ERROR ON ERROR
                     , ACTIVE_FLAG_3          VARCHAR2(1 CHAR)        PATH '$.P_ACTIVE_FLAG'              NULL ON EMPTY ERROR ON ERROR
                     , DIVISION_ID_1          VARCHAR2(30 CHAR)       PATH '$.DIVISION_ID'                NULL ON EMPTY ERROR ON ERROR
                     , DIVISION_ID_2          VARCHAR2(30 CHAR)       PATH '$.p_division_id'              NULL ON EMPTY ERROR ON ERROR
                     , DIVISION_ID_3          VARCHAR2(30 CHAR)       PATH '$.P_DIVISION_ID'              NULL ON EMPTY ERROR ON ERROR
                     , PLAN_START_YYYYMMDD_1  VARCHAR2(8 CHAR)        PATH '$.PLAN_START_YYYYMMDD'        NULL ON EMPTY ERROR ON ERROR
                     , PLAN_START_YYYYMMDD_2  VARCHAR2(8 CHAR)        PATH '$.p_plan_start_yyyymmdd'      NULL ON EMPTY ERROR ON ERROR
                     , PLAN_START_YYYYMMDD_3  VARCHAR2(8 CHAR)        PATH '$.P_PLAN_START_YYYYMMDD'      NULL ON EMPTY ERROR ON ERROR
                     , PLAN_TYPE_1            VARCHAR2(2 CHAR)        PATH '$.PLAN_TYPE'                  NULL ON EMPTY ERROR ON ERROR
                     , PLAN_TYPE_2            VARCHAR2(2 CHAR)        PATH '$.p_plan_type'                NULL ON EMPTY ERROR ON ERROR
                     , PLAN_TYPE_3            VARCHAR2(2 CHAR)        PATH '$.P_PLAN_TYPE'                NULL ON EMPTY ERROR ON ERROR
                     , SEQ_1                  VARCHAR2(10 CHAR)       PATH '$.SEQ'                        NULL ON EMPTY ERROR ON ERROR
                     , SEQ_2                  VARCHAR2(10 CHAR)       PATH '$.p_seq'                      NULL ON EMPTY ERROR ON ERROR
                     , SEQ_3                  VARCHAR2(10 CHAR)       PATH '$.P_SEQ'                      NULL ON EMPTY ERROR ON ERROR
                     , OPERATION_GROUP_1      VARCHAR2(1 CHAR)        PATH '$.OPERATION_GROUP'            NULL ON EMPTY ERROR ON ERROR
                     , OPERATION_GROUP_2      VARCHAR2(1 CHAR)        PATH '$.p_operation_group'          NULL ON EMPTY ERROR ON ERROR
                     , OPERATION_GROUP_3      VARCHAR2(1 CHAR)        PATH '$.P_OPERATION_GROUP'          NULL ON EMPTY ERROR ON ERROR
                     , SCM_SITE_ID_1          VARCHAR2(100 CHAR)      PATH '$.SCM_SITE_ID'                NULL ON EMPTY ERROR ON ERROR
                     , SCM_SITE_ID_2          VARCHAR2(100 CHAR)      PATH '$.p_scm_site_id'              NULL ON EMPTY ERROR ON ERROR
                     , SCM_SITE_ID_3          VARCHAR2(100 CHAR)      PATH '$.P_SCM_SITE_ID'              NULL ON EMPTY ERROR ON ERROR
                     , ITEM_ID_1              VARCHAR2(100 CHAR)      PATH '$.ITEM_ID'                    NULL ON EMPTY ERROR ON ERROR
                     , ITEM_ID_2              VARCHAR2(100 CHAR)      PATH '$.p_item_id'                  NULL ON EMPTY ERROR ON ERROR
                     , ITEM_ID_3              VARCHAR2(100 CHAR)      PATH '$.P_ITEM_ID'                  NULL ON EMPTY ERROR ON ERROR
                     , LINE_ID_1              VARCHAR2(50 CHAR)       PATH '$.LINE_ID'                    NULL ON EMPTY ERROR ON ERROR
                     , LINE_ID_2              VARCHAR2(50 CHAR)       PATH '$.p_line_id'                  NULL ON EMPTY ERROR ON ERROR
                     , LINE_ID_3              VARCHAR2(50 CHAR)       PATH '$.P_LINE_ID'                  NULL ON EMPTY ERROR ON ERROR
                     , OPERATION_ID_1         VARCHAR2(100 CHAR)      PATH '$.OPERATION_ID'               NULL ON EMPTY ERROR ON ERROR
                     , OPERATION_ID_2         VARCHAR2(100 CHAR)      PATH '$.p_operation_id'             NULL ON EMPTY ERROR ON ERROR
                     , OPERATION_ID_3         VARCHAR2(100 CHAR)      PATH '$.P_OPERATION_ID'             NULL ON EMPTY ERROR ON ERROR
                     , MEASURE_1              VARCHAR2(100 CHAR)      PATH '$.MEASURE'                    NULL ON EMPTY ERROR ON ERROR
                     , MEASURE_2              VARCHAR2(100 CHAR)      PATH '$.p_measure'                  NULL ON EMPTY ERROR ON ERROR
                     , MEASURE_3              VARCHAR2(100 CHAR)      PATH '$.P_MEASURE'                  NULL ON EMPTY ERROR ON ERROR
                     , YYYYMMDD_1             VARCHAR2(8 CHAR)        PATH '$.YYYYMMDD'                   NULL ON EMPTY ERROR ON ERROR
                     , YYYYMMDD_2             VARCHAR2(8 CHAR)        PATH '$.p_yyyymmdd'                 NULL ON EMPTY ERROR ON ERROR
                     , YYYYMMDD_3             VARCHAR2(8 CHAR)        PATH '$.P_YYYYMMDD'                 NULL ON EMPTY ERROR ON ERROR
                     , QTY_1                  VARCHAR2(200 CHAR)      PATH '$.QTY'                        NULL ON EMPTY ERROR ON ERROR
                     , QTY_2                  VARCHAR2(200 CHAR)      PATH '$.p_qty'                      NULL ON EMPTY ERROR ON ERROR
                     , QTY_3                  VARCHAR2(200 CHAR)      PATH '$.P_QTY'                      NULL ON EMPTY ERROR ON ERROR
                     , FIX_REASON_1           VARCHAR2(100 CHAR)      PATH '$.FIX_REASON'                 NULL ON EMPTY ERROR ON ERROR
                     , FIX_REASON_2           VARCHAR2(100 CHAR)      PATH '$.p_fix_reason'               NULL ON EMPTY ERROR ON ERROR
                     , FIX_REASON_3           VARCHAR2(100 CHAR)      PATH '$.P_FIX_REASON'               NULL ON EMPTY ERROR ON ERROR
                     , USER_ID_2              VARCHAR2(100 CHAR)      PATH '$.p_user_id'                  NULL ON EMPTY ERROR ON ERROR
                     , USER_ID_3              VARCHAR2(100 CHAR)      PATH '$.P_USER_ID'                  NULL ON EMPTY ERROR ON ERROR
                     , FIX_1                  VARCHAR2(1 CHAR)        PATH '$.FIX'                        NULL ON EMPTY ERROR ON ERROR
                     , FIX_2                  VARCHAR2(1 CHAR)        PATH '$.p_fix'                      NULL ON EMPTY ERROR ON ERROR
                     , FIX_3                  VARCHAR2(1 CHAR)        PATH '$.P_FIX'                      NULL ON EMPTY ERROR ON ERROR
                     , LOC_FLAG_1             VARCHAR2(1 CHAR)        PATH '$.LOC_FLAG'                   NULL ON EMPTY ERROR ON ERROR
                     , LOC_FLAG_2             VARCHAR2(1 CHAR)        PATH '$.p_loc_flag'                 NULL ON EMPTY ERROR ON ERROR
                     , LOC_FLAG_3             VARCHAR2(1 CHAR)        PATH '$.P_LOC_FLAG'                 NULL ON EMPTY ERROR ON ERROR
                     , PROGRAM_ID_1           VARCHAR2(200 CHAR)      PATH '$.PROGRAM_ID'                 NULL ON EMPTY ERROR ON ERROR
                     , PROGRAM_ID_2           VARCHAR2(200 CHAR)      PATH '$.p_program_id'               NULL ON EMPTY ERROR ON ERROR
                     , PROGRAM_ID_3           VARCHAR2(200 CHAR)      PATH '$.P_PROGRAM_ID'               NULL ON EMPTY ERROR ON ERROR
                     , ORIGIN_DIVISION_ID_1   VARCHAR2(30 CHAR)       PATH '$.ORIGIN_DIVISION_ID'         NULL ON EMPTY ERROR ON ERROR
                     , ORIGIN_DIVISION_ID_2   VARCHAR2(30 CHAR)       PATH '$.p_origin_division_id'       NULL ON EMPTY ERROR ON ERROR
                     , ORIGIN_DIVISION_ID_3   VARCHAR2(30 CHAR)       PATH '$.P_ORIGIN_DIVISION_ID'       NULL ON EMPTY ERROR ON ERROR
                     , ELECTRODE_TYPE_1       VARCHAR2(50 CHAR)       PATH '$.ELECTRODE_TYPE'             NULL ON EMPTY ERROR ON ERROR
                     , ELECTRODE_TYPE_2       VARCHAR2(50 CHAR)       PATH '$.p_electrode_type'           NULL ON EMPTY ERROR ON ERROR
                     , ELECTRODE_TYPE_3       VARCHAR2(50 CHAR)       PATH '$.P_ELECTRODE_TYPE'           NULL ON EMPTY ERROR ON ERROR
                     , BUCKET_TYPE_1          VARCHAR2(10 CHAR)       PATH '$.BUCKET_TYPE'                NULL ON EMPTY ERROR ON ERROR
                     , BUCKET_TYPE_2          VARCHAR2(10 CHAR)       PATH '$.p_bucket_type'              NULL ON EMPTY ERROR ON ERROR
                     , BUCKET_TYPE_3          VARCHAR2(10 CHAR)       PATH '$.P_BUCKET_TYPE'              NULL ON EMPTY ERROR ON ERROR
                     , FROM_YYYYMMDD_1        VARCHAR2(8 CHAR)        PATH '$.FROM_YYYYMMDD'              NULL ON EMPTY ERROR ON ERROR
                     , FROM_YYYYMMDD_2        VARCHAR2(8 CHAR)        PATH '$.p_from_yyyymmdd'            NULL ON EMPTY ERROR ON ERROR
                     , FROM_YYYYMMDD_3        VARCHAR2(8 CHAR)        PATH '$.P_FROM_YYYYMMDD'            NULL ON EMPTY ERROR ON ERROR
                     , TO_YYYYMMDD_1          VARCHAR2(8 CHAR)        PATH '$.TO_YYYYMMDD'                NULL ON EMPTY ERROR ON ERROR
                     , TO_YYYYMMDD_2          VARCHAR2(8 CHAR)        PATH '$.p_to_yyyymmdd'              NULL ON EMPTY ERROR ON ERROR
                     , TO_YYYYMMDD_3          VARCHAR2(8 CHAR)        PATH '$.P_TO_YYYYMMDD'              NULL ON EMPTY ERROR ON ERROR
                   )) JT;
        -- 2026.09.17 AJS JSON 키 - AS-IS 형식 테이블 이름(p_xxx · P_XXX)도 받음 (END)
        END IF;                                                 /* AJS 20261007 화면검증 */

        /* 저장 - 확정 · 오류 시 되돌림 · 오류 로그는 호출 프로시저가 처리 */
        P_SCP0013_SAVE_LINE_ROW_DS(V_SCP0013, C_RC1, C_RC2);

        FETCH C_RC1 INTO V_RESULT_CODE, N_RESULT_CNT;
        CLOSE C_RC1;

        FETCH C_RC2 INTO V_ERR_CODE, V_ERR_MESSAGE;
        CLOSE C_RC2;

        O_RESULT_CODE := V_RESULT_CODE;
        O_RESULT_CNT  := N_RESULT_CNT;
        O_RESULT_MSG  := CASE
                             WHEN V_ERR_CODE IS NOT NULL
                             THEN '[' || V_ERR_CODE || ']' || V_ERR_MESSAGE
                         END;

        /* 화면 줄 형식은 저장한 칸 수를 돌려준다 (AS-IS 저장 결과 메시지 건수) */                 /* AJS 20261007 화면검증 */
        IF     V_IS_PIVOT    = 'Y'                                  /* AJS 20261007 화면검증 */
           AND O_RESULT_CODE = 'S' THEN                             /* AJS 20261007 화면검증 */
            O_RESULT_CNT := V_SCP0013.COUNT;                      /* AJS 20261007 화면검증 */
        END IF;                                                 /* AJS 20261007 화면검증 */

    EXCEPTION
        WHEN OTHERS THEN
            /* 저장 호출 전 단계(JSON 변환) 오류 - 원장 변경 없음 */
            O_RESULT_CODE := 'F';
            O_RESULT_CNT  := 0;
            O_RESULT_MSG  := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME
                                         , 'ERROR'
                                         , NULL
                                         , SUBSTR(O_RESULT_MSG, 1, 1000)
                                         , SUBSTR('P_USER_ID=' || P_USER_ID || ', P_DATA=' || DBMS_LOB.SUBSTR(P_DATA, 400, 1), 1, 500)
                                         , SYSDATE);

    END P_SCP0013_SAVE_LINE_ROW_JSON;

    -- 2026.09.17 AJS Extra Spec 조회조건 목록 추가 (START)
    /* ========================================================================================
       12. SCP0013_GET_EXTRA_SPEC - Extra Spec 조회조건 목록
       ======================================================================================== */
    PROCEDURE P_SCP0013_GET_EXTRA_SPEC
    (
        P_DIVISION_ID           IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SCP0013_GET_EXTRA_SPEC
     * Description  : Extra Spec 조회조건 정보 표시용
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2025/04/02   mrchois        PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 - Extra Spec 조회조건 추가 표시
     * 2026.09.17   AJS            [MSSQL -> Oracle 전환]
     *                              - 사업부 비교 : AS-IS 대소문자 · 뒤 공백 무시 비교 재현 (UPPER · RTRIM)
     *                              - 정렬 : AS-IS 정렬 규칙(대소문자 무시 · 하이픈 무시) 재현
     */
    BEGIN

        OPEN O_RC1 FOR
        SELECT SCP_OPERATION_GROUP                          AS OPERATION_GROUP
             , NVL(SCP_EXTRA_SPEC, '-')                     AS CODE
             , NVL(SCP_EXTRA_SPEC, '-')                     AS NAME
          FROM SCM_MST_ITEM_SN
         WHERE 1 = 1
           AND DIVISION_ID = UPPER(RTRIM(P_DIVISION_ID))
         GROUP BY SCP_OPERATION_GROUP
                , SCP_EXTRA_SPEC
         ORDER BY UPPER(TRANSLATE(NVL(SCP_EXTRA_SPEC, '-'), '_-', '/')) NULLS FIRST
                , CODE;

    END P_SCP0013_GET_EXTRA_SPEC;
    -- 2026.09.17 AJS Extra Spec 조회조건 목록 추가 (END)

END PKG_SCP0013;
/
-- ##### PACKAGE BODY PKG_SSP0045 (사내 적용 2026-10-09 14:43:08 · ORA-00979 문장 1→0 · 마커 1)
CREATE OR REPLACE PACKAGE BODY PKG_SSP0045
IS
/*
 * Program ID   : PKG_SSP0045
 * Description  : SSP0045 Shipment Request SEMI
 * Program History
 *===================================================================================================
 * Date         In Charge       Description
 *===================================================================================================
 * 2026.09.29   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 : 본표 행 적재의 약칭 묶음(I)을 이번 조회 임시 테이블 품목으로 한정(결과 동일)
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          조회조건 ALL : 공장 사이트 · 품목 조건에 ALL 을 조건 없음으로 받음
 * 2026.10.08   AJS          조회조건 Model ALL : 대소문자 · 앞뒤 공백 무시, 후보 목록(V_ITEM_TAB)을 만들지 않고 조건 없음으로 받음
 *
 * 전환 기준
 *   1. AS-IS 임시 테이블 12개는 미리 만들어 둔 GT_SSP0045_* 로 옮기고 프로시저 시작에 DELETE 로 비운다.
 *   2. 피벗 칸 수가 조회 기간에 따라 달라지므로 본표 조회의 마지막 조립만 동적 SQL 을 쓴다.
 *   3. AS-IS 가 CTE(WITH)로 적던 구간은 인라인 뷰로 바꾼다.
 *   4. 정렬은 AS-IS 순서를 내는 공용 함수 FN_ASIS_SORT_KEY 를 쓴다.
 *   5. 원본 MSSQL 주석은 내용을 그대로 두고 블록 주석으로만 옮긴다.
 *   6. MSSQL 이 문자 날짜를 날짜로 바꿔 견주던 자리는 TO_DATE 로 형을 맞춘다.
 */

    /*******************************************************************************
     * P_SSP0045_GET_SHEET_CALENDAR_3SPAN
     *   AS-IS SCP0009_GET_SHEET_CALENDAR_3SPAN
     *   본표 날짜 머리글(일 · 주 · 월 세 단)
     *******************************************************************************/
    PROCEDURE P_SSP0045_GET_SHEET_CALENDAR_3SPAN
    (
        P_START_YYYYMMDD        IN  VARCHAR2
      , P_END_YYYYMMDD          IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG               VARCHAR2(4000 CHAR);
    BEGIN

        OPEN O_RC1 FOR
            SELECT 'D_'||BASIS_YYYYMMDD                       AS COLUMN_NAME
                 , CALENDAR_DAY                               AS COLUMN_LABEL_NAME
                 , WEEK_NAME                                  AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                                 AS LARGE_CLASS_LABEL_NAME
                 , DAYOFWEEK                                  AS DAY_CODE
                 , BASIS_YYYYMMDD||'31'                       AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
             UNION ALL
            SELECT 'W_'||BASIS_YYYYMM||ISO_WEEK               AS COLUMN_NAME
                 , WEEK_NAME                                  AS COLUMN_LABEL_NAME
                 , WEEK_NAME                                  AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                                 AS LARGE_CLASS_LABEL_NAME
                 , NULL                                       AS DAY_CODE
                 , BASIS_START_DATE||'21'                     AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY BASIS_YYYYMM
                    , ISO_WEEK
                    , WEEK_NAME
                    , MONTH_NAME
                    , BASIS_START_DATE
             UNION ALL
            SELECT 'M_'||BASIS_YYYYMM                         AS COLUMN_NAME
                 , MONTH_NAME                                 AS COLUMN_LABEL_NAME
                 , MONTH_NAME                                 AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                                 AS LARGE_CLASS_LABEL_NAME
                 , NULL                                       AS DAY_CODE
                 , MIN(BASIS_START_DATE)||'01'                AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY BASIS_YYYYMM
                    , MONTH_NAME
             ORDER BY SORT_ORDER_NO;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS COLUMN_NAME FROM DUAL WHERE 1 = 0;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_GET_SHEET_CALENDAR_3SPAN;

    /*******************************************************************************
     * P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE
     *   AS-IS SCM0002_GET_BODITEM_FOR_PRJROUTE_POPUP
     *   BOD 선택 팝업 — 품목 하나가 실려 있는 운송 경로 목록
     *
     * ★AS-IS 화면은 이 팝업을 공용 화면(SCM0002)으로 띄우면서 부모 화면 이름을 함께 넘긴다.
     *   TO-BE 기능 등록이 이 화면 이름(P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE)으로 되어 있어 이 패키지에 둔다.
     * ★P_PROGRAM_ID 는 AS-IS 도 선언만 하고 본문에서 쓰지 않는다(호출 이력 구분용).
     *******************************************************************************/
    PROCEDURE P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG               VARCHAR2(4000 CHAR);
        V_TO_SITE_TYPE          VARCHAR2(30 CHAR) := 'PLANT';
    BEGIN

        OPEN O_RC1 FOR
            SELECT DISTINCT
                   A.DIVISION_ID
                 , B.FROM_SITE
                 , SF.DIVISION_ID                             AS FROM_DIVISION_ID
                 , SF.SITE_TYPE                               AS FROM_SITE_TYPE
                 , SF.SITE_DESCRIPTION                        AS FROM_SITE_NAME
                 , B.TO_SITE
                 , ST.DIVISION_ID                             AS TO_DIVISION_ID
                 , ST.SITE_TYPE                               AS TO_SITE_TYPE
                 , ST.SITE_DESCRIPTION                        AS TO_SITE_NAME
                 , A.ITEM_ID
                 , A.PRIORITY
                 , A.BOD_ID
                 , B.INCOTERMS
                 , C.TRANSPORT_MODE
                 /* BOD 2단계 개발 */
                 /* ,(SELECT v.lt_total FROM scp_mst_bod_v v WHERE v.division_id = b.division_id  and v.bod_id = b.bod_id ) AS lead_time */
                 , (SELECT SA.LT_TOTAL
                      FROM SCP_MST_BOD_N_V SA
                     WHERE SA.DIVISION_ID = B.DIVISION_ID
                       AND SA.BOD_ID      = B.BOD_ID)          AS LEAD_TIME
                 , A.VALID_YN                                 AS BOD_ITEM_VALID
                 , C.ROUTE_ID
                 , C.DAYS_MON
                 , C.DAYS_TUE
                 , C.DAYS_WED
                 , C.DAYS_THU
                 , C.DAYS_FRI
                 , C.DAYS_SAT
                 , C.DAYS_SUN
                 /* Ship Frozen구간 다음일자 */
                 , TO_CHAR(TO_DATE(P_FROM_YYYYMMDD, 'YYYYMMDD') + NVL(FS.SHIP_FROZEN, 0), 'YYYYMMDD') AS FROZEN_YYYYMMDD
                 , TO_DATE(B.ATTRIBUTE2, 'YYYYMMDD')          AS BOD_FROM_YYYYMMDD    /* BOD 2단계 개발 */
                 , TO_DATE(B.ATTRIBUTE3, 'YYYYMMDD')          AS BOD_TO_YYYYMMDD      /* BOD 2단계 개발 */
              FROM SCP_MST_BOD_ITEM              A
                 , SCP_MST_BOD                   B
                 , SCM_MST_SITE                  SF
                 , SCM_MST_SITE                  ST
                 , SCP_MST_DISTRIBUTION_ROUTE    C
                 , SCM_MST_SITE                  FS
             WHERE A.BOD_ID            = B.BOD_ID
               AND SF.SCM_SITE_ID      = B.FROM_SITE
               AND ST.SCM_SITE_ID      = B.TO_SITE
               AND B.ROUTE_ID          = C.ROUTE_ID
               AND FS.DIVISION_ID      = A.DIVISION_ID
               AND FS.SCM_SITE_ID      = B.FROM_SITE
               AND SF.SITE_TYPE        = 'PLANT'
               AND SF.OPERATION_GROUP  = P_OPERATION_GROUP
               AND ST.SITE_TYPE        = V_TO_SITE_TYPE
               AND FS.SITE_TYPE        = 'PLANT'
               AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
               AND FS.OSP_YN           = 'N'
               AND FS.VALID_YN         = 'Y'
               AND B.INCOTERMS         = 'DAP'                 /* Semi 용 DAP 적용 */
               AND SF.PLANT_ID        <> ST.PLANT_ID           /* 동일 Plant 제외(A040-A -> A040-P 등) */
               AND A.DIVISION_ID       = P_DIVISION_ID
               AND A.ITEM_ID           = P_ITEM_ID
             ORDER BY BOD_ITEM_VALID DESC
                    , FN_ASIS_SORT_KEY(DIVISION_ID) NULLS FIRST
                    , FN_ASIS_SORT_KEY(FROM_SITE) NULLS FIRST
                    , FN_ASIS_SORT_KEY(TO_SITE) NULLS FIRST
                    , PRIORITY
                    , FN_ASIS_SORT_KEY(TRANSPORT_MODE) NULLS FIRST;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE;

    /*******************************************************************************
     * P_SSP0045_GET_SHIPMENT_REQUEST
     *   AS-IS SSP0045_GET_SHIPMENT_REQUEST
     *   Shipment Request 본표 (측정값 9 종 × 일 · 주 · 월 피벗)
     *
     * 측정값
     *   1 SCP_PLAN   SCP 출하계획      2 SHIP_PLAN 출하계획        3 SHIP_REQ  출하지시
     *   4 CUST_PLAN  고객 출하계획     5 CUST_REQ  고객 출하지시   6 INTN_MOVEMENT 사내 이동
     *   7 INSP_PLAN  특성 계획         8 WH_BOH_PLAN 창고 기초재고(계획)
     *   9 WH_BOH_REQ 창고 기초재고(지시)
     *
     * ★소형(40) 사업부는 사내 이동 · 특성 계획 · 재고를 SSP_ANL_SHIP_PLAN_40 에서 읽는다
     *   (AS-IS [C20201016-000147]).
     * ★피벗 칸 수가 조회 기간에 따라 달라지므로 마지막 조립만 동적 SQL 을 쓴다.
     *******************************************************************************/
    PROCEDURE P_SSP0045_GET_SHIPMENT_REQUEST
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_SCM_SITE_ID           IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , P_SHEET_NAME            IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG                   VARCHAR2(4000 CHAR);
        V_STOCK_YYYYMMDD            VARCHAR2(8 CHAR);
        V_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR);
        V_CUTOFF_START_YYYYMMDD     VARCHAR2(8 CHAR);
        V_SCP_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
        V_SCP_PLAN_TYPE             VARCHAR2(10 CHAR);
        V_SCP_SEQ                   NUMBER;
        V_APP_TYPE                  VARCHAR2(8 CHAR) := 'SSP';
        V_BASE_MONDAY_YYYYMMDD      VARCHAR2(8 CHAR);
        V_PIVOT                     CLOB;
        V_SQL                       CLOB;
        V_ITEM_TAB                  T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN

        V_PLAN_START_YYYYMMDD   := TO_CHAR(SYSDATE, 'YYYYMMDD');
        V_CUTOFF_START_YYYYMMDD := TO_CHAR(SYSDATE - 1, 'YYYYMMDD');
        V_STOCK_YYYYMMDD        := TO_CHAR(TO_DATE(P_FROM_YYYYMMDD, 'YYYYMMDD') - 3, 'YYYYMMDD');   /* FROM -3일 */

        /* SCP 계획 기준 주의 월요일에서 4주 앞 */
        V_BASE_MONDAY_YYYYMMDD  := TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'), 'MON') - 28, 'YYYYMMDD');

        /* 임시 테이블 비우기 (ON COMMIT PRESERVE ROWS 라 앞 호출 자료가 남는다) */
        DELETE FROM GT_SSP0045_SHIPMENT_PLAN_FG;
        DELETE FROM GT_SSP0045_PLAN;
        DELETE FROM GT_SSP0045_PLAN_ERP_RESULT;
        DELETE FROM GT_SSP0045_SHIP_REQ;
        DELETE FROM GT_SSP0045_SHIP_REQ_OWMS;
        DELETE FROM GT_SSP0045_FILTER;
        DELETE FROM GT_SSP0045_40_STD;
        DELETE FROM GT_SSP0045_SHIP_ROW;
        DELETE FROM GT_SSP0045_STOCK;
        DELETE FROM GT_SSP0045_CAL_QTY;
        DELETE FROM GT_SSP0045_REQUESTOR;
        DELETE FROM GT_SSP0045_SHIP_PIVOT;

        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        /* 입력값(쉼표 구분 · 빈 값 제외)이 품목 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 문장 밖에서 한 번 고른다
           대상 = 사업부 품목 원장(SCM_MST_ITEM_SN) 품목 + 입력값 그대로(기존 정확일치로 나오던 품목 유지) */
        /* IF TRIM(P_ITEM_ID) IS NOT NULL THEN */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname : ALL 은 후보 목록을 만들지 않고 조건 없음 */
            SELECT DISTINCT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM ( SELECT A.ITEM_ID
                       FROM SCM_MST_ITEM_SN                      A
                          , TABLE(STRING_SPLIT(P_ITEM_ID, ','))   SA
                      WHERE SA.COLUMN_VALUE IS NOT NULL
                        AND A.DIVISION_ID   = P_DIVISION_ID
                        AND (    UPPER(A.ITEM_ID)   LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%'
                              OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%' )
                     UNION ALL
                     SELECT UPPER(SB.COLUMN_VALUE)
                       FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))   SB
                      WHERE SB.COLUMN_VALUE IS NOT NULL
                   )  IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 최신 FN 계획 판 */
        BEGIN
            SELECT PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , PLAN_SEQ
              INTO V_SCP_PLAN_START_YYYYMMDD
                 , V_SCP_PLAN_TYPE
                 , V_SCP_SEQ
              FROM ( SELECT PLAN_START_YYYYMMDD
                          , PLAN_TYPE
                          , PLAN_SEQ
                       FROM SCP_PLAN_VERSION_V
                      WHERE DIVISION_ID = P_DIVISION_ID
                        AND PLAN_CYCLE  = 'WEEKLY'
                        AND PLAN_TYPE   = 'FN'
                      ORDER BY PLAN_START_YYYYMMDD DESC
                             , PLAN_TYPE_ORDER DESC
                             , PLAN_SEQ DESC )  IA
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_SCP_PLAN_START_YYYYMMDD := NULL;
        END;

        /*---------------------------------------------
         * 0. SCP 출하계획(FG) 기준 자료
         *   ★AS-IS 는 B 를 LEFT JOIN 으로 적었으나 WHERE 에 B.DIVISION_ID IS NOT NULL 이 있어
         *     결과가 내부 조인과 같다. 조인 조건을 옮길 수 있도록 내부 조인으로 적는다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIPMENT_PLAN_FG
        ( DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, BIZ_TYPE, PROJECT_CODE, FCST_TYPE
        , ITEM_ID, TO_SITE, INCOTERMS, FROM_SITE, BOD_ID, TRANSPORT_MODE, MEASURE, YYYYMMDD, QTY )
        SELECT DIVISION_ID
             , PLAN_START_YYYYMMDD            /* plan주의 월요일 */
             , PLAN_TYPE
             , MAX(SEQ)                                       AS SEQ
             , MAX(OPERATION_GROUP)                           AS BIZ_TYPE
             , NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/')                         AS PROJECT_CODE
             , FCST_TYPE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , TRANSPORT_MODE
             , MEASURE
             , YYYYMMDD
             , SUM(QTY)                                       AS QTY
          FROM ( SELECT B.DIVISION_ID
                      , B.PLAN_START_YYYYMMDD
                      , B.PLAN_TYPE
                      , B.SEQ
                      , B.OPERATION_GROUP
                      , A.PROJECT_CODE
                      , A.FCST_TYPE
                      , B.ITEM_ID
                      , B.TO_SITE
                      /* 2020.09.18  KBK  법인간 거래 - 실제 매출 Incoterms 적용 */
                      , NVL(C.SSP_INCOTERMS, B.INCOTERMS)     AS INCOTERMS
                      , B.FROM_SITE
                      , B.BOD_ID
                      , B.TRANSPORT_MODE
                      , B.MEASURE
                      , B.YYYYMMDD
                      , A.ALLOCATION_QTY                      AS QTY
                   FROM SCP_PLN_SHIPMENT_PLAN_PEGGING  A
                      , SCP_PLN_SHIPMENT_PLAN          B
                      , SCP_MST_BOD_N_V                C
                  WHERE A.DIVISION_ID           = B.DIVISION_ID
                    AND A.PLAN_START_YYYYMMDD   = B.PLAN_START_YYYYMMDD
                    AND A.PLAN_TYPE             = B.PLAN_TYPE
                    AND A.SEQ                   = B.SEQ
                    AND A.ORDER_ID              = B.ORDER_ID
                    AND C.DIVISION_ID(+)        = B.DIVISION_ID
                    AND C.BOD_ID(+)             = B.BOD_ID
                    AND B.MEASURE               = 'SHIP_PLAN'
                    AND B.SEMI_YN               = 'N'
                    AND B.OPERATION_GROUP       = (CASE WHEN P_DIVISION_ID = '40' THEN 'A' ELSE B.OPERATION_GROUP END)
                    AND A.DIVISION_ID           = P_DIVISION_ID
                    AND A.PLAN_START_YYYYMMDD  >= V_BASE_MONDAY_YYYYMMDD
                    AND A.PLAN_TYPE             = 'FN'
                    AND B.YYYYMMDD             >= P_FROM_YYYYMMDD
                    AND B.YYYYMMDD             <= P_TO_YYYYMMDD
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR B.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR B.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR B.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
               )  XA
         GROUP BY DIVISION_ID
                , PLAN_START_YYYYMMDD
                , PLAN_TYPE
                , NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */
                , FCST_TYPE
                , ITEM_ID
                , TO_SITE
                , INCOTERMS
                , FROM_SITE
                , TRANSPORT_MODE
                , BOD_ID
                , MEASURE
                , YYYYMMDD;

        /*---------------------------------------------
         * 1. SCP Plan : SCP(Weekly) plant향 Shipment Plan
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_PLAN
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DIVISION_ID
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , TR_MODE
             , INCOTERMS
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , PROJECT_CODE
             , FCST_TYPE
             , SEQ
          FROM ( SELECT SP.DIVISION_ID
                      , SP.ITEM_ID
                      , SP.FROM_SITE
                      , SP.TO_SITE
                      , BOD.TRANSPORT_MODE                    AS TR_MODE
                      , BOD.INCOTERMS                         AS INCOTERMS
                      , BOD.BOD_ID                            AS BOD_ID     /* BOD 2단계 개발 */
                      , 'SCP_PLAN'                            AS MEASURE
                      , SP.YYYYMMDD
                      , SP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 1                                     AS SEQ
                      , TO_DATE(SP.YYYYMMDD, 'YYYYMMDD') - TO_DATE(PV.PLAN_START_YYYYMMDD, 'YYYYMMDD')   AS DAY_GAP
                      , CASE WHEN V_SCP_PLAN_START_YYYYMMDD = PV.PLAN_START_YYYYMMDD THEN 0 ELSE 1 END   AS FLAG
                   FROM SCP_ANL_SHIPMENT_PLAN_SEMI   SP
                      , ( SELECT DIVISION_ID
                               , PLAN_START_YYYYMMDD
                               , PLAN_TYPE
                               , PLAN_SEQ
                               , PLAN_ID
                               , MODELING_ID
                               , SORT_SEQ
                               , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID
                                                    ORDER BY PLAN_START_YYYYMMDD DESC, SORT_SEQ ASC, PLAN_SEQ DESC) AS ROW_NUM
                            FROM ( SELECT DIVISION_ID
                                        , PLAN_START_YYYYMMDD
                                        , PLAN_TYPE
                                        , PLAN_SEQ
                                        , PLAN_ID
                                        , MODELING_ID
                                        , CASE WHEN PLAN_TYPE = 'PR' THEN 4
                                               WHEN PLAN_TYPE = 'MA' THEN 3
                                               WHEN PLAN_TYPE = 'SE' THEN 2
                                               WHEN PLAN_TYPE = 'FN' THEN 1
                                               ELSE 9
                                          END                                   AS SORT_SEQ
                                     FROM SCP_PLAN_VERSION_V
                                    WHERE DIVISION_ID          = P_DIVISION_ID
                                      AND PLAN_CYCLE           = 'WEEKLY'
                                      /* 191219 FN만 조회 */
                                      AND PLAN_TYPE            = 'FN'
                                      AND PLAN_START_YYYYMMDD >= V_BASE_MONDAY_YYYYMMDD
                                 )  SA
                        )  PV
                      , SCP_MST_BOD_N_V                BOD     /* BOD 2 단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v */
                      , SCM_MST_SITE                   FS
                      , SCM_MST_SITE                   TS
                  WHERE SP.DIVISION_ID          = PV.DIVISION_ID
                    AND SP.PLAN_START_YYYYMMDD  = PV.PLAN_START_YYYYMMDD
                    AND SP.PLAN_TYPE            = PV.PLAN_TYPE
                    AND SP.SEQ                  = PV.PLAN_SEQ
                    AND SP.DIVISION_ID          = BOD.DIVISION_ID
                    AND SP.BOD_ID               = BOD.BOD_ID
                    AND FS.DIVISION_ID          = SP.DIVISION_ID
                    AND FS.SCM_SITE_ID          = SP.FROM_SITE
                    AND TS.DIVISION_ID          = SP.DIVISION_ID
                    AND TS.SCM_SITE_ID          = SP.TO_SITE
                    AND SP.MEASURE              = 'SHIP_PLAN_AMEND'
                    AND SP.QTY                  > 0
                    AND SP.OPERATION_GROUP      = P_OPERATION_GROUP
                    AND SP.YYYYMMDD            >= P_FROM_YYYYMMDD
                    AND SP.YYYYMMDD            <= P_TO_YYYYMMDD
                    AND FS.VALID_YN             = 'Y'
                    AND TS.VALID_YN             = 'Y'
                    AND FS.PLANT_ID            <> TS.PLANT_ID
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                 UNION ALL
                 /* AS(Warranty Service) 적용 */
                 SELECT Y.DIVISION_ID
                      , Y.ITEM_ID
                      , Z.FROM_SITE
                      , Z.TO_SITE
                      , Z.TRANSPORT_MODE                      AS TR_MODE
                      , Z.INCOTERMS
                      , Z.BOD_ID
                      , 'SCP_PLAN'                            AS MEASURE
                      , Y.YYYYMMDD
                      , Y.QTY
                      , Y.PROJECT_CODE
                      , Y.FCST_TYPE
                      , 1                                     AS SEQ
                      , TO_DATE(Y.YYYYMMDD, 'YYYYMMDD') - TO_DATE(Y.PLAN_START_YYYYMMDD, 'YYYYMMDD')     AS DAY_GAP
                      , CASE WHEN V_SCP_PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD THEN 0 ELSE 1 END    AS FLAG
                   FROM ( SELECT X.DIVISION_ID
                               , X.ITEM_ID
                               , X.FROM_SITE
                               , X.TO_SITE
                               , X.PROJECT_CODE
                               , X.FCST_TYPE
                               , ( SELECT BOD_ID
                                     FROM ( SELECT BOD_ID
                                              FROM SCP_MST_BOD_N_V
                                             WHERE DIVISION_ID     = X.DIVISION_ID
                                               AND FROM_SITE       = X.FROM_SITE
                                               AND TO_SITE         = X.TO_SITE
                                               AND INCOTERMS       = X.INCOTERMS
                                               AND TRANSPORT_MODE  = X.TRANSPORT_MODE
                                               AND X.YYYYMMDD      BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD
                                               AND BOD_VALID_YN    = 'Y'
                                             ORDER BY PRIORITY )  SA
                                    WHERE ROWNUM = 1 )         AS BOD_ID   /* new bod for plant type */
                               , X.YYYYMMDD
                               , X.QTY
                               , X.PLAN_START_YYYYMMDD
                            FROM ( SELECT SP.DIVISION_ID
                                        , SP.ITEM_ID
                                        , SP.FROM_SITE
                                        , SP.PROJECT_CODE
                                        , SP.FCST_TYPE
                                        , L.SEGMENT2                        AS TO_SITE
                                        , BOD.TRANSPORT_MODE                AS TRANSPORT_MODE
                                        , BOD.INCOTERMS                     AS INCOTERMS
                                        , CASE WHEN BOD.SEGMENT3 = 'A' THEN SP.YYYYMMDD
                                               ELSE TO_CHAR(TO_DATE(SP.YYYYMMDD, 'YYYYMMDD') + BOD.BEFORE_LT, 'YYYYMMDD')
                                          END                               AS YYYYMMDD
                                        , SP.QTY
                                        , 1                                 AS SEQ
                                        , SP.PLAN_START_YYYYMMDD
                                     FROM GT_SSP0045_SHIPMENT_PLAN_FG       SP
                                        , SCP_MST_BOD_N_V                   BOD
                                        , SCM_MST_SITE                      FS
                                        , SCM_ADM_LOOKUP_MASTER_DETAIL      L
                                        , SCM_MST_SITE                      TS
                                    WHERE SP.DIVISION_ID       = BOD.DIVISION_ID
                                      AND SP.BOD_ID            = BOD.BOD_ID
                                      AND FS.DIVISION_ID       = SP.DIVISION_ID
                                      AND FS.SCM_SITE_ID       = SP.FROM_SITE
                                      AND L.SEGMENT1           = SP.TO_SITE
                                      AND L.SEGMENT3           = SP.DIVISION_ID
                                      AND TS.DIVISION_ID       = SP.DIVISION_ID
                                      AND TS.SCM_SITE_ID       = L.SEGMENT2
                                      AND FS.VALID_YN          = 'Y'
                                      AND FS.SITE_TYPE         = 'PLANT'
                                      AND FS.OPERATION_GROUP   = 'P'
                                      AND L.LOOKUP_TYPE        = 'AS_SITE_PLANT'
                                      AND L.VALID_YN           = 'Y'
                                      AND TS.SITE_TYPE         = 'PLANT'
                                      AND TS.OPERATION_GROUP   = 'W'
                                      AND TS.VALID_YN          = 'Y'
                                      AND VALIDATE_CONVERSION(SP.YYYYMMDD AS DATE, 'YYYYMMDD') = 1
                                 )  X
                        )  Y
                      , SCP_MST_BOD_N_V                Z
                  WHERE Y.BOD_ID = Z.BOD_ID
               )  AA
         WHERE ( AA.FLAG = 0 OR ( AA.FLAG = 1 AND AA.DAY_GAP < 7 ) );

        /*---------------------------------------------
         * 2. Ship Plan : SSP(Daily) Plant향 Shipment Plan
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_PLAN
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT SSP.DIVISION_ID
             , SSP.ITEM_ID
             , SSP.FROM_SITE
             , SSP.TO_SITE
             , BOD.TRANSPORT_MODE                             AS TR_MODE
             , BOD.INCOTERMS                                  AS INCOTERMS
             , BOD.BOD_ID                                     AS BOD_ID      /* BOD 2단계 개발 */
             , 'SHIP_PLAN'                                    AS MEASURE
             , SSP.YYYYMMDD
             , SSP.QTY
             , SSP.PROJECT_CODE
             , SSP.FCST_TYPE
             , 2                                              AS SEQ
          FROM SSP_ANL_SHIP_CONFIRM        SSP
             , SCP_MST_BOD_N_V             BOD                /* BOD 2 단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v */
             , SCM_MST_SITE                TS
             , SCM_MST_SITE                FS
         WHERE SSP.DIVISION_ID       = BOD.DIVISION_ID
           AND SSP.BOD_ID            = BOD.BOD_ID
           AND TS.DIVISION_ID        = SSP.DIVISION_ID
           AND TS.SCM_SITE_ID        = SSP.TO_SITE
           AND FS.DIVISION_ID        = SSP.DIVISION_ID
           AND FS.SCM_SITE_ID        = SSP.FROM_SITE
           AND TS.SITE_TYPE          = 'PLANT'
           AND TS.VALID_YN           = 'Y'
           AND FS.VALID_YN           = 'Y'
           AND TS.PLANT_ID          <> FS.PLANT_ID
           AND SSP.DIVISION_ID       = P_DIVISION_ID
           AND SSP.QTY               > 0
           AND SSP.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
           AND SSP.YYYYMMDD         <= P_TO_YYYYMMDD
           AND SSP.BIZ_TYPE          = P_OPERATION_GROUP
           AND SSP.CHANGE_TYPE       = 'C'
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR SSP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR SSP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR SSP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 2-1. ERP 출하실적
         *   ★AS-IS 가 CTE 두 벌(RESULT_ERP_C_EXIST · RESULT_ERP_C_NON)로 적던 구간을 인라인 뷰로 옮긴다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_PLAN_ERP_RESULT
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE                                    AS FROM_SITE
             , A.TO_SITE                                      AS TO_SITE
             , B.TR_MODE                                      AS TR_MODE
             , B.INCOTERMS                                    AS INCOTERMS
             , B.BOD_ID                                       AS BOD_ID
             , 'SHIP_PLAN'                                    AS MEASURE
             , A.YYYYMMDD                                     AS YYYYMMDD
             , A.QTY                                          AS QTY
             , B.PROJECT_CODE                                 AS PROJECT_CODE
             , B.FCST_TYPE                                    AS FCST_TYPE
             , 2                                              AS SEQ
          FROM ( /* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                 SELECT E.DIVISION_ID                         AS DIVISION_ID
                      , E.ITEM_ID                             AS ITEM_ID
                      , E.FROM_SCM_SITE_ID                    AS FROM_SITE
                      , E.TO_SCM_SITE_ID                      AS TO_SITE
                      , E.TRANSPORT_MODE                      AS TRANSPORT_MODE
                      /* E.INCOTERMS 대신 INCOTERMS는 DAP로 통일 */
                      , 'DAP'                                 AS INCOTERMS
                      , P.BOD_ID                              AS BOD_ID
                      , E.EXFACTORY_DATE                      AS YYYYMMDD
                      , SUM(E.EXFACTORY_QTY)                  AS QTY
                      , P.PROJECT_CODE                        AS PROJECT_CODE
                      , P.FCST_TYPE                           AS FCST_TYPE
                   FROM SCM_DNM_EXFACTORY_RESULT       E
                      , SCM_MST_SITE                   TS
                      , SCM_MST_SITE                   FS
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   L
                      , SSP_ANL_SHIP_CONFIRM           P
                  WHERE E.DIVISION_ID          = TS.DIVISION_ID
                    AND E.TO_SCM_SITE_ID       = TS.SCM_SITE_ID
                    AND E.DIVISION_ID          = FS.DIVISION_ID
                    AND E.FROM_SCM_SITE_ID     = FS.SCM_SITE_ID
                    AND L.SEGMENT1             = E.SSP_TYPE
                    AND P.DIVISION_ID          = E.DIVISION_ID
                    AND P.CONFIRM_ID           = E.CONFIRM_ID
                    AND TS.SITE_TYPE           = 'PLANT'
                    AND TS.VALID_YN            = 'Y'
                    AND TS.OPERATION_GROUP    <> 'E'
                    AND FS.VALID_YN            = 'Y'
                    AND FS.OPERATION_GROUP    <> 'E'
                    AND L.LOOKUP_TYPE          = 'ERP_SSP_TYPE'    /* LOOKUP에 등록된 공정만 */
                    AND L.VALID_YN             = 'Y'
                    AND P.YYYYMMDD             BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
                    /* D90: DO삭제 , D10:DO생성 */
                    AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')
                    AND E.CONFIRM_ID           LIKE 'C%'
                    AND E.EXFACTORY_DATE       BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR E.FROM_SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR E.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR E.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  GROUP BY E.DIVISION_ID
                         , E.CONFIRM_ID
                         , E.ORDER_NO
                         , E.EXFACTORY_DATE
                         , E.TRANSPORT_MODE
                         , E.INCOTERMS
                         , P.BOD_ID
                         , P.FCST_TYPE
                         , P.PROJECT_CODE
                         , E.ETA_DATE
                         , E.ETD_DATE
                         , E.FROM_SCM_SITE_ID
                         , E.TO_SCM_SITE_ID
                         , E.ITEM_ID
                 UNION ALL
                 /* ERP 출하실적에서 CONFIRM_ID 없는 실적 */
                 SELECT E.DIVISION_ID                         AS DIVISION_ID
                      , E.ITEM_ID                             AS ITEM_ID
                      , E.FROM_SCM_SITE_ID                    AS FROM_SITE
                      , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)    AS TO_SITE
                      , E.TRANSPORT_MODE                      AS TRANSPORT_MODE
                      /* E.INCOTERMS 대신 INCOTERMS는 DAP로 통일 */
                      , 'DAP'                                 AS INCOTERMS
                      , V.BOD_ID                              AS BOD_ID
                      , E.EXFACTORY_DATE                      AS YYYYMMDD
                      , SUM(E.EXFACTORY_QTY)                  AS QTY
                      , E.PROJECT_CODE                        AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                   FROM SCM_DNM_EXFACTORY_RESULT       E
                      , SCM_MST_SITE                   TS
                      , SCM_MST_SITE                   FS
                      , SCP_MST_BOD_N_V                V
                      , SCP_MST_FINAL_ITEM             F
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   L
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   L3
                  WHERE E.DIVISION_ID          = TS.DIVISION_ID
                    AND E.TO_SCM_SITE_ID       = TS.SCM_SITE_ID
                    AND E.DIVISION_ID          = FS.DIVISION_ID
                    AND E.FROM_SCM_SITE_ID     = FS.SCM_SITE_ID
                    AND V.DIVISION_ID          = E.DIVISION_ID
                    AND V.FROM_SITE            = E.FROM_SCM_SITE_ID
                    AND V.TO_SITE              = E.TO_SCM_SITE_ID
                    AND V.INCOTERMS            = E.INCOTERMS
                    AND V.TRANSPORT_MODE       = E.TRANSPORT_MODE
                    AND V.FROM_YYYYMMDD       >= E.EXFACTORY_DATE
                    AND V.TO_YYYYMMDD         <= E.EXFACTORY_DATE
                    AND F.ITEM_ID              = E.ITEM_ID     /* SCP 대상 ITEM만 */
                    AND F.DIVISION_ID          = E.DIVISION_ID
                    AND L.SEGMENT1             = E.ORDER_TYPE_CODE
                    AND L3.SEGMENT1(+)         = E.DIVISION_ID
                    AND L3.SEGMENT2(+)         = E.SOLDTO_CODE
                    AND L3.SEGMENT3(+)         = E.SHIPTO_CODE
                    /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                    AND L3.LOOKUP_TYPE(+)      = 'SHIP_RESULT_TO_SITE_MAPPING'
                    AND TS.SITE_TYPE           = 'PLANT'
                    AND TS.VALID_YN            = 'Y'
                    AND TS.OPERATION_GROUP    <> 'E'
                    AND FS.VALID_YN            = 'Y'
                    AND FS.OPERATION_GROUP    <> 'E'
                    /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                    AND L.LOOKUP_TYPE          = 'ERP_ORDER_TYPE'
                    AND L.VALID_YN             = 'Y'
                    /* D90: DO삭제 , D10:DO생성 */
                    AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')
                    AND E.EXFACTORY_DATE       BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
                    /* 상품창고제외 */
                    AND E.STORAGE_ID NOT IN (SELECT COLUMN_VALUE
                                               FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0045_GET_SHIPMENT_REQUEST', 'PRODUCT_STORAGE')))
                    /* 사외 창고 제외 LOOKUP 관리 */
                    AND NOT EXISTS (SELECT 1
                                      FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                     WHERE LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                       AND VALID_YN    = 'Y'
                                       AND SEGMENT1    = E.STORAGE_ID)
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR E.FROM_SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR E.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR E.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  GROUP BY E.DIVISION_ID
                         , E.ORDER_NO
                         , E.FROM_SCM_SITE_ID
                         , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)
                         , E.ITEM_ID
                         , E.EXFACTORY_DATE
                         , E.TRANSPORT_MODE
                         , E.INCOTERMS
                         , V.BOD_ID
                         , E.PROJECT_CODE
                         , E.ETA_DATE
                         , E.ETD_DATE
               )  A
             , ( SELECT DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , MAX(TR_MODE)                          AS TR_MODE
                      , MAX(INCOTERMS)                        AS INCOTERMS
                      , MAX(BOD_ID)                           AS BOD_ID
                      , MAX(PROJECT_CODE)                     AS PROJECT_CODE
                      , MAX(FCST_TYPE)                        AS FCST_TYPE
                   FROM GT_SSP0045_PLAN
                  GROUP BY DIVISION_ID
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE )  B
         WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
           AND A.FROM_SITE     = B.FROM_SITE(+)
           AND A.TO_SITE       = B.TO_SITE(+)
           AND A.ITEM_ID       = B.ITEM_ID(+);

        /*---------------------------------------------
         * 3. Ship Req : 출하 요청(Plant향 Ship Req)
         *               DM_PLN_SHIPMENT_REQ / MEASURE = 'SHIP_REQ'
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_REQ
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, RN, FROZEN_YYYYMMDD )
        SELECT R.DIVISION_ID
             , R.ITEM_ID
             , R.PLANT_SITE_ID                                AS FROM_SITE
             , R.SCM_SITE_ID                                  AS TO_SITE
             , R.TRANSPORT_MODE                               AS TR_MODE
             , R.INCOTERMS                                    AS INCOTERMS
             , R.BOD_ID                                       AS BOD_ID      /* BOD 2단계 개발 */
             , 'SHIP_REQ'                                     AS MEASURE
             , R.YYYYMMDD
             , R.QTY
             , R.PROJECT_CODE
             , R.FCST_TYPE
             , 3                                              AS SEQ
             , R.LAST_UPDATED_BY
             , RANK() OVER (PARTITION BY R.DIVISION_ID, R.ITEM_ID, R.PLANT_SITE_ID, R.SCM_SITE_ID
                                       , R.TRANSPORT_MODE, R.INCOTERMS
                            ORDER BY R.LAST_UPDATE_DATE DESC) AS RN
             /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]) */
             /* Ship Frozen구간 다음일자 */
             , TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                       + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, R.DIVISION_ID, R.PLANT_SITE_ID, V_PLAN_START_YYYYMMDD)
                       , 'YYYYMMDD')                          AS FROZEN_YYYYMMDD
          FROM DM_PLN_SHIPMENT_REQ         R
             , SCM_MST_SITE                FS
             , SCM_MST_SITE                TS
         WHERE R.DIVISION_ID       = FS.DIVISION_ID
           AND R.PLANT_SITE_ID     = FS.SCM_SITE_ID
           AND R.DIVISION_ID       = TS.DIVISION_ID
           AND R.SCM_SITE_ID       = TS.SCM_SITE_ID
           AND FS.SITE_TYPE        = 'PLANT'
           AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
           /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
           AND FS.VALID_YN         = 'Y'
           AND TS.SITE_TYPE        = 'PLANT'
           AND TS.VALID_YN         = 'Y'
           AND TS.PLANT_ID        <> FS.PLANT_ID
           AND R.DIVISION_ID       = P_DIVISION_ID
           AND R.MEASURE           = 'SHIP_REQ'               /* 확정 후 수정할 것 */
           AND R.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
           AND R.YYYYMMDD         <= P_TO_YYYYMMDD
           AND R.QTY               > 0
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR R.PLANT_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR R.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 3-1. OWMS 출하실적
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_REQ_OWMS
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, RN, FROZEN_YYYYMMDD )
        SELECT O.DIVISION_ID
             , O.ITEM_ID
             , O.FROM_SITE
             , O.TO_SITE
             , R.TR_MODE
             , R.INCOTERMS
             , R.BOD_ID
             , 'SHIP_REQ'                                     AS MEASURE
             , O.YYYYMMDD
             , O.QTY
             , R.PROJECT_CODE
             , R.FCST_TYPE
             , 3                                              AS SEQ
             , '-'                                            AS LAST_UPDATED_BY
             , '-'                                            AS RN
             /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
             /* Ship Frozen구간 다음일자 */
             , TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                       + FN_GET_ANL_SHIP_FROZEN_DAY_CNT('SSP', MS.DIVISION_ID, MS.SCM_SITE_ID, V_PLAN_START_YYYYMMDD)
                       , 'YYYYMMDD')                          AS FROZEN_YYYYMMDD
          FROM SSP_DNM_SHIP_RESULT_OWMS_V   O
             , SCM_MST_SITE                 MS
             , SCM_ADM_LOOKUP_MASTER_DETAIL L
             , SCM_MST_SITE                 FS
             , SCM_MST_SITE                 TS
             , ( SELECT DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , MAX(TR_MODE)                          AS TR_MODE
                      , MAX(INCOTERMS)                        AS INCOTERMS
                      , MAX(BOD_ID)                           AS BOD_ID
                      , MAX(PROJECT_CODE)                     AS PROJECT_CODE
                      , MAX(FCST_TYPE)                        AS FCST_TYPE
                   FROM GT_SSP0045_SHIP_REQ
                  GROUP BY DIVISION_ID
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE )  R
         WHERE MS.DIVISION_ID      = O.DIVISION_ID
           AND MS.SCM_SITE_ID      = O.FROM_SITE
           AND O.DIVISION_ID       = FS.DIVISION_ID
           AND O.FROM_SITE         = FS.SCM_SITE_ID
           AND O.DIVISION_ID       = TS.DIVISION_ID
           AND O.TO_SITE           = TS.SCM_SITE_ID
           AND R.DIVISION_ID(+)    = O.DIVISION_ID
           AND R.FROM_SITE(+)      = O.FROM_SITE
           AND R.TO_SITE(+)        = O.TO_SITE
           AND R.ITEM_ID(+)        = O.ITEM_ID
           AND MS.OPERATION_GROUP <> 'E'
           AND L.LOOKUP_TYPE       = 'SSP_SHIPMENT_RESULT_TYPE'   /* LOOKUP에 등록된 공정만 */
           AND L.SEGMENT1          = 'O'
           AND L.VALID_YN          = 'Y'
           AND FS.SITE_TYPE        = 'PLANT'
           AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
           AND FS.VALID_YN         = 'Y'
           AND TS.SITE_TYPE        = 'PLANT'
           AND TS.OPERATION_GROUP <> 'E'
           AND TS.VALID_YN         = 'Y'
           AND O.YYYYMMDD          BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR O.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR O.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR O.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 3-2. 필터
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_FILTER
        ( DIVISION_ID, ITEM_ID, FROM_SITE )
        SELECT DISTINCT
               DIVISION_ID
             , ITEM_ID
             , FROM_SITE
          FROM ( SELECT DISTINCT
                        DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                   FROM GT_SSP0045_PLAN
                  UNION
                 SELECT DISTINCT
                        DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                   FROM GT_SSP0045_SHIP_REQ )  A;

        /*---------------------------------------------
         * 3-3. [C20201016-000147] : 소형(40) 사업부 조회를 위한 기준 테이블 생성
         *      SSP_ANL_SHIP_PLAN_40 의 데이터 생성 시점이 달라 최신 생성 날짜를 조회한다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_40_STD
        ( DIVISION_ID, FROM_SITE, PLAN_START_YYYYMMDD )
        SELECT DISTINCT
               DIVISION_ID
             , FROM_SITE
             , PLAN_START_YYYYMMDD
          FROM ( SELECT SP.DIVISION_ID
                      , SP.FROM_SITE
                      , SP.PLAN_START_YYYYMMDD
                      , RANK() OVER (PARTITION BY SP.FROM_SITE ORDER BY SP.PLAN_START_YYYYMMDD DESC)  AS RANK_NO
                   FROM GT_SSP0045_FILTER         X1
                      , SSP_ANL_SHIP_PLAN_40      SP
                  WHERE X1.DIVISION_ID       = SP.DIVISION_ID
                    AND X1.FROM_SITE         = SP.FROM_SITE
                    AND X1.ITEM_ID           = SP.ITEM_ID
                    AND SP.DIVISION_ID       = P_DIVISION_ID
                    AND SP.PLAN_START_YYYYMMDD >= TO_CHAR(SYSDATE - 1, 'YYYYMMDD')      /* 전일 */
                    AND SP.PLAN_START_YYYYMMDD <= TO_CHAR(SYSDATE, 'YYYYMMDD')          /* 당일 */
                    AND SP.MEASURE           IN ('POSTP_PLAN', 'WH_IN', 'WH_STOCK')
                    AND SP.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                    AND SP.YYYYMMDD         <= P_TO_YYYYMMDD
                    AND SP.QTY               > 0
                    AND SP.DIVISION_ID       = '40'
               )  A
         WHERE RANK_NO = 1;

        /*---------------------------------------------
         * 4. ROW DATA 생성
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT TOT.DIVISION_ID
             , TOT.ITEM_ID
             , MAX(NVL(I.NICK_NAME, ' '))                     AS NICK_NAME
             , TOT.FROM_SITE
             , TOT.TO_SITE
             , TOT.TR_MODE
             , TOT.INCOTERMS
             , TOT.BOD_ID                                     AS BOD_ID      /* BOD 2단계 개발 */
             , TO_CHAR(MAX(NVL(BOD.LT_TOTAL, 0)))             AS LT_DAY
             , TOT.MEASURE
             , TOT.YYYYMMDD
             /* ★AS-IS 는 이 UNION ALL 에 소수 자리가 0 인 특성계획 수량(NUMERIC(38,0))이 섞여 있어
                MSSQL 이 묶음 전체의 소수 자리를 0 으로 정한다. 그 결과 모든 갈래의 수량이
                행 단위로 반올림된 뒤 합산된다(실측 : 24043.41192 -> 24043 · 48086.82336 -> 48087).
                TO-BE 의 NUMBER 에는 그 제약이 없으므로 같은 값을 내려면 반올림을 그대로 둔다 */
             , SUM(ROUND(TOT.QTY, 0))                         AS QTY
             , TOT.PROJECT_CODE
             , TOT.FCST_TYPE
             , TOT.SEQ
          FROM ( /* 1.SCP PLAN & 2.SHIP PLAN 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ
                   FROM GT_SSP0045_PLAN_ERP_RESULT
                  UNION ALL
                 /* 1.SCP PLAN & 2.SHIP PLAN 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ
                   FROM GT_SSP0045_PLAN
                  UNION ALL
                 /* 2.SHIP PLAN 추가 - Ship Frozen 이후 구간은 Ship Req의 수량을 더해준다. */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , 'SHIP_PLAN'                           AS MEASURE
                      , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE
                      , 2                                     AS SEQ
                   FROM GT_SSP0045_SHIP_REQ
                  WHERE YYYYMMDD >= FROZEN_YYYYMMDD
                  UNION ALL
                 /* 3.SHIP REQ 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE
                      , 3                                     AS SEQ
                   FROM GT_SSP0045_SHIP_REQ_OWMS
                  UNION ALL
                 /* 3.SHIP REQ 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE
                      , 3                                     AS SEQ
                   FROM GT_SSP0045_SHIP_REQ
                  UNION ALL
                 /*---------------------------------------------
                  * 4. Customer Plan : SSP(Daily) From Plant 기준 Sales향 Shipment Plan
                  *---------------------------------------------*/
                 SELECT SSP.DIVISION_ID
                      , SSP.ITEM_ID
                      , SSP.FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'CUST_PLAN'                           AS MEASURE
                      , SSP.YYYYMMDD
                      , SSP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 4                                     AS SEQ
                   FROM SSP_ANL_SHIP_CONFIRM      SSP
                      , SCP_MST_BOD_N_V           BOD         /* BOD 2단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v */
                      , SCM_MST_SITE              TS
                      , GT_SSP0045_FILTER         F
                  WHERE SSP.DIVISION_ID     = BOD.DIVISION_ID
                    AND SSP.BOD_ID          = BOD.BOD_ID
                    AND SSP.DIVISION_ID     = TS.DIVISION_ID
                    AND SSP.TO_SITE         = TS.SCM_SITE_ID
                    AND SSP.DIVISION_ID     = F.DIVISION_ID
                    AND SSP.ITEM_ID         = F.ITEM_ID
                    AND SSP.FROM_SITE       = F.FROM_SITE
                    AND TS.SITE_TYPE        = 'SALES'
                    AND TS.VALID_YN         = 'Y'
                    AND SSP.DIVISION_ID     = P_DIVISION_ID
                    AND SSP.QTY             > 0
                    AND SSP.YYYYMMDD       >= V_PLAN_START_YYYYMMDD
                    AND SSP.YYYYMMDD       <= P_TO_YYYYMMDD
                    AND SSP.BIZ_TYPE        = P_OPERATION_GROUP
                    AND SSP.CHANGE_TYPE     = 'C'
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SSP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SSP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SSP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /*---------------------------------------------
                  * 5. Customer Req : 출하 요청(From Plant 기준 Sales향 Ship Req)
                  *                   DM_PLN_SHIPMENT_REQ / MEASURE = 'SHIP_REQ'
                  *---------------------------------------------*/
                 SELECT R.DIVISION_ID
                      , R.ITEM_ID
                      , R.PLANT_SITE_ID                       AS FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'CUST_REQ'                            AS MEASURE
                      , R.YYYYMMDD
                      , R.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 5                                     AS SEQ
                   FROM DM_PLN_SHIPMENT_REQ       R
                      , SCM_MST_SITE              FS
                      , SCM_MST_SITE              TS
                      , GT_SSP0045_FILTER         F
                  WHERE R.DIVISION_ID       = FS.DIVISION_ID
                    AND R.PLANT_SITE_ID     = FS.SCM_SITE_ID
                    AND R.DIVISION_ID       = TS.DIVISION_ID
                    AND R.SCM_SITE_ID       = TS.SCM_SITE_ID
                    AND R.DIVISION_ID       = F.DIVISION_ID
                    AND R.ITEM_ID           = F.ITEM_ID
                    AND R.PLANT_SITE_ID     = F.FROM_SITE
                    AND FS.SITE_TYPE        = 'PLANT'
                    AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
                    /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
                    AND FS.VALID_YN         = 'Y'
                    AND TS.SITE_TYPE        = 'SALES'
                    AND TS.VALID_YN         = 'Y'
                    AND R.DIVISION_ID       = P_DIVISION_ID
                    AND R.MEASURE           = 'SHIP_REQ'
                    AND R.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                    AND R.YYYYMMDD         <= P_TO_YYYYMMDD
                    AND R.QTY               > 0
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR R.PLANT_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR R.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /*---------------------------------------------
                  * 6. Internal movement
                  *---------------------------------------------*/
                 SELECT P.DIVISION_ID
                      , P.ITEM_ID
                      , FS.SCM_SITE_ID                        AS FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INTN_MOVEMENT'                       AS MEASURE
                      , TO_CHAR(P.PLAN_DATE, 'YYYYMMDD')      AS YYYYMMDD
                      , P.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 6                                     AS SEQ
                   FROM SCM_DNM_CELL_INHOUSE_PLAN_SN   P
                      , SCM_MST_SITE                   FS
                      , GT_SSP0045_FILTER              F
                  WHERE P.DIVISION_ID       = FS.DIVISION_ID
                    AND P.PLANT_ID          = FS.PLANT_ID
                    AND P.DIVISION_ID       = F.DIVISION_ID
                    AND P.ITEM_ID           = F.ITEM_ID
                    AND FS.SCM_SITE_ID      = F.FROM_SITE
                    AND FS.SITE_TYPE        = 'PLANT'
                    AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
                    /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
                    AND FS.VALID_YN         = 'Y'
                    AND P.DIVISION_ID       = P_DIVISION_ID
                    AND P.CATEGORY          = 'MOVING'
                    AND P.PLAN_DATE        >= TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                    AND P.PLAN_DATE        <= TO_DATE(P_TO_YYYYMMDD, 'YYYYMMDD')
                    AND P.QTY               > 0
                    AND P.DIVISION_ID      <> '40'            /* [C20201016-000147] : 소형(40) 제외,KHJ79 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR FS.SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR P.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR P.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /* [C20201016-000147] : 소형(40) 사업부 추가, KHJ79 */
                 SELECT SP.DIVISION_ID
                      , SP.ITEM_ID
                      , SP.FROM_SITE
                      , SP.TO_SITE
                      , SP.TRANSPORT_MODE                     AS TR_MODE
                      , SP.INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INTN_MOVEMENT'                       AS MEASURE
                      , SP.YYYYMMDD
                      , SP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 6                                     AS SEQ
                   FROM SSP_ANL_SHIP_PLAN_40        SP
                      , SCM_MST_SITE                FS
                      , GT_SSP0045_FILTER           F
                      , GT_SSP0045_40_STD           ST
                  WHERE SP.DIVISION_ID          = FS.DIVISION_ID
                    AND SP.FROM_SITE            = FS.SCM_SITE_ID
                    AND SP.DIVISION_ID          = F.DIVISION_ID
                    AND SP.ITEM_ID              = F.ITEM_ID
                    AND SP.FROM_SITE            = F.FROM_SITE
                    AND ST.DIVISION_ID          = SP.DIVISION_ID
                    AND ST.FROM_SITE            = SP.FROM_SITE
                    AND ST.PLAN_START_YYYYMMDD  = SP.PLAN_START_YYYYMMDD
                    AND FS.SITE_TYPE            = 'PLANT'
                    /* 2021.10.21 : W/S AS 수정 , OPERATION_GROUP 파라미터 처리 및 OSP_YN 조건 제거 */
                    AND FS.OPERATION_GROUP      = P_OPERATION_GROUP
                    AND FS.VALID_YN             = 'Y'
                    AND SP.MEASURE              = 'POSTP_PLAN'
                    AND SP.DIVISION_ID          = P_DIVISION_ID
                    AND SP.YYYYMMDD            >= V_PLAN_START_YYYYMMDD
                    AND SP.YYYYMMDD            <= P_TO_YYYYMMDD
                    AND SP.QTY                  > 0
                    AND SP.DIVISION_ID          = '40'        /* 소형(40) 인 경우만 조회 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /*---------------------------------------------
                  * 7. Inspection plan : FP 특성계획
                  *---------------------------------------------*/
                 SELECT FP.DIVISION_ID
                      , FP.ITEM_ID
                      , FP.SCM_SITE_ID                        AS FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INSP_PLAN'                           AS MEASURE
                      , TO_CHAR(FP.PLAN_DATE, 'YYYYMMDD')     AS YYYYMMDD
                      , FP.PLAN_QTY                           AS QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 7                                     AS SEQ
                   FROM SCM_DNM_PLAN_FROZEN_V       FP
                      , SCM_MST_SITE                FS
                      , GT_SSP0045_FILTER           F
                  WHERE FP.DIVISION_ID      = FS.DIVISION_ID
                    AND FP.SCM_SITE_ID      = FS.SCM_SITE_ID
                    AND FP.DIVISION_ID      = F.DIVISION_ID
                    AND FP.ITEM_ID          = F.ITEM_ID
                    AND FP.SCM_SITE_ID      = F.FROM_SITE
                    AND FS.SITE_TYPE        = 'PLANT'
                    AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
                    /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
                    AND FS.VALID_YN         = 'Y'
                    AND FP.DIVISION_ID      = P_DIVISION_ID
                    AND FP.PLAN_DATE       >= TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                    AND FP.PLAN_DATE       <= TO_DATE(P_TO_YYYYMMDD, 'YYYYMMDD')
                    AND FP.PLAN_QTY         > 0
                    AND FP.PLAN_IN_QTY      > 0
                    /* (참고) division_id <> '40' 일때는 'F6000' 데이터만 존재하므로 operation_id 조건에'F5300', 'F5500', 'F5600' 도 포함시켜도 상관없음 */
                    AND FP.OPERATION_ID IN (SELECT SEGMENT1
                                              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                             WHERE LOOKUP_TYPE = 'OPERATION_CHAR'
                                               AND VALID_YN    = 'Y')
                    AND FP.DIVISION_ID     <> '40'            /* C20201016-000147 : 소형(40) 제외,KHJ79 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR FP.SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR FP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR FP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /* [C20201016-000147] : 소형(40) 사업부 추가, KHJ79 */
                 SELECT SP.DIVISION_ID
                      , SP.ITEM_ID
                      , SP.FROM_SITE
                      , SP.TO_SITE
                      , SP.TRANSPORT_MODE                     AS TR_MODE
                      , SP.INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INSP_PLAN'                           AS MEASURE
                      , SP.YYYYMMDD
                      , SP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 7                                     AS SEQ
                   FROM SSP_ANL_SHIP_PLAN_40        SP
                      , SCM_MST_SITE                FS
                      , GT_SSP0045_FILTER           F
                      , GT_SSP0045_40_STD           ST
                  WHERE SP.DIVISION_ID          = FS.DIVISION_ID
                    AND SP.FROM_SITE            = FS.SCM_SITE_ID
                    AND SP.DIVISION_ID          = F.DIVISION_ID
                    AND SP.ITEM_ID              = F.ITEM_ID
                    AND SP.FROM_SITE            = F.FROM_SITE
                    AND ST.DIVISION_ID          = SP.DIVISION_ID
                    AND ST.FROM_SITE            = SP.FROM_SITE
                    AND ST.PLAN_START_YYYYMMDD  = SP.PLAN_START_YYYYMMDD
                    AND FS.SITE_TYPE            = 'PLANT'
                    /* 2021.10.21 : W/S AS 수정 , OPERATION_GROUP 파라미터 처리 및 OSP_YN 조건 제거 */
                    AND FS.OPERATION_GROUP      = P_OPERATION_GROUP
                    AND FS.VALID_YN             = 'Y'
                    AND SP.MEASURE              = 'WH_IN'
                    AND SP.DIVISION_ID          = P_DIVISION_ID
                    AND SP.YYYYMMDD            >= V_PLAN_START_YYYYMMDD
                    AND SP.YYYYMMDD            <= P_TO_YYYYMMDD
                    AND SP.QTY                  > 0
                    AND SP.DIVISION_ID          = '40'        /* 소형(40) 인 경우만 조회 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
               )  TOT
             , SCP_MST_BOD_N_V         BOD           /* BOD 2단계 개발 : FROM , TO 조건 추가 */
             -- 2026.10.06 AJS 약칭 묶음을 이번 조회 품목으로 한정 (결과 동일) (START)
--             , ( SELECT ITEM_ID
--                      , MAX(NICK_NAME)                        AS NICK_NAME
--                   FROM SCM_MST_ITEM_SN
--                  WHERE NICK_NAME IS NOT NULL
--                  GROUP BY ITEM_ID )  I
             , ( SELECT ITEM_ID
                      , MAX(NICK_NAME)                        AS NICK_NAME
                   FROM SCM_MST_ITEM_SN
                  WHERE NICK_NAME IS NOT NULL
                    AND ITEM_ID IN (SELECT XA.ITEM_ID
                                      FROM GT_SSP0045_PLAN_ERP_RESULT XA
                                     UNION ALL
                                    SELECT XB.ITEM_ID
                                      FROM GT_SSP0045_PLAN XB
                                     UNION ALL
                                    SELECT XC.ITEM_ID
                                      FROM GT_SSP0045_SHIP_REQ XC
                                     UNION ALL
                                    SELECT XD.ITEM_ID
                                      FROM GT_SSP0045_SHIP_REQ_OWMS XD
                                     UNION ALL
                                    SELECT XE.ITEM_ID
                                      FROM GT_SSP0045_FILTER XE)
                  GROUP BY ITEM_ID )  I
             -- 2026.10.06 AJS 약칭 묶음을 이번 조회 품목으로 한정 (결과 동일) (END)
         WHERE TOT.DIVISION_ID   = BOD.DIVISION_ID(+)
           AND TOT.BOD_ID        = BOD.BOD_ID(+)
           AND TOT.ITEM_ID       = I.ITEM_ID(+)
         GROUP BY TOT.DIVISION_ID
                , TOT.ITEM_ID
                , TOT.FROM_SITE
                , TOT.TO_SITE
                , TOT.TR_MODE
                , TOT.INCOTERMS
                , TOT.MEASURE
                , TOT.YYYYMMDD
                , TOT.PROJECT_CODE
                , TOT.FCST_TYPE
                , TOT.SEQ
                , TOT.BOD_ID;                                  /* BOD 2단계 개발 */

        /* LT DAY 삭제 */
        UPDATE GT_SSP0045_SHIP_ROW
           SET LT_DAY = '-'
         WHERE MEASURE IN ('CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN');

        /*---------------------------------------------
         * 5. STOCK INV
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_STOCK
        ( DIVISION_ID, ITEM_ID, FROM_SITE, YYYYMMDD, QTY )
        SELECT INV.DIVISION_ID
             , INV.ITEM_ID
             , INV.SCM_SITE_ID                                AS FROM_SITE
             , V_PLAN_START_YYYYMMDD                          AS YYYYMMDD
             , INV.SSP_QTY                                    AS QTY         /* SSP용 dbo.SSP_DNM_STOCK_C */
          FROM SSP_DNM_STOCK_C        INV
             , ( SELECT DIVISION_ID
                      , SITE_ID
                      , MAX(CUTOFF_DATE)                      AS MAX_CUTOFF_DATE
                   FROM SSP_DNM_STOCK_C
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    /* ★AS-IS 는 문자끼리 견주나 TO-BE 의 CUTOFF_DATE 는 날짜 칸이라 형을 맞춘다 */
                    AND CUTOFF_DATE  > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')       /* 현재일 - 3 */
                    AND CUTOFF_DATE <= TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')  /* 변수 : 현재일 */
                  GROUP BY DIVISION_ID
                         , SITE_ID )  MS
             , ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , OPERATION_GROUP
                      , SITE_TYPE
                   FROM SCM_MST_SITE
                  WHERE DIVISION_ID      = P_DIVISION_ID
                    AND SITE_TYPE        = 'PLANT'
                    AND OPERATION_GROUP  = P_OPERATION_GROUP                 /* Cell Plant Site */
                    AND VALID_YN         = 'Y' )  B
             , ( SELECT DISTINCT
                        A.STORAGE_ID
                      , A.LOCATION_CODE
                      , A.SCM_SITE_ID
                      , A.DIVISION_ID
                      , A.OPERATION_ID
                   FROM SCM_MST_LOCATION   A
                      , SCM_MST_SITE       SB
                  WHERE A.SCM_SITE_ID      = SB.SCM_SITE_ID
                    AND SB.DIVISION_ID     = P_DIVISION_ID
                    AND SB.VALID_YN        = 'Y'
                    AND SB.OPERATION_GROUP = P_OPERATION_GROUP               /* Cell Plant Site */
                    AND A.DIVISION_ID      = P_DIVISION_ID
                    AND A.VALID_YN         = 'Y'
                    /* 2019.10.31 BOH(STOCK_V) 조회 시 FORMATION_CHECK_PACKAGING 재고 포함 */
                    /* Cell 특성완료 이후 창고 */
                    AND A.LOCATION_CODE IN ('CELL_OWMS', 'FORMATION_CHECK_PACKAGING')
                    AND ( A.STORAGE_ID IS NOT NULL OR A.OPERATION_ID IS NOT NULL ) )  C
         WHERE INV.DIVISION_ID   = MS.DIVISION_ID
           AND INV.SITE_ID       = MS.SITE_ID
           AND INV.CUTOFF_DATE   = MS.MAX_CUTOFF_DATE
           AND INV.DIVISION_ID   = B.DIVISION_ID
           AND INV.SCM_SITE_ID   = B.SCM_SITE_ID
           AND INV.DIVISION_ID   = C.DIVISION_ID
           AND INV.SCM_SITE_ID   = C.SCM_SITE_ID
           AND ( INV.STORAGE_ID  = C.STORAGE_ID OR INV.OPERATION_ID = C.OPERATION_ID )
           AND INV.CUTOFF_DATE   > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')
           AND P_DIVISION_ID    <> '40'                       /* [C20201016-000147] : 소형(40) 사업부 제외 ,khj79 */
         UNION ALL
        /* [C20201016-000147] : 소형(40) 사업부 추가, khj79 */
        SELECT SP.DIVISION_ID
             , SP.ITEM_ID
             , SP.FROM_SITE
             , SP.YYYYMMDD
             , SP.QTY
          FROM SSP_ANL_SHIP_PLAN_40        SP
             , SCM_MST_SITE                FS
             , GT_SSP0045_FILTER           F
             , GT_SSP0045_40_STD           ST
         WHERE SP.DIVISION_ID          = FS.DIVISION_ID
           AND SP.FROM_SITE            = FS.SCM_SITE_ID
           AND SP.DIVISION_ID          = F.DIVISION_ID
           AND SP.ITEM_ID              = F.ITEM_ID
           AND SP.FROM_SITE            = F.FROM_SITE
           AND ST.DIVISION_ID          = SP.DIVISION_ID
           AND ST.FROM_SITE            = SP.FROM_SITE
           AND ST.PLAN_START_YYYYMMDD  = SP.PLAN_START_YYYYMMDD
           AND FS.SITE_TYPE            = 'PLANT'
           /* 2021.10.21 : W/S AS 수정 , OPERATION_GROUP 파라미터 처리 및 OSP_YN 조건 제거 */
           AND FS.OPERATION_GROUP      = P_OPERATION_GROUP
           AND FS.VALID_YN             = 'Y'
           AND SP.MEASURE              = 'WH_STOCK'
           AND SP.DIVISION_ID          = P_DIVISION_ID
           AND SP.YYYYMMDD             = V_PLAN_START_YYYYMMDD
           AND SP.QTY                  > 0
           AND SP.DIVISION_ID          = '40'                 /* 소형(40) 인 경우만 조회 */
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 6. 일자별 BOH 계산
         *   ★AS-IS 가 CTE 세 벌(Z · QTY · BOH)로 적던 구간을 인라인 뷰로 옮긴다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_CAL_QTY
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, YYYYMMDD, PLAN_QTY, REQ_QTY )
        SELECT Z.DIVISION_ID
             , Z.ITEM_ID
             , Z.NICK_NAME
             , Z.FROM_SITE
             , Z.YYYYMMDD
             , ( SELECT NVL(SUM(X.PLAN_QTY), 0)
                   FROM ( SELECT DIVISION_ID
                               , ITEM_ID
                               , FROM_SITE
                               , YYYYMMDD
                               , NVL(SUM(CASE WHEN MEASURE = 'SHIP_PLAN'     THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'CUST_PLAN'     THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INTN_MOVEMENT' THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INSP_PLAN'     THEN NVL(QTY, 0)
                                              ELSE 0.0
                                         END), 0)                            AS PLAN_QTY
                            FROM GT_SSP0045_SHIP_ROW
                           WHERE MEASURE IN ('SHIP_PLAN', 'SHIP_REQ', 'CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN')
                             AND YYYYMMDD >= V_PLAN_START_YYYYMMDD
                             AND YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY DIVISION_ID
                                  , ITEM_ID
                                  , FROM_SITE
                                  , YYYYMMDD )  X
                  WHERE X.DIVISION_ID = Z.DIVISION_ID
                    AND X.ITEM_ID     = Z.ITEM_ID
                    AND X.FROM_SITE   = Z.FROM_SITE
                    AND X.YYYYMMDD    < Z.YYYYMMDD ) + NVL(BOH.QTY, 0)       AS PLAN_QTY
             , ( SELECT NVL(SUM(X.REQ_QTY), 0)
                   FROM ( SELECT DIVISION_ID
                               , ITEM_ID
                               , FROM_SITE
                               , YYYYMMDD
                               , NVL(SUM(CASE WHEN MEASURE = 'SHIP_REQ'      THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'CUST_REQ'      THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INTN_MOVEMENT' THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INSP_PLAN'     THEN NVL(QTY, 0)
                                              ELSE 0.0
                                         END), 0)                            AS REQ_QTY
                            FROM GT_SSP0045_SHIP_ROW
                           WHERE MEASURE IN ('SHIP_PLAN', 'SHIP_REQ', 'CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN')
                             AND YYYYMMDD >= V_PLAN_START_YYYYMMDD
                             AND YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY DIVISION_ID
                                  , ITEM_ID
                                  , FROM_SITE
                                  , YYYYMMDD )  X
                  WHERE X.DIVISION_ID = Z.DIVISION_ID
                    AND X.ITEM_ID     = Z.ITEM_ID
                    AND X.FROM_SITE   = Z.FROM_SITE
                    AND X.YYYYMMDD    < Z.YYYYMMDD ) + NVL(BOH.QTY, 0)       AS REQ_QTY
          FROM ( SELECT DISTINCT
                        R.DIVISION_ID
                      , R.ITEM_ID
                      , R.NICK_NAME
                      , R.FROM_SITE
                      , O.BASIS_YYYYMMDD                      AS YYYYMMDD
                   FROM SCM_SYS_CALENDAR_M    O
                      , ( SELECT DISTINCT
                                 DIVISION_ID
                               , ITEM_ID
                               , NICK_NAME
                               , FROM_SITE
                            FROM GT_SSP0045_SHIP_ROW )  R
                  WHERE O.BASIS_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                    AND O.BASIS_YYYYMMDD <= P_TO_YYYYMMDD )  Z
             , ( SELECT V.DIVISION_ID
                      , V.ITEM_ID
                      , V.FROM_SITE
                      , SUM(V.QTY)                            AS QTY
                   FROM ( SELECT INV.DIVISION_ID
                               , INV.ITEM_ID
                               , INV.FROM_SITE
                               , INV.YYYYMMDD
                               , INV.QTY                                     /* SSP용 */
                            FROM GT_SSP0045_STOCK      INV                   /* 20200401 속도개선. TEMP Table 사용. */
                               , SCP_MST_FINAL_ITEM    FI
                           WHERE INV.DIVISION_ID    = FI.DIVISION_ID
                             AND INV.ITEM_ID        = FI.ITEM_ID
                             AND FI.OPERATION_GROUP = P_OPERATION_GROUP
                             AND ( TRIM(P_SCM_SITE_ID) IS NULL
                                   OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                                   OR INV.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                             AND ( TRIM(P_ITEM_ID) IS NULL
--                                 OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                                   OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                 OR INV.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                                   OR INV.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                        )  V
                  GROUP BY V.DIVISION_ID
                         , V.ITEM_ID
                         , V.FROM_SITE )  BOH
         WHERE Z.DIVISION_ID = BOH.DIVISION_ID(+)
           AND Z.ITEM_ID     = BOH.ITEM_ID(+)
           AND Z.FROM_SITE   = BOH.FROM_SITE(+);

        /*---------------------------------------------
         * 8. W/H BOH(Plan) : Cell Plant의 Cell 재고
         *    일자별 BOH 계산  : BOH(D+1) = BOH(D) - Ship Plan(D) - Customer Plan(D) - Internal movement(D) + Inspection Plan(D)
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DIVISION_ID
             , ITEM_ID
             , NICK_NAME
             , FROM_SITE
             , '-'                                            AS TO_SITE
             , '-'                                            AS TR_MODE
             , '/'                                            AS INCOTERMS
             , '-'                                            AS BOD_ID      /* BOD 2단계 개발 */
             , '-'                                            AS LT_DAY
             , 'WH_BOH_PLAN'                                  AS MEASURE
             , YYYYMMDD
             , NVL(PLAN_QTY, 0)                               AS QTY
             , '/'                                            AS PROJECT_CODE
             , '/'                                            AS FCST_TYPE
             , 8                                              AS SEQ
          FROM GT_SSP0045_CAL_QTY;

        /*---------------------------------------------
         * 9. W/H BOH(Req) : Cell Plant의 Cell 재고
         *    일자별 BOH 계산  : BOH(D+1) = BOH(D) - Ship Req(D) - Customer Req(D) - Internal movement(D) + Inspection Plan(D)
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DIVISION_ID
             , ITEM_ID
             , NICK_NAME
             , FROM_SITE
             , '-'                                            AS TO_SITE
             , '-'                                            AS TR_MODE
             , '/'                                            AS INCOTERMS
             , '-'                                            AS BOD_ID      /* BOD 2단계 개발 */
             , '-'                                            AS LT_DAY
             , 'WH_BOH_REQ'                                   AS MEASURE
             , YYYYMMDD
             , NVL(REQ_QTY, 0)                                AS QTY
             , '/'                                            AS PROJECT_CODE
             , '/'                                            AS FCST_TYPE
             , 9                                              AS SEQ
          FROM GT_SSP0045_CAL_QTY;

        /*---------------------------------------------
         * 10. Requestor
         *     2020.01.03  Requestor 조회 시 Last Updated By 가 scp_batch인 것은 제외
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_REQUESTOR
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE, LAST_UPDATED_BY )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.TR_MODE
             , A.INCOTERMS
             , A.BOD_ID                                       /* BOD 2단계 개발 */
             , A.MEASURE
             , A.LAST_UPDATED_BY
          FROM GT_SSP0045_SHIP_REQ    A
         WHERE A.RN = (SELECT NVL(MIN(B.RN), 1)
                         FROM GT_SSP0045_SHIP_REQ B
                        WHERE B.DIVISION_ID     = A.DIVISION_ID
                          AND B.ITEM_ID         = A.ITEM_ID
                          AND B.FROM_SITE       = A.FROM_SITE
                          AND B.TO_SITE         = A.TO_SITE
                          AND B.TR_MODE         = A.TR_MODE
                          AND B.INCOTERMS       = A.INCOTERMS
                          AND B.MEASURE         = A.MEASURE
                          AND B.LAST_UPDATED_BY <> 'scp_batch');

        /*---------------------------------------------
         * 11. UI용 Measure 추가
         *     MEASURE : SCP_PLAN, SHIP_PLAN, SHIP_REQ
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.FROM_SITE
             , A.TO_SITE
             , A.TR_MODE
             , A.INCOTERMS
             , A.BOD_ID                                       /* BOD 2단계 개발 */
             , A.LT_DAY
             , M.COLUMN_NAME                                  AS MEASURE
             , O.BASIS_YYYYMMDD
             , NULL                                           AS QTY
             , A.PROJECT_CODE                                 AS PROJECT_CODE
             , A.FCST_TYPE                                    AS FCST_TYPE
             , M.SORT_ORDER_NO                                AS SEQ
          FROM GT_SSP0045_SHIP_ROW        A
             , SCM_SYS_CALENDAR_M         O
             , SCM_MST_SHEET_MEASURE      M
         WHERE O.BASIS_YYYYMMDD  = V_PLAN_START_YYYYMMDD
           AND M.PROGRAM_ID      = P_PROGRAM_ID
           AND M.SHEET_NAME      = P_SHEET_NAME
           AND M.COLUMN_NAME     IN ('SCP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
           AND A.MEASURE         IN ('SCP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
           AND NOT EXISTS (SELECT 1
                             FROM GT_SSP0045_SHIP_ROW B
                            WHERE B.DIVISION_ID  = A.DIVISION_ID
                              AND B.ITEM_ID      = A.ITEM_ID
                              AND B.FROM_SITE    = A.FROM_SITE
                              AND B.TO_SITE      = A.TO_SITE
                              AND B.TR_MODE      = A.TR_MODE
                              AND B.INCOTERMS    = A.INCOTERMS
                              AND B.BOD_ID       = A.BOD_ID                  /* BOD 2단계 개발 */
                              AND B.PROJECT_CODE = A.PROJECT_CODE
                              AND B.FCST_TYPE    = A.FCST_TYPE
                              AND B.MEASURE      = M.COLUMN_NAME
                              AND B.YYYYMMDD     = O.BASIS_YYYYMMDD);

        /* MEASURE : CUST_PLAN, CUST_REQ, INTN_MOVEMENT, INSP_PLAN */
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.FROM_SITE
             , '-'                                            AS TO_SITE
             , '-'                                            AS TR_MODE
             , '/'                                            AS INCOTERMS
             , '-'                                            AS BOD_ID      /* BOD 2단계 개발 */
             , '-'                                            AS LT_DAY
             , M.COLUMN_NAME                                  AS MEASURE
             , O.BASIS_YYYYMMDD
             , NULL                                           AS QTY
             , '/'                                            AS PROJECT_CODE
             , '/'                                            AS FCST_TYPE
             , M.SORT_ORDER_NO                                AS SEQ
          FROM GT_SSP0045_SHIP_ROW        A
             , SCM_SYS_CALENDAR_M         O
             , SCM_MST_SHEET_MEASURE      M
         WHERE O.BASIS_YYYYMMDD  = V_PLAN_START_YYYYMMDD
           AND M.PROGRAM_ID      = P_PROGRAM_ID
           AND M.SHEET_NAME      = P_SHEET_NAME
           AND M.COLUMN_NAME     IN ('CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN')
           AND A.MEASURE         IN ('SCP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
           AND NOT EXISTS (SELECT 1
                             FROM GT_SSP0045_SHIP_ROW B
                            WHERE B.DIVISION_ID  = A.DIVISION_ID
                              AND B.ITEM_ID      = A.ITEM_ID
                              AND B.FROM_SITE    = A.FROM_SITE
                              AND B.TO_SITE      = '-'
                              AND B.TR_MODE      = '-'
                              AND B.INCOTERMS    = '/'
                              AND B.BOD_ID       = '-'                       /* BOD 2단계 개발 */
                              AND B.MEASURE      = M.COLUMN_NAME
                              AND B.YYYYMMDD     = O.BASIS_YYYYMMDD);

        /*---------------------------------------------
         * 12. PIVOT용 Data정리
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_PIVOT
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.FROM_SITE
             , A.TO_SITE
             , A.TR_MODE
             , A.INCOTERMS
             , NVL(NULLIF(RTRIM(A.BOD_ID),''), '/')                             AS BOD_ID      /* BOD 2단계 개발 */
             , A.LT_DAY
             , A.MEASURE
             , 'D_'||A.YYYYMMDD                               AS YYYYMMDD
             , O.BASIS_YYYYMM                                 AS YYYYMM
             , SUBSTR(O.BASIS_YYYYMM, -4)||O.ISO_WEEK         AS ISO_WEEK
             , A.QTY
             , A.PROJECT_CODE
             , A.FCST_TYPE
             , A.SEQ
          FROM GT_SSP0045_SHIP_ROW     A
             , SCM_SYS_CALENDAR_M      O
         WHERE A.YYYYMMDD = O.BASIS_YYYYMMDD;

        /*---------------------------------------------
         * 13. PIVOIT처리
         *     피벗 대상 날짜 칸 만들기 — 칸 수가 기간에 따라 달라지므로 이 부분만 동적 SQL
         *---------------------------------------------*/
        DBMS_LOB.CREATETEMPORARY(V_PIVOT, TRUE);
        FOR C IN ( SELECT YYYYMMDD
                     FROM ( SELECT 'W_'||BASIS_YYYYMM||ISO_WEEK          AS YYYYMMDD
                                 , BASIS_START_DATE||'21'                AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY BASIS_YYYYMM
                                    , ISO_WEEK
                                    , BASIS_START_DATE
                             UNION ALL
                            SELECT 'M_'||BASIS_YYYYMM                    AS YYYYMMDD
                                 , MIN(BASIS_START_DATE)||'01'           AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY BASIS_YYYYMM
                                    , MONTH_NAME
                             UNION ALL
                            SELECT 'D_'||BASIS_YYYYMMDD                  AS YYYYMMDD
                                 , BASIS_YYYYMMDD||'31'                  AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY BASIS_YYYYMMDD
                          )  IA
                    ORDER BY SORT_ORDER_NO )
        LOOP
            IF SUBSTR(C.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_PIVOT, ', SUM(CASE WHEN P.YYYYMM = '''||SUBSTR(C.YYYYMMDD, -6)
                                || ''' THEN P.QTY END) AS '||C.YYYYMMDD||CHR(10));
            ELSIF SUBSTR(C.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_PIVOT, ', SUM(CASE WHEN P.ISO_WEEK = '''||SUBSTR(C.YYYYMMDD, -6)
                                || ''' THEN P.QTY END) AS '||C.YYYYMMDD||CHR(10));
            ELSE
                DBMS_LOB.APPEND(V_PIVOT, ', SUM(CASE WHEN P.YYYYMMDD = '''||C.YYYYMMDD
                                || ''' THEN P.QTY END) AS '||C.YYYYMMDD||CHR(10));
            END IF;
        END LOOP;

        DBMS_LOB.CREATETEMPORARY(V_SQL, TRUE);
        DBMS_LOB.APPEND(V_SQL,
             'SELECT P.DIVISION_ID'||CHR(10)
          || '     , P.ITEM_ID'||CHR(10)
          || '     , NVL(NULLIF(P.NICK_NAME, '' ''), '' '') AS NICK_NAME'||CHR(10)
          || '     , P.FROM_SITE'||CHR(10)
          || '     , P.TO_SITE'||CHR(10)
          || '     , P.TR_MODE'||CHR(10)
          || '     , P.INCOTERMS'||CHR(10)
          || '     , P.BOD_ID'||CHR(10)                                      /* BOD 2단계 개발 */
          /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
          || '     , TO_CHAR(TO_DATE(:B_PLAN_START1, ''YYYYMMDD'')'||CHR(10)
          || '               + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(:B_APP_TYPE1, P.DIVISION_ID, P.FROM_SITE, :B_PLAN_START2)'||CHR(10)
          || '               , ''YYYYMMDD'') AS BOD_FROM_YYYYMMDD'||CHR(10)
          || '     , :B_TO_YYYYMMDD AS BOD_TO_YYYYMMDD'||CHR(10)             /* BOD 2단계 개발 */
          || '     , P.LT_DAY'||CHR(10)
          /* ★AS-IS 는 이어붙이는 값 하나라도 없으면 문장 전체가 빈 값이 된다. 그 동작을 맞춘다 */
          /* 2026.09.30 AJS 수정 (START) */
--          || '     , CASE WHEN C.USERNAME IS NULL OR C.USERID IS NULL THEN NULL'||CHR(10)
--          || '            ELSE C.USERNAME||''(''||C.USERID||'')'' END AS LAST_UPDATED_BY'||CHR(10)
          || '     , CASE WHEN C.USER_NM IS NULL OR C.USER_ID IS NULL THEN NULL'||CHR(10)
          || '            ELSE C.USER_NM||''(''||C.USER_ID||'')'' END AS LAST_UPDATED_BY'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '     , P.SEQ'||CHR(10)
          || '     , P.PROJECT_CODE'||CHR(10)
          || '     , P.FCST_TYPE'||CHR(10)
          || '     , TO_CHAR(TO_DATE(:B_PLAN_START3, ''YYYYMMDD'')'||CHR(10)
          || '               + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(:B_APP_TYPE2, P.DIVISION_ID, P.FROM_SITE, :B_PLAN_START4)'||CHR(10)
          || '               , ''YYYYMMDD'') AS FROZEN_YYYYMMDD'||CHR(10)
          || '     , M.ATTRIBUTE3 AS MEASURE_COLOR'||CHR(10)
          /* [C20201016-000147] : 소형(40) 사업부 추가 - 소형인 경우 MEASURE 명 변경 */
          || '     , CASE WHEN P.DIVISION_ID = ''40'' AND P.MEASURE = ''INSP_PLAN''     THEN ''WH in Plan'''||CHR(10)
          || '            WHEN P.DIVISION_ID = ''40'' AND P.MEASURE = ''INTN_MOVEMENT'' THEN ''Post Process Plan'''||CHR(10)
          || '            ELSE M.COLUMN_LABEL_NAME END AS MEASURE_LABEL'||CHR(10)
          || '     , P.MEASURE'||CHR(10));
        DBMS_LOB.APPEND(V_SQL, V_PIVOT);
        DBMS_LOB.APPEND(V_SQL,
             '  FROM GT_SSP0045_SHIP_PIVOT   P'||CHR(10)
          || '     , GT_SSP0045_REQUESTOR    R'||CHR(10)
          /* 2026.09.30 AJS 수정 (START) */
--          || '     , TB_FX_USER              C'||CHR(10)
          || '     , SCM_ADM_USER_M          C'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '     , SCP_MST_BOD_N_V         B'||CHR(10)                     /* BOD 2단계 개발 : FROM , TO 추가 */
          || '     , SCM_MST_SHEET_MEASURE   M'||CHR(10)
          || '     , SCM_MST_SITE            S'||CHR(10)
          || ' WHERE R.DIVISION_ID(+)   = P.DIVISION_ID'||CHR(10)
          || '   AND R.ITEM_ID(+)       = P.ITEM_ID'||CHR(10)
          || '   AND R.FROM_SITE(+)     = P.FROM_SITE'||CHR(10)
          || '   AND R.TO_SITE(+)       = P.TO_SITE'||CHR(10)
          || '   AND R.TR_MODE(+)       = P.TR_MODE'||CHR(10)
          || '   AND R.INCOTERMS(+)     = P.INCOTERMS'||CHR(10)
          || '   AND R.BOD_ID(+)        = P.BOD_ID'||CHR(10)                 /* BOD 2단계 개발 */
          || '   AND R.MEASURE(+)       = P.MEASURE'||CHR(10)
          /* 2026.09.30 AJS 수정 (START) */
--          || '   AND R.LAST_UPDATED_BY  = C.USERID(+)'||CHR(10)
          || '   AND R.LAST_UPDATED_BY  = C.USER_ID(+)'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '   AND P.BOD_ID           = B.BOD_ID(+)'||CHR(10)
          || '   AND M.COLUMN_NAME      = P.MEASURE'||CHR(10)
          || '   AND S.SCM_SITE_ID      = P.FROM_SITE'||CHR(10)
          || '   AND M.PROGRAM_ID       = :B_PGM'||CHR(10)
          || '   AND M.SHEET_NAME       = :B_SHT'||CHR(10)
          || '   AND S.DIVISION_ID      = :B_DIV'||CHR(10)
          || '   AND S.OPERATION_GROUP  = :B_OPGRP'||CHR(10)
          || '   AND S.SITE_TYPE        = ''PLANT'''||CHR(10)
          || '   AND S.VALID_YN         = ''Y'''||CHR(10)
          || ' GROUP BY P.DIVISION_ID, P.ITEM_ID, P.NICK_NAME, P.FROM_SITE, P.TO_SITE, P.TR_MODE, P.INCOTERMS'||CHR(10)
          /* 2026.09.30 AJS 수정 (START) */
--          || '        , P.LT_DAY, P.MEASURE, P.PROJECT_CODE, P.FCST_TYPE, P.SEQ, C.USERID, C.USERNAME'||CHR(10)
          || '        , P.LT_DAY, P.MEASURE, P.PROJECT_CODE, P.FCST_TYPE, P.SEQ, C.USER_ID, C.USER_NM'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '        , M.COLUMN_LABEL_NAME, S.SHIP_FROZEN, M.ATTRIBUTE3'||CHR(10)
          || '        , P.BOD_ID, B.TO_YYYYMMDD'||CHR(10)                    /* BOD 2단계 개발 */
          || ' ORDER BY FN_ASIS_SORT_KEY(P.DIVISION_ID) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.ITEM_ID) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.FROM_SITE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.TO_SITE) DESC NULLS LAST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.TR_MODE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.PROJECT_CODE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.FCST_TYPE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.BOD_ID) NULLS FIRST'||CHR(10)
          || '        , P.SEQ'||CHR(10));

        /* DEBUG QRY 출력 */
        IF DEBUG_MODE = 'T' THEN
            FOR I IN 0 .. TRUNC((DBMS_LOB.GETLENGTH(V_SQL) - 1) / 3000) LOOP
                DBMS_OUTPUT.PUT_LINE(DBMS_LOB.SUBSTR(V_SQL, 3000, I * 3000 + 1));
            END LOOP;
        END IF;

        OPEN O_RC1 FOR V_SQL
          USING V_PLAN_START_YYYYMMDD, V_APP_TYPE, V_PLAN_START_YYYYMMDD
              , P_TO_YYYYMMDD
              , V_PLAN_START_YYYYMMDD, V_APP_TYPE, V_PLAN_START_YYYYMMDD
              , P_PROGRAM_ID, P_SHEET_NAME, P_DIVISION_ID, P_OPERATION_GROUP;

        DBMS_LOB.FREETEMPORARY(V_PIVOT);
        DBMS_LOB.FREETEMPORARY(V_SQL);

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_GET_SHIPMENT_REQUEST;

    /*******************************************************************************
     * P_SSP0045_SAVE_SHIPMENT_REQUEST
     *   AS-IS SSP0045_SAVE_SHIPMENT_REQUEST
     *   Shipment Request 입력
     *
     * ★AS-IS 는 삭제 기능이 없어 Active Flag 를 'I' 또는 'M' 으로 보고 입력 · 수정만 한다.
     * ★AS-IS CATCH 는 오류를 기록한 뒤 바깥 트랜잭션을 확정(COMMIT)하고 결과 코드로 알린다.
     *   TO-BE 는 저장 시작에 SAVEPOINT 를 두고 오류 때 그 지점까지만 되돌린다.
     *******************************************************************************/
    PROCEDURE P_SSP0045_SAVE_SHIPMENT_REQUEST
    (
        P_ACTIVE_FLAG           IN  CLOB
      , P_DIVISION_ID           IN  CLOB
      , P_FROM_SITE             IN  CLOB
      , P_ITEM_ID               IN  CLOB
      , P_INCOTERMS             IN  CLOB
      , P_TRANSPORT_MODE        IN  CLOB
      , P_TO_SITE               IN  CLOB
      , P_BOD_ID                IN  CLOB
      , P_MEASURE               IN  CLOB
      , P_YYYYMMDD              IN  CLOB
      , P_QTY                   IN  CLOB
      , P_PROJECT_CODE          IN  CLOB
      , P_FCST_TYPE             IN  CLOB
      , P_CREATED_BY            IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG               VARCHAR2(4000 CHAR);
        V_DELIMITER             VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT          PLS_INTEGER := 0;
        V_MST_LOOP_CNT          PLS_INTEGER := 0;
        V_CNT_NO_BOD            PLS_INTEGER := 0;
        V_STR_NO_BOD            VARCHAR2(150 CHAR);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PKG_SSP0045.P_SSP0045_SAVE_SHIPMENT_REQUEST';
        V_LOG_TYPE              VARCHAR2(30 CHAR);
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        D_EVENT_DATE            DATE;
        /* 예외처리 변수 설정 */
        V_ERR_CODE              PLS_INTEGER;
        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
        V_SQL_CODE              VARCHAR2(30 CHAR);
        E_NO_BOD                EXCEPTION;
    BEGIN

        SAVEPOINT SP_SSP0045_SAVE;

        DELETE FROM GT_SSP0045_SAVE_REQ;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 프로시저 LOOP 길이를 판단 */
        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ITEM_ID, V_DELIMITER));

        /*** 1. 신규건 MEASURE별 입력데이터 정리   *****/
        WHILE LENGTH(RTRIM(P_DIVISION_ID)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            INSERT INTO GT_SSP0045_SAVE_REQ
            ( ACTIVE_FLAG, DIVISION_ID, FROM_SITE, ITEM_ID, INCOTERMS, TRANSPORT_MODE, TO_SITE
            , BOD_ID, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE )
            SELECT SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,     V_DELIMITER, V_MST_LOOP_CNT)   AS ACTIVE_FLAG
                 , SCM_ARR_SPL_VAL(P_DIVISION_ID,     V_DELIMITER, V_MST_LOOP_CNT)   AS DIVISION_ID
                 , SCM_ARR_SPL_VAL(P_FROM_SITE,       V_DELIMITER, V_MST_LOOP_CNT)   AS FROM_SITE
                 , SCM_ARR_SPL_VAL(P_ITEM_ID,         V_DELIMITER, V_MST_LOOP_CNT)   AS ITEM_ID
                 , SCM_ARR_SPL_VAL(P_INCOTERMS,       V_DELIMITER, V_MST_LOOP_CNT)   AS INCOTERMS
                 , SCM_ARR_SPL_VAL(P_TRANSPORT_MODE,  V_DELIMITER, V_MST_LOOP_CNT)   AS TRANSPORT_MODE
                 , SCM_ARR_SPL_VAL(P_TO_SITE,         V_DELIMITER, V_MST_LOOP_CNT)   AS TO_SITE
                 , SCM_ARR_SPL_VAL(P_BOD_ID,          V_DELIMITER, V_MST_LOOP_CNT)   AS BOD_ID
                 , 'SHIP_REQ'                                                        AS MEASURE
                 , SCM_ARR_SPL_VAL(P_YYYYMMDD,        V_DELIMITER, V_MST_LOOP_CNT)   AS YYYYMMDD
                 , SCM_ARR_SPL_VAL(P_QTY,             V_DELIMITER, V_MST_LOOP_CNT)   AS QTY
                 , SCM_ARR_SPL_VAL(P_PROJECT_CODE,    V_DELIMITER, V_MST_LOOP_CNT)   AS PROJECT_CODE
                 , SCM_ARR_SPL_VAL(P_FCST_TYPE,       V_DELIMITER, V_MST_LOOP_CNT)   AS FCST_TYPE
              FROM DUAL;

        END LOOP;

        /* BOD 2단계 개발 : BOD ID 를 변경하지 못하도록 주석 처리 함 */

        /* BOD CHECK */
        SELECT COUNT(*)
          INTO V_CNT_NO_BOD
          FROM GT_SSP0045_SAVE_REQ
         WHERE ACTIVE_FLAG = 'M'
           AND TRIM(BOD_ID) IS NULL;

        IF V_CNT_NO_BOD > 0 THEN

            SELECT NO_BOD
              INTO V_STR_NO_BOD
              /* ★AS-IS 는 이어붙이는 값 하나라도 없으면 문구 전체가 빈 값이 된다. 그 동작을 맞춘다 */
              FROM ( SELECT CASE WHEN DIVISION_ID IS NULL OR FROM_SITE IS NULL OR TO_SITE IS NULL
                                       OR INCOTERMS IS NULL OR TRANSPORT_MODE IS NULL THEN NULL
                                  ELSE DIVISION_ID||'/'||FROM_SITE||'/'||TO_SITE||'/'||INCOTERMS||'/'||TRANSPORT_MODE
                             END                                                       AS NO_BOD
                       FROM GT_SSP0045_SAVE_REQ
                      WHERE ACTIVE_FLAG = 'M'
                        AND TRIM(BOD_ID) IS NULL )  IA
             WHERE ROWNUM = 1;

            V_ERR_CODE    := 99111;
            V_ERR_MESSAGE := 'Div, From Site, To Site 에 해당되는 BOD(Trans mode, Incoterms) 정보가 유효하지 않습니다. '||V_STR_NO_BOD;
            RAISE E_NO_BOD;                                    /* 예외발생 */

        END IF;

        D_EVENT_DATE := SYSDATE;

        /* 수정 */
        /* 삭제기능은 없으므로 Active Flag는 'I' 또는 'M'으로 가정하고 입력/수정만 진행 */
        UPDATE DM_PLN_SHIPMENT_REQ A
           SET ( A.QTY, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE )
               = ( SELECT TO_NUMBER(B.QTY)
                        , P_CREATED_BY
                        , D_EVENT_DATE
                     FROM GT_SSP0045_SAVE_REQ B
                    WHERE A.DIVISION_ID     = B.DIVISION_ID
                      AND A.SCM_SITE_ID     = B.TO_SITE
                      AND A.ITEM_ID         = B.ITEM_ID
                      AND A.INCOTERMS       = B.INCOTERMS
                      AND A.TRANSPORT_MODE  = B.TRANSPORT_MODE
                      AND A.MEASURE         = B.MEASURE
                      AND A.PLANT_SITE_ID   = B.FROM_SITE
                      AND A.YYYYMMDD        = B.YYYYMMDD
                      AND A.BOD_ID          = B.BOD_ID         /* BOD 2단계 개발 : 추가 */
                      AND A.PROJECT_CODE    = (CASE WHEN B.PROJECT_CODE IS NULL OR B.PROJECT_CODE = '/' THEN '/' ELSE B.PROJECT_CODE END)
                      AND A.FCST_TYPE       = (CASE WHEN B.FCST_TYPE IS NULL OR B.FCST_TYPE = '/' THEN '/' ELSE B.FCST_TYPE END) )
         WHERE EXISTS (SELECT 1
                         FROM GT_SSP0045_SAVE_REQ B
                        WHERE A.DIVISION_ID     = B.DIVISION_ID
                          AND A.SCM_SITE_ID     = B.TO_SITE
                          AND A.ITEM_ID         = B.ITEM_ID
                          AND A.INCOTERMS       = B.INCOTERMS
                          AND A.TRANSPORT_MODE  = B.TRANSPORT_MODE
                          AND A.MEASURE         = B.MEASURE
                          AND A.PLANT_SITE_ID   = B.FROM_SITE
                          AND A.YYYYMMDD        = B.YYYYMMDD
                          AND A.BOD_ID          = B.BOD_ID     /* BOD 2단계 개발 : 추가 */
                          AND A.PROJECT_CODE    = (CASE WHEN B.PROJECT_CODE IS NULL OR B.PROJECT_CODE = '/' THEN '/' ELSE B.PROJECT_CODE END)
                          AND A.FCST_TYPE       = (CASE WHEN B.FCST_TYPE IS NULL OR B.FCST_TYPE = '/' THEN '/' ELSE B.FCST_TYPE END));

        INSERT INTO DM_PLN_SHIPMENT_REQ
        ( DIVISION_ID,    PROJECT_CODE,   SCM_SITE_ID,        ITEM_ID,            FCST_TYPE
        , INCOTERMS,      TRANSPORT_MODE, MEASURE,            PLANT_SITE_ID,      YYYYMMDD,           QTY
        , BOD_ID,         SITE_TYPE,      CREATED_BY,         CREATION_DATE,      LAST_UPDATED_BY,    LAST_UPDATE_DATE )
        SELECT B.DIVISION_ID
             , B.PROJECT_CODE                                 AS PROJECT_CODE
             , B.TO_SITE
             , B.ITEM_ID
             , B.FCST_TYPE                                    AS FCST_TYPE
             , B.INCOTERMS
             , B.TRANSPORT_MODE
             , B.MEASURE
             , B.FROM_SITE
             , B.YYYYMMDD
             , TO_NUMBER(B.QTY)
             , B.BOD_ID
             , 'PLANT'
             , P_CREATED_BY
             , D_EVENT_DATE
             , P_CREATED_BY
             , D_EVENT_DATE
          FROM GT_SSP0045_SAVE_REQ B
         WHERE NOT EXISTS (SELECT 1
                             FROM DM_PLN_SHIPMENT_REQ A
                            WHERE A.DIVISION_ID     = B.DIVISION_ID
                              AND A.SCM_SITE_ID     = B.TO_SITE
                              AND A.ITEM_ID         = B.ITEM_ID
                              AND A.INCOTERMS       = B.INCOTERMS
                              AND A.TRANSPORT_MODE  = B.TRANSPORT_MODE
                              AND A.MEASURE         = B.MEASURE
                              AND A.PLANT_SITE_ID   = B.FROM_SITE
                              AND A.YYYYMMDD        = B.YYYYMMDD
                              AND A.BOD_ID          = B.BOD_ID /* BOD 2단계 개발 : 추가 */
                              AND A.PROJECT_CODE    = (CASE WHEN B.PROJECT_CODE IS NULL OR B.PROJECT_CODE = '/' THEN '/' ELSE B.PROJECT_CODE END)
                              AND A.FCST_TYPE       = (CASE WHEN B.FCST_TYPE IS NULL OR B.FCST_TYPE = '/' THEN '/' ELSE B.FCST_TYPE END));

        /* History */
        INSERT INTO DM_PLN_SHIPMENT_REQ_H
        ( DIVISION_ID,    PROJECT_CODE,   SCM_SITE_ID,        ITEM_ID,            FCST_TYPE
        , INCOTERMS,      TRANSPORT_MODE, MEASURE,            PLANT_SITE_ID,      YYYYMMDD,           QTY
        , BOD_ID,         SITE_TYPE,      CREATED_BY,         CREATION_DATE,      LAST_UPDATED_BY,    LAST_UPDATE_DATE )
        SELECT B.DIVISION_ID
             , B.PROJECT_CODE                                 AS PROJECT_CODE
             , B.TO_SITE
             , B.ITEM_ID
             , B.FCST_TYPE                                    AS FCST_TYPE
             , B.INCOTERMS
             , B.TRANSPORT_MODE
             , B.MEASURE
             , B.FROM_SITE
             , B.YYYYMMDD
             , TO_NUMBER(B.QTY)
             , B.BOD_ID
             , 'PLANT'
             , P_CREATED_BY
             , D_EVENT_DATE
             , P_CREATED_BY
             , D_EVENT_DATE
          FROM GT_SSP0045_SAVE_REQ B;

        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE, NULL AS MSG FROM DUAL;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN E_NO_BOD THEN
            ROLLBACK TO SP_SSP0045_SAVE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL, SYSDATE);
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR
                    SELECT 'N' AS RESULT_CODE, V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MESSAGE AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

        WHEN OTHERS THEN
            V_ERR_MSG  := SQLERRM;
            V_SQL_CODE := TO_CHAR(SQLCODE);
            ROLLBACK TO SP_SSP0045_SAVE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MSG, NULL, SYSDATE);
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR
                    SELECT 'F' AS RESULT_CODE, '['||V_SQL_CODE||']'||V_ERR_MSG AS ERR_MESSAGE FROM DUAL;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_SAVE_SHIPMENT_REQUEST;

END PKG_SSP0045;
/
-- ##### PROCEDURE PR_DM_DNM_EDI_CALLOFF_MKT_FCST (사내 적용 2026-10-09 14:43:08 · ORA-00979 문장 4→0 · 마커 4)
CREATE OR REPLACE PROCEDURE           "PR_DM_DNM_EDI_CALLOFF_MKT_FCST" 
/*
 * Program ID  : PR_DM_DNM_EDI_CALLOFF_MKT_FCST
 * Description  : GSCM COMPLETED EDI 정보 -> MKT_FCST INSERT(CUST_FCST_EDI MEASURE)
 *                  DM_DNM_EDI_CALLOFF_ITEM -> DM_PLN_MKT_FCST
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 배포시 주의사항 : 개발기 -> LGCE_INFDEV , 운영기 -> LGCE_INF
 *===================================================================================================
   20230503 kdmcc14      [EDI과제] PROJECT EDI_CALLOFF DATA -> MKT FCST MEASURE 생성
   20231006 chutoc730    [EDI과제] CUST_MATERIAL_CODE NOT LIKE '9j1%' 예외 분기 추가
   20231101 chutoc730    [EDI과제] MEASURE(SCHEDULING_TYPE) 별 오류 합 수정
   20231116 chutoc730    [EDI과제] Porsche/Audi/DRX Audi_DE_SHM / Porsche_DE_SHM 예외 로직 추가 / 추후 제외 소급 적용 룰 추가
   20231205 chutoc730    [EDI과제] 유통기간내 고객수요를 합산 로직을 기간내 MAX(IF_SEQ) 조건으로 합산 / 그룹조건에 CUSTOMER_PLANT를 추가하고 CUST_MATERIAL_CODE 를 제거 수정.
   20231206 chutoc730    MKT FCST[Auto] 화면 관련하여 발주처 예외처리.
   20240105 chutoc730    기존데이터 삭제 기준 날짜 변경 금주월요일~계획구간에서 당일~계획구간.
   20240116 chutoc730    END_CUSTOMER 추가 및 기준 하드코딩 LOOKUP(DM_EDI_CALLOFF_MKT_FCST_END_CUSTOMER) 에 데이터화.
   20240424 kcw3408      SENDER_NAME 30--> 200 으로 수정
   20240429 kcw3408      N:N Model Mapping_적재 추가(집계 시점에 Cust Item/Unloading Point/Plant 고려,Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음)
   20240626 JSSBAE       [E20240620-001488]_SCM DM 고객수요분석- Cust Plant NULL인 데이터 처리로직 개선
   20240626 JSSBAE       [E20240610-000320]_SCM DM EDI(Cust FCST) 관련 문의사항 (예외로직적용: 앞뒤 공백값, NULL값 공백으로 치환해서 비교 처리)
   20240703 JSSBAE       [E20240701-000472]_[공급 SCM PI팀] ERP EDI Master화면 업데이트 범위 개선
   20241204 JSSBAE       [E20241126-000426]_Cust.FCST(P+P) Measure 로직 수정
   20241216 KANG.H.J     [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 */
AS
    V_BATCH_USER         VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_BATCH_CHK_MSG      VARCHAR2(150 CHAR) := ' [DM]SOLDTO_CODE 없이 들어와서 계속해서 에러를 발생시켜서 TRANSFER_FLAG 를 변경함.';
    V_LOG_TYPE           VARCHAR2(30 CHAR);
    N_LOG_COUNT          INTEGER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    D_EVENT_DATE         DATE;
    V_IFSEQNO_INSERT     VARCHAR2(30 CHAR);
    V_SOLDTO_CODE        VARCHAR2(10 CHAR);
    V_SHIPTO_CODE        VARCHAR2(10 CHAR);
    V_UNLOADING_POINT    VARCHAR2(35 CHAR);
    V_CUSTOMER_PLANT     VARCHAR2(8 CHAR);
    V_SCHEDULING_TYPE    VARCHAR2(6 CHAR);
    V_PROJECT_CODE       VARCHAR2(100 CHAR);
    V_SCM_SITE_ID        VARCHAR2(100 CHAR);
    V_CUST_MATERIAL_CODE VARCHAR2(70 CHAR);
    V_ITEM_ID            VARCHAR2(100 CHAR);
    V_END_CUSTOMER       VARCHAR2(35 CHAR);
    V_SENDER_NAME        VARCHAR2(200 CHAR);
    V_CREATE_DATE        VARCHAR2(16 CHAR);
    V_CREATE_TIME        VARCHAR2(10 CHAR);
    V_0WEEK_MONDAY       VARCHAR2(8 CHAR);
    V_1WEEK_MONDAY       VARCHAR2(8 CHAR);
    V_TODAY              VARCHAR2(8 CHAR);
    V_HOUR               VARCHAR2(2 CHAR);
    V_YYYYMMDD           VARCHAR2(8 CHAR);
    V_DATEADDTODAY       DATE;
    V_I                  INTEGER := 1;
    V_CNT                INTEGER := 0;
    V_J                  INTEGER := 1;
    V_CNT_ORG            INTEGER := 0;
    V_FROM_YYYYMMDD      VARCHAR2(4000 CHAR);
    V_CUST_FCST_I        INTEGER;
    V_CUST_FCST_CNT      INTEGER;
    V_CUST_FCST_DIVISION VARCHAR2(30 CHAR);
    V_IN_PARA_DATA       VARCHAR2(4000 CHAR);
BEGIN

    /* LOG 용 변수 설정 */
    V_HOUR := NULL;


    DELETE FROM GT_DDECM_DM_CUST_MODEL_MAPPING;
    DELETE FROM GT_DDECM_CUST_FCST_DIVISION;
    DELETE FROM GT_DDECM_MKT_ORG_DATA;

    /* 시작 LOG */
    V_LOG_TYPE     := 'START';
    V_LOG_MESSAGE  := '########## Start of procedure ##########';
    V_DESCRIPTION  := NULL;
    D_EVENT_DATE   := SYSDATE;
    D_EVENT_DATE   := SYSDATE;
    V_DATEADDTODAY := SYSDATE;
    V_TODAY        := TO_CHAR(V_DATEADDTODAY, 'YYYYMMDD');

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_0WEEK_MONDAY := TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'MON') + (-7), 'YYYYMMDD');     /* W0월요일 */
    V_1WEEK_MONDAY := TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'MON') + (-7 + 7), 'YYYYMMDD'); /* W1월요일 */
    /* 현재시간 */
    V_HOUR := SUBSTR(TO_CHAR(V_DATEADDTODAY, 'HH24:MI:SS'), 1, 2);

    DBMS_OUTPUT.PUT_LINE(V_1WEEK_MONDAY);

    /* 오늘 기준 52W 전까지 조회함 */
    V_FROM_YYYYMMDD := TO_CHAR(TRUNC(SYSDATE, 'IW') - (52 * 7), 'YYYYMMDD');
    /* PSA 데이터 조회일자 */
    BEGIN
        /* 다음주 일요일을 날짜기준으로 삼는데. (단 오늘이 일요일이면 오늘부터 기준을 삼음) */
        SELECT CASE
                   WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY, 'D')) = 1 THEN TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'SUN') + (-7), 'YYYYMMDD')
                   ELSE TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'SUN') + 0, 'YYYYMMDD')
               END
          INTO V_YYYYMMDD
          FROM DUAL;
    END;

    BEGIN

        /* 예외 Sales Site 관리 테이블중복제거 / 임시확인용 Sales Site 관리 테이블 중복제거 */
        DELETE FROM GT_DDECM_EDI_MGM_SALES_SITE;

        /* 테이블중복제거 / 임시확인용테이블 중복제거 */
        DELETE FROM GT_DDECM_EDI_END_CUSTOMER;

        /* EDI END_CUSTOMER별 기간 설정 */
        BEGIN
            /* EDI_END_CUSTOMER Lookup의 Active = 'Off'이면 CREATE_DATE -52주부터, 'On'이면 Lookup 기간 사용 */
            INSERT INTO GT_DDECM_EDI_END_CUSTOMER
                (DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, FROM_WEEK, FROM_DAY, TO_WEEK, TO_DAY, ACTIVE)
            SELECT A.DIVISION_ID                                          AS DIVISION_ID
                 , A.END_CUSTOMER                                         AS END_CUSTOMER
                 , NVL(NULLIF(RTRIM(B.SEGMENT4),''), '/')                                   AS SCM_SITE_ID
                 , CASE WHEN NVL(B.SEGMENT5, 'On') = 'On' THEN NVL(B.ATTRIBUTE1, '-1')
                        ELSE '-52'
                   END                                                    AS FROM_WEEK
                 , NVL(B.ATTRIBUTE2, 'TUE')                               AS FROM_DAY
                 , NVL(B.ATTRIBUTE3, '0')                                 AS TO_WEEK
                 , NVL(B.ATTRIBUTE4, 'MON')                               AS TO_DAY
                 , NVL(B.SEGMENT5, 'On')                                  AS ACTIVE
              FROM SCM_MST_SITE A
              LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                ON  B.LOOKUP_TYPE  = 'EDI_END_CUSTOMER'
                AND A.DIVISION_ID  = B.SEGMENT1
                AND A.END_CUSTOMER = B.SEGMENT2
                AND B.VALID_YN     = 'Y'
             WHERE A.END_CUSTOMER IS NOT NULL
             GROUP BY A.DIVISION_ID, A.END_CUSTOMER, B.SEGMENT4, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.SEGMENT5;
        END;

        BEGIN
            /* 테이블중복제거 / 임시확인용테이블 중복제거 */
            DELETE FROM GT_DDECM_EDI_ALL;

            /* EDI STATUS_CODE가 SUCCESS인 DATA */
            BEGIN
                /* DIVISION_ID, SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, ITEM_ID, SCHEDULING_TYPE 기준으로 DATA 추출 */
                /* EDI물동 기준이 되는 IFSEQNO 추출함. */
                INSERT INTO GT_DDECM_EDI_ALL
                    (NUM, DIVISION_ID, IFSEQNO, SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, CUSTOMER_PLANT, SCHEDULING_TYPE
                    , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, ERP_FCST_TYPE, CREATE_DATE, CREATE_TIME, MESSAGE_TYPE, END_CUSTOMER, SENDER_NAME, YYYYMMDD)
                SELECT ROW_NUMBER() OVER (ORDER BY A.IFSEQNO)             AS NUM   /* 해당 칼럼이 필요한가?? */
                     , A.DIVISION_ID
                     , A.IFSEQNO
                     , A.SOLDTO_CODE
                     , A.SHIPTO_CODE
                     , A.UNLOADING_POINT
                     , A.CUSTOMER_PLANT
                     , A.SCHEDULING_TYPE
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.ERP_FCST_TYPE
                     , A.CREATE_DATE
                     , A.CREATE_TIME
                     , A.MESSAGE_TYPE
                     , A.END_CUSTOMER
                     , A.SENDER_NAME
                     , A.YYYYMMDD
                  FROM (
                        SELECT ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCHEDULING_TYPE, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                                                             , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                                  ORDER BY A.CREATE_DATE DESC, A.IFSEQNO DESC)     AS RNK
                             , A.DIVISION_ID
                             , A.IFSEQNO
                             , A.SOLDTO_CODE
                             , A.SHIPTO_CODE
                             , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                             , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                             , A.SCHEDULING_TYPE
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END           AS ERP_FCST_TYPE
                             , A.CREATE_DATE
                             , A.CREATE_TIME
                             , A.MESSAGE_TYPE
                             , B.END_CUSTOMER
                             , A.SENDER_NAME
                             , A.YYYYMMDD
                          FROM DM_DNM_EDI_CALLOFF_ITEM A
                          LEFT OUTER JOIN SCM_MST_SITE B
                            ON  A.DIVISION_ID = B.DIVISION_ID
                            AND A.SCM_SITE_ID = B.SCM_SITE_ID
                            AND B.SITE_TYPE   = 'SALES'
                            AND B.VALID_YN    = 'Y'
                            AND REPLACE(B.END_CUSTOMER, '-', '') IS NOT NULL
                          LEFT OUTER JOIN LATERAL (SELECT C1.*
                                         FROM GT_DDECM_EDI_END_CUSTOMER C1
                                        WHERE A.DIVISION_ID  = C1.DIVISION_ID
                                          AND C1.END_CUSTOMER = B.END_CUSTOMER
                                          AND C1.SCM_SITE_ID  = NVL((SELECT X99.SCM_SITE_ID
                                                                       FROM GT_DDECM_EDI_END_CUSTOMER X99
                                                                      WHERE X99.DIVISION_ID  = A.DIVISION_ID
                                                                        AND X99.END_CUSTOMER = B.END_CUSTOMER
                                                                        AND X99.SCM_SITE_ID  = A.SCM_SITE_ID), '/')) C ON (1 = 1)
                         WHERE 1 = 1
                           AND A.CREATE_DATE >= V_FROM_YYYYMMDD    /* 52주 전부터가 유효한 데이터임. */
                           AND A.YYYYMMDD    >= V_TODAY            /* 당일 이후 */
/*
   [원본 보존] 아래 CALENDAR 기반 CREATE_DATE 시작/종료일 산출 블록은 원본 MSSQL에서 주석처리되어 비활성 상태임.
   AND A.CREATE_DATE >= (
       SELECT BASIS_YYYYMMDD   -- 시작일의 정의 (-1주 OR -52주의 날짜를 지정한 요일로 추출함)
       FROM (
             SELECT RANK() OVER (ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD <= (CASE WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 2 THEN TO_CHAR(V_DATEADDTODAY-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(V_DATEADDTODAY-2,'YYYYMMDD') ELSE TO_CHAR(V_DATEADDTODAY,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.FROM_DAY   -- 사용자가 정의한 요일로 처리
            ) D
       WHERE D.RK = C.FROM_WEEK    -- FROM_WEEK는 -1 OR -52로만 존재함.
   )
   AND A.CREATE_DATE <= (
       SELECT BASIS_YYYYMMDD -- 종료일을 지정함 (0주(금주) OR -1주(차주)의 날짜를 지정한 요일로 추출함)
       FROM (
             SELECT (CASE WHEN DAYOFWEEK = 'SUN' THEN RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 2
                          ELSE RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 1 END) AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD >= (CASE WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 2 THEN TO_CHAR(V_DATEADDTODAY-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(V_DATEADDTODAY-2,'YYYYMMDD') ELSE TO_CHAR(V_DATEADDTODAY,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.TO_DAY
            ) D
       WHERE D.RK = C.TO_WEEK
   )
*/
                           AND A.STATUS_CODE = 'S'
                           AND EXISTS (
                                        SELECT 1
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                                         WHERE LUP.LOOKUP_TYPE = 'DM_EDI_CALLOFF_MKT_FCST_END_CUSTOMER'
                                           AND LUP.SEGMENT1    = A.DIVISION_ID
                                           AND LUP.SEGMENT2    = A.SENDER_NAME
                                           AND LUP.SEGMENT3    = B.END_CUSTOMER
                                           AND LUP.SEGMENT4    = A.SCHEDULING_TYPE
                                           AND A.MESSAGE_TYPE  = (CASE WHEN LUP.SEGMENT5 IN ('DELJIT', 'DELFOR') THEN LUP.SEGMENT5   /* DELJIT / DELFOR로 정의되어 있으면. 정의된 데이터만 추출함. */
                                                                       ELSE (                                                       /* 그렇지 않을 경우 이번주 일요일까지는 DELJIT / 그 이후로는 DELFOR 로 정의된 추출함. */
                                                                             CASE WHEN A.YYYYMMDD <= V_YYYYMMDD THEN 'DELJIT'
                                                                                  ELSE 'DELFOR'
                                                                             END)
                                                                  END)
                                           AND LUP.VALID_YN = 'Y'
                                           AND ((LENGTH(LUP.ATTRIBUTE2) < 8 AND LENGTH(LUP.ATTRIBUTE3) < 8) OR (A.YYYYMMDD BETWEEN LUP.ATTRIBUTE1 AND LUP.ATTRIBUTE2))  /* 유효날짜 체크함. */
                                      )
                         GROUP BY A.DIVISION_ID
                                , A.IFSEQNO
                                , A.SOLDTO_CODE
                                , A.SHIPTO_CODE
                                , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ')
                                , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')
                                , A.SCHEDULING_TYPE
                                , A.PROJECT_CODE
                                , A.SCM_SITE_ID
                                , A.ITEM_ID
                                , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                , A.CREATE_DATE
                                , A.CREATE_TIME
                                , A.MESSAGE_TYPE
                                , B.END_CUSTOMER
                                , A.SENDER_NAME
                                , A.YYYYMMDD
                       ) A
                 WHERE RNK = 1
                   AND LENGTH(A.YYYYMMDD) = 8    /* 강현준 추가 ('444444' 가 추가되어 있음 */
                 ORDER BY A.IFSEQNO;
            END;

            /* 자료 추출(고객수요 N:N Mapping 적용) */
            /* 테이블중복제거 / 임시확인용테이블 중복제거 */
            DELETE FROM GT_DDECM_EDI_MKT_FCST;
            DELETE FROM GT_DDECM_EDI_MKT_FCST_ALL;

            /* 2024.04.29    kcw3408       고객수요 N:N Mapping  */
            BEGIN
                /* [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선 START */
                INSERT INTO GT_DDECM_DM_CUST_MODEL_MAPPING
                    (DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, PROJECT_CODE, FCST_TYPE, INCOTERMS, DOM_EXP, ITEM_ID, MAPPING_ITEM_ID
                    , UNLOADING_POINT, CUSTOMER_PLANT, CUSTOMER_ITEM_ID, VALID_START_DATE, VALID_END_DATE)
                SELECT DISTINCT A.DIVISION_ID
                     /* , A.DATA_TYPE_CODE  -- MKT_FCST(CUST_FCST)는 롤인/롤아웃 구분없이 모두 생성하므로 DATA_TYPE_CODE 구분없이 처리함. */
                     , A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE
                     , A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.MAPPING_ITEM_ID
                     , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                     , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                     , NVL(RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)), ' ') AS CUSTOMER_ITEM_ID
                     , MAX(A.VALID_START_DATE)                    AS VALID_START_DATE
                     , MAX(A.VALID_END_DATE)                      AS VALID_END_DATE
                  FROM DM_CUST_MODEL_MAPPING_M A
                 WHERE A.ACTIVE_YN = 'Y'
                 /* AND A.DATA_TYPE_CODE = 'SCM' */
                 GROUP BY A.DIVISION_ID
                     , A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE
                     , A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.MAPPING_ITEM_ID
                     , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' '), NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')
                     , NVL(RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)), ' ');
                /* [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선 END */
            END;

            SELECT COUNT(*) INTO V_CNT FROM GT_DDECM_EDI_ALL;

            IF (V_CNT > 0) THEN

                INSERT INTO GT_DDECM_EDI_MKT_FCST_ALL
                    (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                    , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                    , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                    , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, CREATE_TIME, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                SELECT X1.EDI_IF_SEQ, X1.SUB_NO, X1.YYYYMMDD
                     , X1.DIVISION_ID, X1.SCM_SITE_ID, X1.ITEM_ID, X1.PROJECT_CODE
                     , CASE WHEN X1.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END                 AS ERP_FCST_TYPE
                     , X1.BASIS_YYYYMMDD, X1.QTY, X1.EDI_INCOTERMS, X1.SALES_PLANT_SITE_ID
                     , 'E'                                                                         AS DOM_EXP
                     , X1.COMPANY_ID, X1.SOLDTO_CODE, X1.SHIPTO_CODE
                     , X1.DOC_IDENTIFINER, X1.MESSAGE_TYPE
                     , NVL(RTRIM(LTRIM(X1.UNLOADING_POINT)), ' ')                                 AS UNLOADING_POINT
                     , NVL(RTRIM(LTRIM(X1.CUSTOMER_PLANT)), ' ')                                  AS CUSTOMER_PLANT
                     , X1.RDD_START, X1.RDD_END
                     , X1.IFSEQNO
                     , X1.SCHEDULING_TYPE
                     , CASE WHEN (X1.MESSAGE_TYPE = 'DELFOR' AND X1.SOLDTO_CODE = 'FR000064' AND X1.RDD_START <> X1.RDD_END AND X1.RDD_START >= V_1WEEK_MONDAY) THEN 'Periodic DELFOR'
                            ELSE NULL
                       END                                                                        AS DELFOR_TYPE
                     , X1.EDI_LT
                     , NVL(RTRIM(LTRIM(X1.CUST_MATERIAL_CODE)), ' ')                              AS CUST_MATERIAL_CODE
                     , X1.CREATE_DATE, X1.CREATE_TIME
                     , X1.SENDER_CODE, X1.SENDER_NAME
                     , X1.ATTRIBUTE10
                  FROM DM_DNM_EDI_CALLOFF_ITEM X1
                  INNER JOIN GT_DDECM_EDI_ALL X2
                    ON  X1.IFSEQNO         = X2.IFSEQNO
                    AND X1.SOLDTO_CODE     = X2.SOLDTO_CODE
                    AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                    AND X1.SCHEDULING_TYPE = X2.SCHEDULING_TYPE
                    AND X1.PROJECT_CODE    = X2.PROJECT_CODE
                    AND X1.SCM_SITE_ID     = X2.SCM_SITE_ID
                    AND X1.ITEM_ID         = X2.ITEM_ID
                    AND X1.SENDER_NAME     = X2.SENDER_NAME
                    AND X1.CREATE_DATE     = X2.CREATE_DATE
                    AND X1.CREATE_TIME     = X2.CREATE_TIME
                    AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                 WHERE 1 = 1
                   AND X1.STATUS_CODE = 'S'
                   AND TO_NUMBER(REPLACE(NVL(X1.QTY, '0'), ',', '')) <> 0
                   AND NVL(X1.EXCEPTION_FLAG, 'N') != 'Y';

            END IF;

            BEGIN

                BEGIN
                /*
                   2024.04.29    kcw3408       고객수요 N:N Mapping
                   전체 대생 추출후 N:N Model Mapping 작업
                    .집계 시점에 Cust Item/Unloading Point/Plant 반영
                    .Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음
                    . GT_DDECM_EDI_MKT_FCST: 최종 결과,insert 작업
                */
                    BEGIN
                        INSERT INTO GT_DDECM_EDI_MKT_FCST
                            (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                            , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                            , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                            , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                        SELECT X.EDI_IF_SEQ
                             , X.SUB_NO
                             , X.YYYYMMDD
                             , X.DIVISION_ID
                             , X.SCM_SITE_ID
                             , B.ITEM_ID
                             , X.PROJECT_CODE
                             , X.ERP_FCST_TYPE
                             , X.BASIS_YYYYMMDD
                             , X.QTY
                             , X.EDI_INCOTERMS
                             , X.SALES_PLANT_SITE_ID
                             , X.DOM_EXP
                             , X.COMPANY_ID
                             , X.SOLDTO_CODE
                             , X.SHIPTO_CODE
                             , X.DOC_IDENTIFINER
                             , X.MESSAGE_TYPE
                             , NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                             , NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                             , X.RDD_START
                             , X.RDD_END
                             , X.IFSEQNO
                             , X.SCHEDULING_TYPE
                             , X.DELFOR_TYPE
                             , X.EDI_LT
                             , NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') AS CUST_MATERIAL_CODE
                             , X.CREATE_DATE
                             , X.SENDER_CODE
                             , X.SENDER_NAME
                             , X.CHANGE_STATUS
                          FROM GT_DDECM_EDI_MKT_FCST_ALL X
                          JOIN GT_DDECM_DM_CUST_MODEL_MAPPING B
                            ON  X.DIVISION_ID   = B.DIVISION_ID
                            AND X.SCM_SITE_ID   = B.SCM_SITE_ID
                            AND X.PROJECT_CODE  = B.PROJECT_CODE
                            AND X.ERP_FCST_TYPE = B.FCST_TYPE
                            AND X.EDI_INCOTERMS = B.INCOTERMS
                            AND X.DOM_EXP       = B.DOM_EXP
                            AND X.ITEM_ID       = B.ITEM_ID
                            AND NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')   = NVL(RTRIM(LTRIM(B.UNLOADING_POINT)), ' ')
                            AND NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')    = NVL(RTRIM(LTRIM(B.CUSTOMER_PLANT)), ' ')
                            AND NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') = NVL(RTRIM(LTRIM(B.CUSTOMER_ITEM_ID)), ' ')
                         WHERE 1 = 1
                           AND X.BASIS_YYYYMMDD >= B.VALID_START_DATE
                           AND X.BASIS_YYYYMMDD <= B.VALID_END_DATE
                           AND B.ITEM_ID IS NOT NULL;
                    END;
                END;

                BEGIN
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* CUST_FCST_EDI 및 하위 MEASURE 생성 (BEGIN) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder')  /* CUST_fcst는 제외 */
                       AND YYYYMMDD >= V_TODAY
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ALL X
                                     WHERE DM_PLN_MKT_FCST.DIVISION_ID  = X.DIVISION_ID
                                       AND DM_PLN_MKT_FCST.DOM_EXP      = 'E'
                                       AND DM_PLN_MKT_FCST.ATTRIBUTE5   = X.SENDER_NAME
                                       AND X.BASIS_YYYYMMDD             >= V_TODAY   /* 금일 20240105 당주월요일이후 */
                                  );

                /* 날짜 중복데이터는 SUM한 값으로 입력 */
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4    /* SENDER_CODE 값 저장 */
                        , ATTRIBUTE5    /* SENDER_NAME 값 저장 */
                        , ATTRIBUTE6    /* IFSEQNO 값 저장 */
                        , ATTRIBUTE7    /* LEADTIME 적용전 ORIGINAL YYYYMMDD 값 저장 */
                        , ATTRIBUTE8    /* EDI_LT 값 저장 */
                        , ATTRIBUTE9    /* CREATE_DATE 값 저장 */
                        , ATTRIBUTE10)  /* 소급적용여부 */
                    SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.DOM_EXP
                         , A.ERP_FCST_TYPE                            AS FCST_TYPE
                         , A.EDI_INCOTERMS                            AS INCOTERMS
                         , 'CUST_FCST_EDI'                            AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD                           AS YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))    AS QTY
                         , 'EDI'
                         , SYSDATE
                         , 'EDI'
                         , SYSDATE
                         , MAX(A.SENDER_CODE)                         AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                         AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                             AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                            AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                              AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                         AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                       AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST
                                     WHERE BASIS_YYYYMMDD >= V_TODAY   /* 금일 20240105 */
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */, A.BASIS_YYYYMMDD;
                END;

                /* MEASURE별 SUM한 값으로 생성 */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.DOM_EXP
                         , A.ERP_FCST_TYPE
                         , A.EDI_INCOTERMS
                         , CASE WHEN A.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast'
                                WHEN A.SCHEDULING_TYPE = '10' THEN 'Immidiate'
                                WHEN A.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement'
                                WHEN A.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp'
                                WHEN A.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp'
                                WHEN A.SCHEDULING_TYPE = '3'  THEN 'Material_Temp'
                                WHEN A.SCHEDULING_TYPE = '83' THEN 'Backorder'
                           END                                       AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))
                         , 'EDI'
                         , SYSDATE
                         , 'EDI'
                         , SYSDATE
                         , MAX(A.SENDER_CODE)                        AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                        AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                            AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                           AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                             AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                        AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                      AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST
                                     WHERE BASIS_YYYYMMDD >= V_TODAY   /* 금일 20240105 */
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , A.SCHEDULING_TYPE, NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */, A.BASIS_YYYYMMDD;
                END;

                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* CUST_FCST_EDI 및 하위 MEASURE 생성 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* [E20241126-000426]_Cust.FCST(P+P) Measure 로직 수정 START */
                /* 프로시져를 호출하여, CUST_FCST 메져 데이터를 생성한다 */
                DELETE FROM GT_DDECM_CUST_FCST_DIVISION;

                INSERT INTO GT_DDECM_CUST_FCST_DIVISION (DIVISION_ID, SEQ)
                SELECT DIVISION_ID
                     , ROW_NUMBER() OVER (ORDER BY DIVISION_ID) - 1  AS SEQ
                  FROM (SELECT DISTINCT DIVISION_ID FROM GT_DDECM_EDI_MKT_FCST);

                SELECT NVL(MAX(SEQ), -1) INTO V_CUST_FCST_CNT FROM GT_DDECM_CUST_FCST_DIVISION;
                V_CUST_FCST_I        := 0;
                V_CUST_FCST_DIVISION := NULL;

                WHILE V_CUST_FCST_I <= V_CUST_FCST_CNT LOOP
                    SELECT DIVISION_ID INTO V_CUST_FCST_DIVISION
                      FROM GT_DDECM_CUST_FCST_DIVISION
                     WHERE SEQ = V_CUST_FCST_I;

                    /* DIVISION 단위로 생성 (CUST_FCST = CUST_FCST_EDI + RPA + EXCEL) */
                    PR_DM_PLN_MKT_FCST_MAKE_CUST_FCST(V_CUST_FCST_DIVISION);   /* > 81, 81_UC */
                    V_CUST_FCST_I := V_CUST_FCST_I + 1;
                END LOOP;

                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (BEGIN) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST_H
                        (DIVISION_ID, HISTORY_SEQ, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT B.DIVISION_ID
                         , SEQ1_DM_PLN_MKT_FCST_H.NEXTVAL   /* History Seqno */
                         , B.PROJECT_CODE
                         , B.SCM_SITE_ID
                         , B.ITEM_ID
                         , B.DOM_EXP
                         , FCST_TYPE
                         , INCOTERMS
                         , MEASURE
                         , PLANT_SITE_ID
                         , B.BASIS_YYYYMMDD
                         , TO_NUMBER(REPLACE(B.QTY, ',', ''))
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE
                         , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                      FROM DM_PLN_MKT_FCST A
                      INNER JOIN GT_DDECM_EDI_MKT_FCST B
                        ON  A.DIVISION_ID  = B.DIVISION_ID
                        AND A.PROJECT_CODE = B.PROJECT_CODE
                        AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                        AND A.ITEM_ID      = B.ITEM_ID
                        AND A.MEASURE      = CASE WHEN B.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast'
                                                  WHEN B.SCHEDULING_TYPE = '10' THEN 'Immidiate'
                                                  WHEN B.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement'
                                                  WHEN B.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp'
                                                  WHEN B.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp'
                                                  WHEN B.SCHEDULING_TYPE = '3'  THEN 'Material_Temp'
                                                  WHEN B.SCHEDULING_TYPE = '83' THEN 'Backorder'
                                             END
                        AND A.PLANT_SITE_ID = B.SALES_PLANT_SITE_ID
                        AND A.YYYYMMDD      = B.BASIS_YYYYMMDD
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST
                                     WHERE BASIS_YYYYMMDD >= V_TODAY   /* 금일 20240105 */
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) C
                        ON  A.DIVISION_ID     = C.DIVISION_ID
                        AND B.PROJECT_CODE    = C.PROJECT_CODE
                        AND B.SCM_SITE_ID     = C.SCM_SITE_ID
                        AND B.ITEM_ID         = C.ITEM_ID
                        AND B.DOM_EXP         = C.DOM_EXP
                        AND B.ERP_FCST_TYPE   = C.ERP_FCST_TYPE
                        AND B.UNLOADING_POINT = C.UNLOADING_POINT
                        AND B.CUSTOMER_PLANT  = C.CUSTOMER_PLANT
                        AND B.EDI_INCOTERMS   = C.EDI_INCOTERMS
                        AND NVL(B.SALES_PLANT_SITE_ID, ' ') = NVL(C.SALES_PLANT_SITE_ID, ' ')
                        AND B.CREATE_DATE     = C.CREATE_DATE
                        AND B.BASIS_YYYYMMDD  = C.BASIS_YYYYMMDD
                     WHERE 1 = 1
                       AND A.YYYYMMDD >= V_TODAY   /* 금일 20240105 W1월요일이후 */
                       AND A.MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder');
                END;
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */

            END;

        END;

        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
        /* CUST_FCST_EDI[Org.] START */
        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
        BEGIN
            /* 테이블중복제거 / 임시확인용테이블 중복제거 */
            DELETE FROM GT_DDECM_EDI_END_CUSTOMER_ORG;

            /* EDI END_CUSTOMER별 기간 설정 */
            BEGIN
                /* EDI_END_CUSTOMER_ORG Lookup의 Active = 'Off'이면 CREATE_DATE -52주부터, 'On'이면 Lookup 기간 사용 */
                /* ORG Lookup의 Active가 'On'이면 Lookup기간중 EDI 데이터 미수신시 수량 0으로 변경 */
                INSERT INTO GT_DDECM_EDI_END_CUSTOMER_ORG
                    (DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, FROM_WEEK, FROM_DAY, TO_WEEK, TO_DAY, ACTIVE)
                SELECT A.DIVISION_ID                                       AS DIVISION_ID
                     , A.END_CUSTOMER                                      AS END_CUSTOMER
                     , NVL(NULLIF(RTRIM(B.SEGMENT4),''), '/')                                AS SCM_SITE_ID
                     , CASE WHEN NVL(B.SEGMENT5, 'On') = 'On' THEN NVL(B.ATTRIBUTE1, '-1')
                            ELSE '-52'
                       END                                                 AS FROM_WEEK
                     , NVL(B.ATTRIBUTE2, 'TUE')                            AS FROM_DAY
                     , NVL(B.ATTRIBUTE3, '0')                              AS TO_WEEK
                     , NVL(B.ATTRIBUTE4, 'MON')                            AS TO_DAY
                     , NVL(B.SEGMENT5, 'On')                               AS ACTIVE
                  FROM SCM_MST_SITE A
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                    ON  B.LOOKUP_TYPE  = 'EDI_END_CUSTOMER_ORG'
                    AND A.DIVISION_ID  = B.SEGMENT1
                    AND A.END_CUSTOMER = B.SEGMENT2
                    AND B.VALID_YN     = 'Y'
                 WHERE A.END_CUSTOMER IS NOT NULL
                 GROUP BY A.DIVISION_ID, A.END_CUSTOMER, B.SEGMENT4, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.SEGMENT5;
            END;

            BEGIN
                /* 테이블중복제거 / 임시확인용테이블 중복제거 */
                DELETE FROM GT_DDECM_EDI_ORG_ALL;

                /* EDI STATUS_CODE가 SUCCESS인 DATA */
                BEGIN
                    /* SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, ITEM_ID, SCHEDULING 기준으로 DATA 추출 */
                    INSERT INTO GT_DDECM_EDI_ORG_ALL
                        (NUM, DIVISION_ID, IFSEQNO, SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, CUSTOMER_PLANT, SCHEDULING_TYPE
                        , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, ERP_FCST_TYPE, CREATE_DATE, CREATE_TIME, MESSAGE_TYPE, END_CUSTOMER, SENDER_NAME, YYYYMMDD)
                    SELECT ROW_NUMBER() OVER (ORDER BY A.IFSEQNO)          AS NUM
                         , A.DIVISION_ID
                         , A.IFSEQNO
                         , A.SOLDTO_CODE
                         , A.SHIPTO_CODE
                         , A.UNLOADING_POINT
                         , A.CUSTOMER_PLANT
                         , A.SCHEDULING_TYPE
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.ERP_FCST_TYPE
                         , A.CREATE_DATE
                         , A.CREATE_TIME
                         , A.MESSAGE_TYPE
                         , A.END_CUSTOMER
                         , A.SENDER_NAME
                         , A.YYYYMMDD
                      FROM (
                            SELECT ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCHEDULING_TYPE, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                                                                 , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                                      ORDER BY A.CREATE_DATE DESC, A.IFSEQNO DESC)   AS RNK
                                 , A.DIVISION_ID
                                 , A.IFSEQNO
                                 , A.SOLDTO_CODE
                                 , A.SHIPTO_CODE
                                 , A.UNLOADING_POINT
                                 , A.CUSTOMER_PLANT
                                 , A.SCHEDULING_TYPE
                                 , A.PROJECT_CODE
                                 , A.SCM_SITE_ID
                                 , A.ITEM_ID
                                 , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END         AS ERP_FCST_TYPE
                                 , A.CREATE_DATE
                                 , A.CREATE_TIME
                                 , A.MESSAGE_TYPE
                                 , B.END_CUSTOMER
                                 , A.SENDER_NAME
                                 , A.YYYYMMDD
                              FROM DM_DNM_EDI_CALLOFF_ITEM A
                              LEFT OUTER JOIN SCM_MST_SITE B
                                ON  A.DIVISION_ID = B.DIVISION_ID
                                AND A.SCM_SITE_ID = B.SCM_SITE_ID
                                AND B.SITE_TYPE   = 'SALES'
                                AND B.VALID_YN    = 'Y'
                                AND REPLACE(B.END_CUSTOMER, '-', '') IS NOT NULL
                              LEFT OUTER JOIN LATERAL (SELECT C1.*
                                             FROM GT_DDECM_EDI_END_CUSTOMER_ORG C1
                                            WHERE A.DIVISION_ID  = C1.DIVISION_ID
                                              AND C1.END_CUSTOMER = B.END_CUSTOMER
                                              AND C1.SCM_SITE_ID  = NVL((SELECT X99.SCM_SITE_ID
                                                                           FROM GT_DDECM_EDI_END_CUSTOMER_ORG X99
                                                                          WHERE X99.DIVISION_ID  = A.DIVISION_ID
                                                                            AND X99.END_CUSTOMER = B.END_CUSTOMER
                                                                            AND X99.SCM_SITE_ID  = A.SCM_SITE_ID), '/')) C ON (1 = 1)
                             WHERE 1 = 1
                               AND A.CREATE_DATE >= V_FROM_YYYYMMDD
                               AND A.YYYYMMDD    >= V_TODAY   /* 당일 이후 */
/*
   [원본 보존] 아래 CALENDAR 기반 CREATE_DATE 시작/종료일 산출 블록은 원본 MSSQL에서 주석처리되어 비활성 상태임.
   AND A.CREATE_DATE >= (
       SELECT BASIS_YYYYMMDD
       FROM (
             SELECT RANK() OVER (ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD <= (CASE WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 2 THEN TO_CHAR(SYSDATE-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(SYSDATE-2,'YYYYMMDD') ELSE TO_CHAR(SYSDATE,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.FROM_DAY
            ) D
       WHERE D.RK = C.FROM_WEEK
   )
   AND A.CREATE_DATE <= (
       SELECT BASIS_YYYYMMDD
       FROM (
             SELECT (CASE WHEN DAYOFWEEK = 'SUN' THEN RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 2
                          ELSE RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 1 END) AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD >= (CASE WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 2 THEN TO_CHAR(SYSDATE-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(SYSDATE-2,'YYYYMMDD') ELSE TO_CHAR(SYSDATE,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.TO_DAY
            ) D
       WHERE D.RK = C.TO_WEEK
   )
*/
                               AND A.STATUS_CODE = 'S'
                               AND EXISTS (
                                            SELECT *
                                              FROM SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                                             WHERE LUP.LOOKUP_TYPE = 'DM_EDI_CALLOFF_MKT_FCST_END_CUSTOMER'
                                               AND LUP.SEGMENT1    = A.DIVISION_ID
                                               AND LUP.SEGMENT2    = A.SENDER_NAME
                                               AND LUP.SEGMENT3    = B.END_CUSTOMER
                                               AND LUP.SEGMENT4    = A.SCHEDULING_TYPE
                                               AND A.MESSAGE_TYPE  = CASE WHEN LUP.SEGMENT5 IN ('DELJIT', 'DELFOR') THEN LUP.SEGMENT5   /* DELJIT / DELFOR로 정의되어 있으면. 정의된 데이터만 추출함. */
                                                                          ELSE (CASE WHEN A.YYYYMMDD <= V_YYYYMMDD THEN 'DELJIT' ELSE 'DELFOR' END)
                                                                     END
                                               AND LUP.VALID_YN = 'Y'
                                               AND ((LENGTH(LUP.ATTRIBUTE2) < 8 AND LENGTH(LUP.ATTRIBUTE3) < 8) OR (A.YYYYMMDD BETWEEN LUP.ATTRIBUTE1 AND LUP.ATTRIBUTE2))
                                          )
                             GROUP BY A.DIVISION_ID
                                    , A.IFSEQNO
                                    , A.SOLDTO_CODE
                                    , A.SHIPTO_CODE
                                    , A.UNLOADING_POINT
                                    , A.CUSTOMER_PLANT
                                    , A.SCHEDULING_TYPE
                                    , A.PROJECT_CODE
                                    , A.SCM_SITE_ID
                                    , A.ITEM_ID
                                    , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                    , A.CREATE_DATE
                                    , A.CREATE_TIME
                                    , A.MESSAGE_TYPE
                                    , B.END_CUSTOMER
                                    , A.SENDER_NAME
                                    , A.YYYYMMDD
                           ) A
                     WHERE RNK = 1
                       AND LENGTH(A.YYYYMMDD) = 8    /* 강현준 추가 ('444444' 가 추가되어 있음 */
                     ORDER BY A.IFSEQNO;
                END;

                /* 테이블중복제거 / 임시확인용테이블 중복제거 */
                DELETE FROM GT_DDECM_EDI_MKT_FCST_ORG;

                /* 기존 로직: 전체 대상 추출 ,삭제를 위한 자료 추출(고객수요 N:N Mapping 적용전 전체) */
                DELETE FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL;

                SELECT COUNT(*) INTO V_CNT_ORG FROM GT_DDECM_EDI_ORG_ALL;

                IF V_CNT_ORG > 0 THEN

                    INSERT INTO GT_DDECM_EDI_MKT_FCST_ORG_ALL
                        (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                        , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                        , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                        , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, CREATE_TIME, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                    SELECT X1.EDI_IF_SEQ, X1.SUB_NO, X1.YYYYMMDD
                         , X1.DIVISION_ID, X1.SCM_SITE_ID, X1.ITEM_ID, X1.PROJECT_CODE
                         , CASE WHEN X1.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END              AS ERP_FCST_TYPE
                         , X1.BASIS_YYYYMMDD, X1.QTY, X1.EDI_INCOTERMS, X1.SALES_PLANT_SITE_ID
                         , 'E'                                                                     AS DOM_EXP
                         , X1.COMPANY_ID, X1.SOLDTO_CODE, X1.SHIPTO_CODE
                         , X1.DOC_IDENTIFINER, X1.MESSAGE_TYPE
                         , NVL(RTRIM(LTRIM(X1.UNLOADING_POINT)), ' ')                              AS UNLOADING_POINT
                         , NVL(RTRIM(LTRIM(X1.CUSTOMER_PLANT)), ' ')                               AS CUSTOMER_PLANT
                         , X1.RDD_START, X1.RDD_END
                         , X1.IFSEQNO
                         , X1.SCHEDULING_TYPE
                         , CASE WHEN (X1.MESSAGE_TYPE = 'DELFOR' AND X1.SOLDTO_CODE = 'FR000064' AND X1.RDD_START <> X1.RDD_END AND X1.RDD_START >= V_1WEEK_MONDAY) THEN 'Periodic DELFOR'
                                ELSE NULL
                           END                                                                    AS DELFOR_TYPE
                         , X1.EDI_LT
                         , NVL(RTRIM(LTRIM(X1.CUST_MATERIAL_CODE)), ' ')                           AS CUST_MATERIAL_CODE
                         , X1.CREATE_DATE
                         , X1.CREATE_TIME
                         , X1.SENDER_CODE
                         , X1.SENDER_NAME
                         , X1.ATTRIBUTE10
                      FROM DM_DNM_EDI_CALLOFF_ITEM X1
                      INNER JOIN GT_DDECM_EDI_ORG_ALL X2
                        ON  X1.IFSEQNO         = X2.IFSEQNO
                        AND X1.SOLDTO_CODE     = X2.SOLDTO_CODE
                        AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                        AND X1.SCHEDULING_TYPE = X2.SCHEDULING_TYPE
                        AND X1.PROJECT_CODE    = X2.PROJECT_CODE
                        AND X1.SCM_SITE_ID     = X2.SCM_SITE_ID
                        AND X1.ITEM_ID         = X2.ITEM_ID
                        AND X1.SENDER_NAME     = X2.SENDER_NAME
                        AND X1.CREATE_DATE     = X2.CREATE_DATE
                        AND X1.CREATE_TIME     = X2.CREATE_TIME
                        AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                     WHERE 1 = 1
                       AND X1.STATUS_CODE = 'S'
                       AND TO_NUMBER(REPLACE(NVL(X1.QTY, '0'), ',', '')) <> 0
                       AND NVL(X1.EXCEPTION_FLAG, 'N') != 'Y';

                    /*
                       2024.04.29    kcw3408       고객수요 N:N Mapping
                       전체 대생 추출후 N:N Model Mapping 작업
                        .집계 시점에 Cust Item/Unloading Point/Plant 반영
                        .Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음
                        . GT_DDECM_EDI_MKT_FCST_ORG: 최종 결과,insert 작업
                    */
                    INSERT INTO GT_DDECM_EDI_MKT_FCST_ORG
                        (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                        , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                        , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                        , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                    SELECT X.EDI_IF_SEQ
                         , X.SUB_NO
                         , X.YYYYMMDD
                         , X.DIVISION_ID
                         , X.SCM_SITE_ID
                         , B.ITEM_ID
                         , X.PROJECT_CODE
                         , X.ERP_FCST_TYPE
                         , X.BASIS_YYYYMMDD
                         , X.QTY
                         , X.EDI_INCOTERMS
                         , X.SALES_PLANT_SITE_ID
                         , X.DOM_EXP
                         , X.COMPANY_ID
                         , X.SOLDTO_CODE
                         , X.SHIPTO_CODE
                         , X.DOC_IDENTIFINER
                         , X.MESSAGE_TYPE
                         , NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                         , NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                         , X.RDD_START
                         , X.RDD_END
                         , X.IFSEQNO
                         , X.SCHEDULING_TYPE
                         , X.DELFOR_TYPE
                         , X.EDI_LT
                         , NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') AS CUST_MATERIAL_CODE
                         , X.CREATE_DATE
                         , X.SENDER_CODE
                         , X.SENDER_NAME
                         , X.CHANGE_STATUS
                      FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                      JOIN GT_DDECM_DM_CUST_MODEL_MAPPING B
                        ON  X.DIVISION_ID   = B.DIVISION_ID
                        AND X.SCM_SITE_ID   = B.SCM_SITE_ID
                        AND X.PROJECT_CODE  = B.PROJECT_CODE
                        AND X.ERP_FCST_TYPE = B.FCST_TYPE
                        AND X.EDI_INCOTERMS = B.INCOTERMS
                        AND X.DOM_EXP       = B.DOM_EXP
                        AND X.ITEM_ID       = B.ITEM_ID
                        AND NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')   = NVL(RTRIM(LTRIM(B.UNLOADING_POINT)), ' ')
                        AND NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')    = NVL(RTRIM(LTRIM(B.CUSTOMER_PLANT)), ' ')
                        AND NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') = NVL(RTRIM(LTRIM(B.CUSTOMER_ITEM_ID)), ' ')
                     WHERE 1 = 1
                       AND X.BASIS_YYYYMMDD >= B.VALID_START_DATE
                       AND X.BASIS_YYYYMMDD <= B.VALID_END_DATE
                       AND B.ITEM_ID IS NOT NULL;

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD < V_0WEEK_MONDAY   /* 당주월요일이전 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                     WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                       AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                       AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                       AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                       AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                       AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                       AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                       AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                  );

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD >= V_0WEEK_MONDAY   /* 금주월요일이후 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                     WHERE DM_PLN_MKT_FCST.DIVISION_ID = X.DIVISION_ID
                                       AND DM_PLN_MKT_FCST.ATTRIBUTE5  = X.SENDER_NAME
                                       AND DM_PLN_MKT_FCST.DOM_EXP     = 'E'
                                  );

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD < V_0WEEK_MONDAY   /* 당주월요일이전 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                     WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                       AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                       AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                       AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                       AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                       AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                       AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                       AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                  );

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD >= V_0WEEK_MONDAY   /* 금주월요일이후 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                  );
                END IF;

                /* 날짜 중복데이터는 SUM한 값으로 입력 */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                         , A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , 'CUST_FCST_EDI_ORG'                       AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD                          AS YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))   AS QTY
                         , 'EDI'                                     AS CREATED_BY
                         , SYSDATE                                   AS CREATION_DATE
                         , 'EDI'                                     AS LAST_UPDATED_BY
                         , SYSDATE                                   AS LAST_UPDATE_DATE
                         , MAX(A.SENDER_CODE)                        AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                        AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                            AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                           AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                             AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                        AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                      AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST_ORG A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG
                                     WHERE 1 = 1
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */, A.BASIS_YYYYMMDD;
                END;

                /* MEASURE별 SUM한 값으로 생성 */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.DOM_EXP
                         , A.ERP_FCST_TYPE
                         , A.EDI_INCOTERMS
                         , CASE WHEN A.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp[Org.]'
                                WHEN A.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp[Org.]'
                                WHEN A.SCHEDULING_TYPE = '3'  THEN 'Material_Temp[Org.]'
                                WHEN A.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast[Org.]'
                                WHEN A.SCHEDULING_TYPE = '10' THEN 'Immidiate[Org.]'
                                WHEN A.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement[Org.]'
                                WHEN A.SCHEDULING_TYPE = '83' THEN 'Backorder[Org.]'
                           END                                       AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD                          AS YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))   AS QTY
                         , 'EDI'                                     AS CREATED_BY
                         , SYSDATE                                   AS CREATION_DATE
                         , 'EDI'                                     AS LAST_UPDATED_BY
                         , SYSDATE                                   AS LAST_UPDATE_DATE
                         , MAX(A.SENDER_CODE)                        AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                        AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                            AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                           AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                             AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                        AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                      AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST_ORG A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG
                                     WHERE 1 = 1
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.SCHEDULING_TYPE, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */, A.BASIS_YYYYMMDD;
                END;

                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* CUST_FCST_EDI_ORG 및 하위 MEASURE 생성 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (BEGIN) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST_H
                        (DIVISION_ID, HISTORY_SEQ, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT B.DIVISION_ID
                         , SEQ1_DM_PLN_MKT_FCST_H.NEXTVAL   /* History Seqno */
                         , B.PROJECT_CODE
                         , B.SCM_SITE_ID
                         , B.ITEM_ID
                         , B.DOM_EXP
                         , FCST_TYPE
                         , INCOTERMS
                         , MEASURE
                         , PLANT_SITE_ID
                         , B.BASIS_YYYYMMDD
                         , TO_NUMBER(REPLACE(B.QTY, ',', ''))
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE
                         , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                      FROM DM_PLN_MKT_FCST A
                      INNER JOIN GT_DDECM_EDI_MKT_FCST_ORG B
                        ON  A.DIVISION_ID  = B.DIVISION_ID
                        AND A.PROJECT_CODE = B.PROJECT_CODE
                        AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                        AND A.ITEM_ID      = B.ITEM_ID
                        AND A.YYYYMMDD     = B.BASIS_YYYYMMDD
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG
                                     WHERE BASIS_YYYYMMDD >= V_0WEEK_MONDAY
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) C
                        ON  A.DIVISION_ID     = C.DIVISION_ID
                        AND B.PROJECT_CODE    = C.PROJECT_CODE
                        AND B.SCM_SITE_ID     = C.SCM_SITE_ID
                        AND B.ITEM_ID         = C.ITEM_ID
                        AND B.DOM_EXP         = C.DOM_EXP
                        AND B.ERP_FCST_TYPE   = C.ERP_FCST_TYPE
                        AND B.UNLOADING_POINT = C.UNLOADING_POINT
                        AND B.CUSTOMER_PLANT  = C.CUSTOMER_PLANT
                        AND B.EDI_INCOTERMS   = C.EDI_INCOTERMS
                        AND NVL(B.SALES_PLANT_SITE_ID, ' ') = NVL(C.SALES_PLANT_SITE_ID, ' ')
                        AND B.CREATE_DATE     = C.CREATE_DATE
                        AND B.BASIS_YYYYMMDD  = C.BASIS_YYYYMMDD
                     WHERE 1 = 1
                       AND A.MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]');
                END;
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */

                /* EDI 데이터 LOOKUP FROM 기간 이후 데이터 미전송시 MKT_FCST 기존 수량을 전부 0으로 변경 START */
                BEGIN
                    /* 테이블중복제거 / 임시확인용테이블 중복제거 */
                    DELETE FROM GT_DDECM_MKT_ORG_DATA;

                    /* MKT_FCST 데이터 생성일 체크 */
                    BEGIN
                        /* LOOKUP적용 */
                        INSERT INTO GT_DDECM_MKT_ORG_DATA
                            (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, PLANT_SITE_ID)
                        SELECT A.DIVISION_ID
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , A.PLANT_SITE_ID
                          FROM (
                                SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, PLANT_SITE_ID
                                     , MAX(ATTRIBUTE6) AS IFSEQNO
                                     , MAX(ATTRIBUTE9) AS CREATE_DATE
                                  FROM DM_PLN_MKT_FCST
                                 WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                                   AND QTY <> 0
                                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, PLANT_SITE_ID
                               ) A
                          LEFT OUTER JOIN SCM_MST_SITE B
                            ON  A.DIVISION_ID = B.DIVISION_ID
                            AND A.SCM_SITE_ID = B.SCM_SITE_ID
                            AND B.SITE_TYPE   = 'SALES'
                            AND B.VALID_YN    = 'Y'
                            AND REPLACE(B.END_CUSTOMER, '-', '') IS NOT NULL
                          LEFT OUTER JOIN LATERAL (SELECT C1.*
                                         FROM GT_DDECM_EDI_END_CUSTOMER_ORG C1
                                        WHERE A.DIVISION_ID  = C1.DIVISION_ID
                                          AND C1.END_CUSTOMER = B.END_CUSTOMER
                                          AND C1.SCM_SITE_ID  = NVL((SELECT X99.SCM_SITE_ID
                                                                       FROM GT_DDECM_EDI_END_CUSTOMER_ORG X99
                                                                      WHERE X99.DIVISION_ID  = A.DIVISION_ID
                                                                        AND X99.END_CUSTOMER = B.END_CUSTOMER
                                                                        AND X99.SCM_SITE_ID  = A.SCM_SITE_ID), '/')) C ON (1 = 1)
                         WHERE A.CREATE_DATE < (
                                SELECT BASIS_YYYYMMDD
                                  FROM (
                                        SELECT RANK() OVER (ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK, DT.BASIS_YYYYMMDD
                                          FROM SCM_SYS_CALENDAR_M DT
                                         WHERE BASIS_YYYYMMDD <= (CASE WHEN TO_NUMBER(TO_CHAR(SYSDATE, 'D')) = 2 THEN TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
                                                                       WHEN TO_NUMBER(TO_CHAR(SYSDATE, 'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(SYSDATE - 2, 'YYYYMMDD') ELSE TO_CHAR(SYSDATE, 'YYYYMMDD') END)
                                                                       ELSE TO_CHAR(SYSDATE, 'YYYYMMDD')
                                                                  END)
                                           AND DAYOFWEEK = C.FROM_DAY
                                       ) D
                                 WHERE D.RK = C.FROM_WEEK
                              )
                           AND C.ACTIVE = 'On';
                    END;

                    UPDATE DM_PLN_MKT_FCST MK
                       SET QTY              = 0
                         , LAST_UPDATED_BY  = 'EDI'
                         , LAST_UPDATE_DATE = SYSDATE
                     WHERE EXISTS (
                                    SELECT 1
                                      FROM GT_DDECM_MKT_ORG_DATA ED
                                     WHERE MK.DIVISION_ID   = ED.DIVISION_ID
                                       AND MK.PROJECT_CODE  = ED.PROJECT_CODE
                                       AND MK.SCM_SITE_ID   = ED.SCM_SITE_ID
                                       AND MK.ITEM_ID       = ED.ITEM_ID
                                       AND MK.PLANT_SITE_ID = ED.PLANT_SITE_ID
                                  )
                       AND MK.MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND MK.QTY <> 0;
                END;
                /* EDI 데이터 LOOKUP FROM 기간 이후 데이터 미전송시 MKT_FCST 기존 수량을 전부 0으로 변경 END */

            END;
        END;
        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
        /* CUST_FCST_EDI[Org.] END */
        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */

    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'CUST_FCST_EDI Insert';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            , 'ERROR'
                            , 0
                            , SQLERRM
                            , NULL
                            , SYSDATE
                            , P_IN_PARA_DATA  => V_IN_PARA_DATA
                            , P_SQL_ERR_CODE  => SQLCODE
                            , P_SQL_ERR_MSG   => SQLERRM
                            , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

        RAISE_APPLICATION_ERROR(-20001
                              , '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;
/
-- ##### PROCEDURE PR_DM_PLN_SALES_PLAN_RESULT_MOVE (사내 적용 2026-10-09 15:14:29 · ORA-00979 문장 1→0 · 마커 1)
CREATE OR REPLACE PROCEDURE           "PR_DM_PLN_SALES_PLAN_RESULT_MOVE" 
(
    P_DIVISION_ID  IN VARCHAR2
)
/* ============================================================
 * Program ID   : PR_DM_PLN_SALES_PLAN_RESULT_MOVE
 * Description  :
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2018.03.29    JHBAEK         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *                              [DM_PLN_MKT_FCST] -> [DM_PLN_MKT_FCST_RESULT] 테이블에 자료(과거 1주일) INSERT PROCEDURE
 *                              WEEKLY RUNNNG.
 * 2019.07.12    KHSONG         [CSR ID:4023158] 'RTF_SYS_RP' MEASURE 추가
 * 2020.02.13    HWI1993        COMPANY_ID 추가 안되서 오류발생
 * 2020.03.09    KHSONG         TMM_FCST ADD
 * 2022.04.07    hwi1993        GM JV 작업
 * 2025.04.22    JSSBAE         [E20250401-000548]_선감지(SMS) 대상 기준 정리
 * 2025.06.23    KANG.H.J       [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_DM_PLN_SALES_PLAN_RESULT_MOVE';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    V_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_EVENT_DATE    DATE;
    V_DIVISION_ID   VARCHAR2(4000 CHAR);
BEGIN

    V_DIVISION_ID := NULL;

    /* START LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN

        IF P_DIVISION_ID = 'ALL' THEN
            V_DIVISION_ID := '';
        ELSE
            V_DIVISION_ID := P_DIVISION_ID;
        END IF;

        /* RESULT DATA DELETE */
        DELETE
          FROM DM_PLN_SALES_PLAN_RESULT L
         WHERE L.DIVISION_ID LIKE '%' || V_DIVISION_ID || '%'
           AND L.YYYYMMDD <  TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
           AND L.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 2, 'YYYYMMDD')
           AND L.MEASURE IN ('MKT_FCST', 'CUST_FCST', 'RTF_SYS_RP', 'TMM_FCST');

        /* RESULT DATA INSERT */
        INSERT
          INTO DM_PLN_SALES_PLAN_RESULT
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , COMPANY_ID
             , CELL_PROD_SITE_ID )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY
             , SUM(A.QTY) AS QTY
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , SYSDATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
             , ' ' AS COMPANY_ID
             , A.CELL_PROD_SITE_ID
          FROM DM_PLN_SALES_PLAN A
             , SCM_MST_DIVISION B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND B.DIVISION_ID LIKE '%' || V_DIVISION_ID || '%'
           AND 1 = 1
           AND A.YYYYMMDD <  TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
           AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 2, 'YYYYMMDD')
           AND A.MEASURE IN ('MKT_FCST', 'CUST_FCST', 'RTF_SYS_RP', 'TMM_FCST')
      GROUP BY A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
             , A.CELL_PROD_SITE_ID;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            V_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    END;

    /* END LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

END;
/
-- ##### PROCEDURE PR_SSP_ANL_SHIPMENT_PLAN_FG (사내 적용 2026-10-09 15:13:36 · ORA-00979 문장 2→0 · 마커 2)
CREATE OR REPLACE PROCEDURE PR_SSP_ANL_SHIPMENT_PLAN_FG
(
      P_PLAN_CYCLE           IN VARCHAR2
    , P_PLAN_START_YYYYMMDD  IN VARCHAR2 /* PLAN_NAME */
    , P_PLAN_ID              IN VARCHAR2
    , P_MODELING_ID          IN VARCHAR2
    , P_SEQ                  IN VARCHAR2
    , P_PLAN_TYPE            IN VARCHAR2
    , P_MASTER_ID            IN VARCHAR2
    , P_DIVISION_ID          IN VARCHAR2
    , P_ENGINE_PLAN_ID       IN VARCHAR2
    , P_USER_ID              IN VARCHAR2 DEFAULT 'ssp_batch'
    /* -- , @p_debug       INT OUTPUT */
)
/*
 * Program ID   : PR_SSP_ANL_SHIPMENT_PLAN_FG
 * Description  : PR_SSP_ANL_CREATE_DATA 에서 호출함.
 * OutTable     :
 * Execute      : EXEC PR_SSP_ANL_SHIPMENT_PLAN_FG    @p_plan_cycle          ='DAILY'
                                                    , @p_plan_start_yyyymmdd ='20180807'
                                                    , @p_plan_id             ='103802'
                                                    , @p_modeling_id         ='201'
                                                    , @p_seq                 ='1'
                                                    , @p_plan_type           ='SP'
                                                    , @p_master_id           ='81::DAILY'
                                                    , @p_division_id         ='81'
                                                    , @p_engine_plan_id      ='103802::SP::1'
                                                    , @p_user_id             = 'KTH'
                 -- UI 실행
                 EXEC SSP0009_GET_SHIPMENT_PLAN_FG     @p_from_yyyymmdd        ='20180807'
                                                     , @p_to_yyyymmdd         ='20181001'
                                                     , @p_division_id         ='81'
                                                     , @p_biz_type            ='A'
                                                     , @p_project_code        ='A15HC2001'
                                                     , @p_item_id             ='ACLN1007I-A1'
                                                     , @p_plan_start_yyyymmdd ='20180807'
                                                     , @p_plan_type           ='SP'
                                                     , @p_seq                 ='1'
                                                     , @p_program_id          = 'SSP0009'
                                                     , @p_sheet_name          = 'Shipment Plan FG'
                                                     , @p_user_id             = 'middleware'

 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018.06.12   LTW         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018.06.18   KTH         8주(56일) 추가 로직
 * 2018.07.16   KTH         전극 SCP 반영(ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID,ELECTRODE_TYPE) 추가
                            SCP_MST_FINAL_ITEM_V로 변경, TMP_SSP_PLN_NET_DEMAND_V로 변경
                            파라미터 변경 (PLN과 동일하게 변경),MEASURE를 0으로 추가 로직 변경
 * 2018.07.19   KTH         INCOTERMS 수정
 * 2018.07.27   KTH         INCOTERMS 수정(BOD_ID -> DEMAND_ID)
 * 2018.08.07   KTH         MEASURE(WH_IN_BALANCE) 로직 추가( to site기준의 BOH + 특정일자까지 누적 Fcst qty * (-1) + 특정일자까지 누적 WH_IN total 누적수량)
 * 2018.08.22   KTH         최종입력시점에 MAX(INCOTERMS) 를 INCOTERMS 로 변경함.
 * 2018.09.14   KTH         UNPEGGING 제외 조건 추가 (ENG_DEMAND_ID 는 UNPEGGING 아님)
 * 2018.09.17   KTH         소형(40) Balance데이타 생성시 월별로 계산,Balance(WH_IN) 삭제,  삭제시 속도 개선
 * 2018.11.21   KTH         SHIP_REQ 로직변경(YYYYMMDD = LPST) 추가
 * 2019.08.02   KTH         BALANCE 입력(소형(40)일 경우)  월별 BALANCE 적용로직 삭제
 * 2026.07.06   ZIONEX      [PJ202650304] NextSCM Migration
 */
AS


    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'ssp_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SSP_ANL_SHIPMENT_PLAN_FG';
    V_LOG_TYPE      VARCHAR2(30 CHAR); /* START/END/ERROR/... */
    N_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_TABLE_ID      VARCHAR2(150 CHAR) := 'SSP_ANL_SHIPMENT_PLAN_FG';
    D_EVENT_DATE    DATE;

    /* 임시 실행시간 확인용 */
    V_START_TIME    DATE := SYSDATE;
    V_EXEC_TIME     VARCHAR2(10 CHAR) := ''; /* '[00:00]'; */

    X_INT           NUMBER := 1;
    X_MEASURE       VARCHAR2(100 CHAR);

    V_ROWCOUNT      NUMBER;
    V_TOTAL_SEC     NUMBER;
    V_MIN           NUMBER;
    V_SEC           NUMBER;
    V_ERR_MSG       VARCHAR2(1000 CHAR);
BEGIN
    V_BATCH_USER := P_USER_ID;

  /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := V_PROGRAM_NAME || ':' || ' SSP_ANL_SHIPMENT_PLAN_FG INSERT LOGIC';
    D_EVENT_DATE  := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );

    BEGIN
        /* BEGIN TRAN TX_FG */
          /*----------------------------------------------------------------------------------------------------------- */
          /* 0. temp 테이블 생성 : Measure까지 생성후 마지막에 한번에 입력하기 위해서 */
          /*----------------------------------------------------------------------------------------------------------- */
          /* 원본: IF OBJECT_ID('tempdb..#tmp_SSP_ANL_SHIPMENT_PLAN_FG') IS NOT NULL DROP TABLE ... / CREATE TABLE ...(선언폭=GT_SASF_FG) */
          /* => GTT GT_SASF_FG 사용, 진입부 DELETE 로 초기화. */
          DELETE FROM GT_SASF_FG;

            /*----------------------------------------------------------------------------------------------------------- */
            /* Measure 확인 (FG) */
            /*----------------------------------------------------------------------------------------------------------- */
            /*
            --SHIP PLAN FG MEASURE
            SELECT DBO.FN_GET_MEASURE_CODE('Ship Plan')           -- SHIP_PLAN              -- 1 SHIP_PLAN 입력 (FG)
            SELECT DBO.FN_GET_MEASURE_CODE('Ship Req')            -- SHIP_REQ               -- 1 SHIP_REQ 입력(FG)

            SELECT DBO.FN_GET_MEASURE_CODE('WH In')                 -- WH_IN                -- 2 WH_IN 입력 FG
            SELECT DBO.FN_GET_MEASURE_CODE('Intransit')             -- INTRANSIT            -- 3 INTRANSIT 입력  FG
            SELECT DBO.FN_GET_MEASURE_CODE('MKT FCST')              -- MKT_FCST             -- 4 MKT_FCST 입력 FG

            SELECT * FROM DBO.SCM_MST_SHEET_MEASURE WITH(NOLOCK)  WHERE PROGRAM_ID ='SCP0009'  -- shipment plan FG

                       MKT_FCST         MKT FCST
                       INTRANSIT       Intransit
                       WH_IN_TOTAL      WH In Total  = SUM(WH_IN) + INTRANSIT
                       BALANCE         Balance      = BOH - MKT_FCST + WH_IN_TOTAL
                       WH_IN           WH In
                       SHIP_REQ         Ship Req
                       SHIP_PLAN       Ship Plan
                       SHIP_PLAN_AMEND Ship Plan Amend
            */

            /*----------------------------------------------------------------------------------------------------------- */
            /* 1-1. SHIP_REQ 입력 (FG) */
            /*----------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SASF_FG
                  (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
        )
            SELECT DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,MAX(OPERATION_GROUP)
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,SUM(QTY) AS QTY /* sum */
             FROM (
                    SELECT
                          B.DIVISION_ID
                         ,B.PLAN_START_YYYYMMDD /* plan주의 월요일  ,dbo.FN_GET_BUCKET_YYYYMMDD(0) */
                         ,B.PLAN_TYPE
                         ,B.SEQ
                         ,B.OPERATION_GROUP
                         ,A.PROJECT_CODE
                         ,B.ITEM_ID
                         ,B.TO_SITE
                         ,A.INCOTERMS
                         ,B.FROM_SITE
                         ,B.BOD_ID
                         ,B.TRANSPORT_MODE
                         ,B.MEASURE
                         ,B.YYYYMMDD
                         ,A.ALLOCATION_QTY         AS QTY
                     FROM SSP_PLN_SHIPMENT_PLAN_PEGGING A
                        , SSP_PLN_SHIPMENT_PLAN B


                     WHERE 1 = 1
                     AND A.DIVISION_ID           = B.DIVISION_ID(+)
                     AND A.PLAN_START_YYYYMMDD   = B.PLAN_START_YYYYMMDD(+)
                     AND A.PLAN_TYPE             = B.PLAN_TYPE(+)
                     AND A.SEQ                   = B.SEQ(+)
                     AND A.ORDER_ID              = B.ORDER_ID(+)
                  /* AND A.ENG_DEMAND_ID         = B.ENG_DEMAND_ID */
                     AND B.MEASURE(+)            = 'SHIP_REQ'
                     AND B.SEMI_YN(+)            = 'N'
/* AND B.ENG_DEMAND_ID        <> 'UNPEGGING' */
                       AND A.DIVISION_ID         = P_DIVISION_ID /* '81' */
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD /* '20180409' */
                       AND A.PLAN_TYPE           = P_PLAN_TYPE /* 'PR' */
                       AND A.SEQ                 = P_SEQ /* '9' */
                       AND B.DIVISION_ID         IS NOT NULL
                       AND B.SEMI_YN               = 'N'
                       AND A.ENG_DEMAND_ID        <> 'UNPEGGING'
                       AND TO_DATE(B.YYYYMMDD, 'YYYYMMDD') = A.LPST
/* AND B.ENG_DEMAND_ID        <> 'UNPEGGING' */
                ) X
             GROUP BY
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,TRANSPORT_MODE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  ;

            /*----------------------------------------------------------------------------------------------------------- */
            /* 1-2. SHIP_PLAN 입력 (FG) */
            /*----------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SASF_FG
                  (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
                  )
            SELECT DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,MAX(OPERATION_GROUP)
                  ,NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/') AS PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,SUM(QTY) AS QTY /* sum */
             FROM (
                   SELECT
                          B.DIVISION_ID
                         ,B.PLAN_START_YYYYMMDD /* plan주의 월요일  ,dbo.FN_GET_BUCKET_YYYYMMDD(0) */
                         ,B.PLAN_TYPE
                         ,B.SEQ
                         ,B.OPERATION_GROUP
                         ,A.PROJECT_CODE
                         ,B.ITEM_ID
                         ,B.TO_SITE
                         ,A.INCOTERMS
                         ,B.FROM_SITE
                         ,B.BOD_ID
                         ,B.TRANSPORT_MODE
                         ,B.MEASURE
                         ,B.YYYYMMDD
                         ,A.ALLOCATION_QTY         AS QTY
                     FROM SSP_PLN_SHIPMENT_PLAN_PEGGING A
                        , SSP_PLN_SHIPMENT_PLAN B


                     WHERE 1 = 1
                     AND A.DIVISION_ID           = B.DIVISION_ID(+)
                     AND A.PLAN_START_YYYYMMDD   = B.PLAN_START_YYYYMMDD(+)
                     AND A.PLAN_TYPE             = B.PLAN_TYPE(+)
                     AND A.SEQ                   = B.SEQ(+)
                     AND A.ORDER_ID              = B.ORDER_ID(+)
                  /* AND A.ENG_DEMAND_ID         = B.ENG_DEMAND_ID */
                     AND B.MEASURE(+)            = 'SHIP_PLAN'
                     AND B.SEMI_YN(+)            = 'N'
/* AND B.ENG_DEMAND_ID        <> 'UNPEGGING' */
                       AND A.DIVISION_ID         = P_DIVISION_ID /* '81' */
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD /* '20180409' */
                       AND A.PLAN_TYPE           = P_PLAN_TYPE /* 'PR' */
                       AND A.SEQ                 = P_SEQ /* '9' */
                       AND B.DIVISION_ID         IS NOT NULL
                       AND A.ENG_DEMAND_ID        <> 'UNPEGGING'
/* AND B.ENG_DEMAND_ID        <> 'UNPEGGING' */
                ) X
             GROUP BY
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,TRANSPORT_MODE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  ;

            /*----------------------------------------------------------------------------------------------------------- */
            /* 2-1. WH_IN 입력 FG : SSP_ANL_PROBLEM_REPORT_PEGGING */
            /*----------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SASF_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
                  )
            SELECT DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,'-'                      AS BOD_ID
                  ,'-'                      AS TRANSPORT_MODE
                  ,'WH_IN'                  AS MEASURE
                  ,YYYYMMDD
                  ,SUM(QTY)                 AS QTY
                  FROM (
                        SELECT A.DIVISION_ID
                              ,A.PLAN_START_YYYYMMDD
                              ,A.PLAN_TYPE
                              ,A.SEQ
                              ,A.OPERATION_GROUP
                              ,SUBSTR(FN_SCM_SPLIT(A.ENG_DEMAND_ID,2,'::'), 1, 100)                             AS PROJECT_CODE
                              ,A.ITEM_ID
                              ,A.TO_SITE
                              ,FN_SCM_SPLIT(FN_SCM_SPLIT(A.STOCK_PLAN_LOT_ID,2,'::'),2,'~') AS INCOTERMS
                              /* ,dbo.fn_scm_split(a.eng_demand_id,7,'::')                             AS from_site */
                              ,FN_SCM_SPLIT(A.STOCK_PLAN_LOT_ID,5,'::')                         AS FROM_SITE
                              ,SUBSTR((CASE WHEN FN_SCM_SPLIT(A.STOCK_PLAN_LOT_ID,4,'::') < P_PLAN_START_YYYYMMDD THEN P_PLAN_START_YYYYMMDD
                                     ELSE FN_SCM_SPLIT(A.STOCK_PLAN_LOT_ID,4,'::')
                                     END), 1, 8)                                                           AS YYYYMMDD
                              ,A.PLANNED_QTY                            AS QTY
                          FROM SSP_ANL_PROBLEM_REPORT_PEGGING A
                          WHERE 1=1
                            AND A.DIVISION_ID            = P_DIVISION_ID /* N'81'          -- */
                            AND A.PLAN_START_YYYYMMDD    = P_PLAN_START_YYYYMMDD /* N'20180521'    -- */
                            AND A.PLAN_TYPE              = P_PLAN_TYPE /* N'PR'          -- */
                            AND A.SEQ                    = P_SEQ /* N'1'           -- */
                            AND A.STOCK_PLAN_LOT_ID   LIKE 'INT%'

                      ) X
             GROUP BY
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,YYYYMMDD
                  ;

            /*----------------------------------------------------------------------------------------------------------- */
            /* 2-2. WH_IN 입력 FG : SSP_PLN_SHIPMENT_PLAN_PEGGING */
            /*----------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_SASF_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
                  )
            SELECT DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,MAX(OPERATION_GROUP)
                  ,NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/') AS PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,'-'   AS BOD_ID
                  ,'-'   AS TRANSPORT_MODE
                  ,MEASURE
                  ,YYYYMMDD
                  ,SUM(QTY)
                  FROM (

                        SELECT
                          B.DIVISION_ID
                         ,B.PLAN_START_YYYYMMDD /* plan주의 월요일  ,dbo.FN_GET_BUCKET_YYYYMMDD(0) */
                         ,B.PLAN_TYPE
                         ,B.SEQ
                         ,B.OPERATION_GROUP
                         ,A.PROJECT_CODE
                         ,B.ITEM_ID
                         ,B.TO_SITE
                         ,A.INCOTERMS
                         ,B.FROM_SITE
                         ,B.BOD_ID
                         ,B.TRANSPORT_MODE
                         ,'WH_IN' AS MEASURE
                         ,TO_CHAR(B.END_TIME, 'YYYYMMDD') AS YYYYMMDD
                         ,A.ALLOCATION_QTY         AS QTY
                     FROM SSP_PLN_SHIPMENT_PLAN_PEGGING A
                        , SSP_PLN_SHIPMENT_PLAN B


              WHERE 1 = 1
                     AND A.DIVISION_ID           = B.DIVISION_ID(+)
                     AND A.PLAN_START_YYYYMMDD   = B.PLAN_START_YYYYMMDD(+)
                     AND A.PLAN_TYPE             = B.PLAN_TYPE(+)
                     AND A.SEQ                   = B.SEQ(+)
                     AND A.ORDER_ID              = B.ORDER_ID(+)
                  /* AND A.ENG_DEMAND_ID         = B.ENG_DEMAND_ID */
                     AND B.MEASURE(+)            = 'SHIP_PLAN'
                     AND B.SEMI_YN(+)            = 'N'
/* AND B.ENG_DEMAND_ID        <> 'UNPEGGING' */
                       AND A.DIVISION_ID         = P_DIVISION_ID /* '81' */
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD /* '20180409' */
                       AND A.PLAN_TYPE           = P_PLAN_TYPE /* 'PR' */
                       AND A.SEQ                 = P_SEQ /* '9' */
                       AND B.DIVISION_ID         IS NOT NULL
                       AND A.ENG_DEMAND_ID        <> 'UNPEGGING'
/* AND B.ENG_DEMAND_ID        <> 'UNPEGGING' */

                      ) X
             GROUP BY
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,PROJECT_CODE
                  ,NVL(PROJECT_CODE,'/')
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,MEASURE
                  ,YYYYMMDD
                  ;

            /*----------------------------------------------------------------------------------------------------------- */
          /* 7. ALLOCATION 추가 */
          /*----------------------------------------------------------------------------------------------------------- */
           INSERT INTO GT_SASF_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
                  )
                 SELECT A.DIVISION_ID /* DIVISION_ID */
                       ,A.PLAN_START_YYYYMMDD /* PLAN_START_YYYYMMDD */
                       ,A.PLAN_TYPE /* PLAN_TYPE */
                       ,A.SEQ /* SEQ */
                       ,A.OPERATION_GROUP /* OPERATION_GROUP */
                       ,A.PROJECT_CODE /* PROJECT_CODE */
                       ,A.ITEM_ID /* ITEM_ID */
                       ,A.SALES_SITE_ID         AS TO_SITE /* TO_SITE */
                       ,A.INCOTERMS /* INCOTERMS */
                       ,'-'                     AS FROM_SITE /* FROM_SITE */
                       ,'-'                     AS BOD_ID /* BOD_ID */
                       ,'ALLOCATION'            AS MEASURE /* MEASURE */
                       ,A.YYYYMMDD /* YYYYMMDD */
                       ,SUM(NVL(A.ALLOCATION_QTY,0))  AS QTY /* QTY */
                  FROM SSP_PLN_ALLOCATION A
                 WHERE 0 = 0
                   AND A.DIVISION_ID         = P_DIVISION_ID /* '81' */
                   AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD /* '20180409' */
                   AND A.PLAN_TYPE           = P_PLAN_TYPE /* 'PR' */
                   AND A.SEQ                 = P_SEQ /* '9' */
                  GROUP BY
                       DIVISION_ID
                      ,PLAN_START_YYYYMMDD
                      ,PLAN_TYPE
                      ,SEQ
                      ,OPERATION_GROUP
                      ,PROJECT_CODE
                      ,ITEM_ID
                      ,SALES_SITE_ID
                      ,INCOTERMS
                      ,FROM_SITE
                      ,YYYYMMDD
                      ;
            /*----------------------------------------------------------------------------------------------------------- */
            /* 5. MKT_FCST 입력 FG */
           /*----------------------------------------------------------------------------------------------------------- */

            DELETE FROM GT_SASF_NET_DEMAND;

            INSERT INTO GT_SASF_NET_DEMAND
                  (
                    DIVISION_ID
                   ,PLAN_START_YYYYMMDD
                   ,PLAN_TYPE
                   ,SEQ
                   ,MASTER_ID
                   ,ENG_PLAN_ID
                   ,PROJECT_CODE
                   ,ITEM_ID
                   ,SALES_SITE_ID
                   ,INCOTERMS
                   ,YYYYMMDD
                   ,SPLIT_QTY
                  )
           SELECT
                     A.DIVISION_ID
                    ,A.PLAN_START_YYYYMMDD
                    ,A.PLAN_TYPE
                    ,A.SEQ
                    ,A.MASTER_ID
                    ,A.ENG_PLAN_ID
                    ,NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/')  AS PROJECT_CODE
                    ,A.ITEM_ID
                    ,A.SALES_SITE_ID
                    ,A.INCOTERMS
                    ,A.YYYYMMDD
                    ,A.SPLIT_QTY
                FROM SCP_PLN_NET_DEMAND_V A
               WHERE VALIDATE_CONVERSION(A.SEQ AS NUMBER) = 1
                 AND A.DIVISION_ID           = P_DIVISION_ID
                 AND A.PLAN_START_YYYYMMDD   = P_PLAN_START_YYYYMMDD
                 AND A.PLAN_TYPE             = P_PLAN_TYPE
                 AND A.SEQ                   = P_SEQ
                 AND A.MASTER_ID             = P_MASTER_ID
                 AND A.ENG_PLAN_ID           = P_ENGINE_PLAN_ID
                 ;

             INSERT INTO GT_SASF_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  /* ,ORIGIN_FROM_DIVISION_ID */
                  /* ,ORIGIN_TO_DIVISION_ID */
                  /* ,ELECTRODE_TYPE */
                  ,QTY
                  )

              SELECT
                     SUBSTR(A.DIVISION_ID, 1, 30)                                    AS DIVISION_ID
                    ,SUBSTR(A.PLAN_START_YYYYMMDD, 1, 8)                             AS PLAN_START_YYYYMMDD
                    ,SUBSTR(A.PLAN_TYPE, 1, 50)                                      AS PLAN_TYPE
                    ,A.SEQ
                    ,C.OPERATION_GROUP   AS OPERATION_GROUP
                    ,SUBSTR(A.PROJECT_CODE, 1, 100)                                  AS PROJECT_CODE
                    ,SUBSTR(A.ITEM_ID, 1, 100)                                       AS ITEM_ID
                    ,SUBSTR(A.SALES_SITE_ID, 1, 100)                                 AS TO_SITE
                    ,SUBSTR(A.INCOTERMS, 1, 100)                                     AS INCOTERMS
                    , '-'                                                       AS FROM_SITE
                    , '-'                                                       AS BOD_ID
                    ,'MKT_FCST'                                                 AS MEASURE
                    ,SUBSTR(A.YYYYMMDD, 1, 8)                                        AS YYYYMMDD
                    ,SUM(A.SPLIT_QTY)
                FROM GT_SASF_NET_DEMAND A
                   , SCP_MST_FINAL_ITEM_V C
                /* [FMT ③ §4.72] ANSI INNER JOIN -> 콤마 + WHERE 조인조건. */
                /* ON 의 A.DIVISION_ID = P_DIVISION_ID 는 아래 WHERE 에 동일 술어가 있어 옮기지 않는다(로직 동일). */
               WHERE A.ITEM_ID             = C.ITEM_ID
                 AND VALIDATE_CONVERSION(A.SEQ AS NUMBER) = 1
                 AND A.DIVISION_ID           = P_DIVISION_ID
                 AND A.PLAN_START_YYYYMMDD   = P_PLAN_START_YYYYMMDD
                 AND A.PLAN_TYPE             = P_PLAN_TYPE
                 AND A.SEQ                   = P_SEQ
                 AND A.MASTER_ID             = P_MASTER_ID
                 AND A.ENG_PLAN_ID           = P_ENGINE_PLAN_ID

/* AND ISNUMERIC(A.seq)        = 1 */
            GROUP BY
                     A.DIVISION_ID
                    ,A.PLAN_START_YYYYMMDD
                    ,A.PLAN_TYPE
                    ,A.SEQ
                    ,C.OPERATION_GROUP
                    ,A.PROJECT_CODE
                    ,A.ITEM_ID
                    ,A.SALES_SITE_ID
                    ,A.INCOTERMS
                    ,A.YYYYMMDD
                    ;

            /*----------------------------------------------------------------------------------------------------------- */
            /* 5. SHIP_PLAN_AMEND 입력 FG */
            /*----------------------------------------------------------------------------------------------------------- */
                 INSERT INTO GT_SASF_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
                  )
              SELECT DIVISION_ID /* DIVISION_ID */
                  ,PLAN_START_YYYYMMDD /* PLAN_START_YYYYMMDD */
                  ,PLAN_TYPE /* PLAN_TYPE */
                  ,SEQ /* SEQ */
                  ,OPERATION_GROUP /* OPERATION_GROUP */
                  ,NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/') AS PROJECT_CODE /* PROJECT_CODE */
                  ,ITEM_ID /* ITEM_ID */
                  ,TO_SITE /* TO_SITE */
                  ,INCOTERMS /* INCOTERMS */
                  ,FROM_SITE /* FROM_SITE */
                  ,BOD_ID /* BOD_ID */
                 ,'SHIP_PLAN_AMEND' AS MEASURE /* MEASURE */
                  ,YYYYMMDD /* YYYYMMDD */
                  ,QTY /* QTY */
              FROM GT_SASF_FG
              WHERE MEASURE ='SHIP_PLAN'
              ;

          /*----------------------------------------------------------------------------------------------------------- */
          /* 6. WH_IN_TOTAL 입력 FG  = SUM(WH_IN) + INTRANSIT */
          /*----------------------------------------------------------------------------------------------------------- */
          /*
                 INSERT INTO #tmp_SSP_ANL_SHIPMENT_PLAN_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  ,QTY
                  )
              SELECT DIVISION_ID                                  --DIVISION_ID
                    ,PLAN_START_YYYYMMDD                          --PLAN_START_YYYYMMDD
                    ,PLAN_TYPE                                    --PLAN_TYPE
                    ,SEQ                   --SEQ
                    ,OPERATION_GROUP                              --OPERATION_GROUP
                    ,PROJECT_CODE                                 --PROJECT_CODE
                    ,ITEM_ID                                      --ITEM_ID
                    ,TO_SITE                                      --TO_SITE
                    ,INCOTERMS                                    --INCOTERMS
                    ,'-'                  AS FROM_SITE            --FROM_SITE
                    ,'-'         AS BOD_ID               --BOD_ID
                    ,'WH_IN_TOTAL'        AS MEASURE              --MEASURE
                    ,YYYYMMDD                                     --YYYYMMDD
                    ,SUM(ISNULL(QTY,0))                           --QTY
               FROM #tmp_SSP_ANL_SHIPMENT_PLAN_FG  WITH(NOLOCK)
              WHERE MEASURE IN ('WH_IN','INTRANSIT')
              GROUP BY
                    DIVISION_ID
                   ,PLAN_START_YYYYMMDD
                   ,PLAN_TYPE
                   ,SEQ
                   ,OPERATION_GROUP
                   ,PROJECT_CODE
                   ,ITEM_ID
                   ,TO_SITE
                   ,INCOTERMS
                   ,YYYYMMDD
                   ;
           */

          /*----------------------------------------------------------------------------------------------------------- */
          /* 7-1. MKT_FCST OR INTRANSIT OR WH_IN_TOTAL 이 존재하지 않는 경우, 해당 MEASURE를 0으로 추가 */
          /* (비고) FROM SITE TO SITE 출하계획이 존재하지 않는 경우, 관련 MEASURE가 미생성되는 것은 허용함 */
          /* ( WH_IN, SHIP_REQ, SHIP_PLAN, SHIP_PLAN_AMEND ) */
          /*----------------------------------------------------------------------------------------------------------- */

          WHILE X_INT < 3
          LOOP

               X_MEASURE := ( CASE X_INT WHEN 1 THEN 'MKT_FCST'
                                                 WHEN 2 THEN 'ALLOCATION'
                                                /* WHEN 3 THEN 'WH_IN_TOTAL' */
                                     END);


                INSERT INTO GT_SASF_FG
                     (
                       DIVISION_ID
                      ,PLAN_START_YYYYMMDD
                      ,PLAN_TYPE
                      ,SEQ
                      ,OPERATION_GROUP
                      ,PROJECT_CODE
                      ,ITEM_ID
                      ,TO_SITE
                      ,INCOTERMS
                      ,FROM_SITE
                      ,BOD_ID
                      ,MEASURE
                      ,YYYYMMDD
                      /* ,ORIGIN_FROM_DIVISION_ID */
                      /* ,ORIGIN_TO_DIVISION_ID */
                      /* ,ELECTRODE_TYPE */
                      ,QTY
                      )
               SELECT
                      SUB.DIVISION_ID /* DIVISION_ID */
                     ,SUB.PLAN_START_YYYYMMDD /* PLAN_START_YYYYMMDD */
                     ,SUB.PLAN_TYPE /* PLAN_TYPE */
                     ,SUB.SEQ /* SEQ */
                     ,SUB.OPERATION_GROUP /* OPERATION_GROUP */
                     ,SUB.PROJECT_CODE /* PROJECT_CODE */
                     ,SUB.ITEM_ID /* ITEM_ID */
                     ,SUB.TO_SITE /* TO_SITE */
                     ,SUB.INCOTERMS /* INCOTERMS */
                     ,SUB.FROM_SITE /* FROM_SITE */
                     ,SUB.BOD_ID /* BOD_ID */
                     ,SUB.MEASURE /* MEASURE */
                     ,SUB.YYYYMMDD /* YYYYMMDD */
                     /* ,SUB.ORIGIN_FROM_DIVISION_ID */
                     /* ,SUB.ORIGIN_TO_DIVISION_ID */
                     /* ,SUB.ELECTRODE_TYPE */
                     ,0   AS QTY /* QTY */
                FROM
                    (
                        SELECT
                               DIVISION_ID
                              ,PLAN_START_YYYYMMDD
                              ,PLAN_TYPE
                              ,SEQ
                              ,OPERATION_GROUP
                              ,PROJECT_CODE
                              ,ITEM_ID
                              ,TO_SITE
                              ,INCOTERMS
                              ,'-'        AS FROM_SITE
                              ,'-'        AS BOD_ID
                              ,X_MEASURE AS MEASURE
                              ,YYYYMMDD
                              /* ,ORIGIN_FROM_DIVISION_ID */
                              /* ,ORIGIN_TO_DIVISION_ID */
                              /* ,ELECTRODE_TYPE */
                         FROM
                              ( /* 56 DAYS */
                                 SELECT C.BASIS_YYYYMMDD AS YYYYMMDD
                                   FROM SCM_SYS_CALENDAR_M    C
                                  WHERE 1=1
                                    AND C.BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
                                    AND C.BASIS_YYYYMMDD <  TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD') /* 8주(56일) */
                              ) A
                            , (
                                 SELECT DISTINCT
                                        DIVISION_ID
                                       ,PLAN_START_YYYYMMDD
                                       ,PLAN_TYPE
                                       ,SEQ
                                       ,OPERATION_GROUP
                                       ,PROJECT_CODE
                                       ,ITEM_ID
                                       ,TO_SITE
                                       ,INCOTERMS
                                       /* ,ORIGIN_FROM_DIVISION_ID */
                                       /* ,ORIGIN_TO_DIVISION_ID */
                                       /* ,ELECTRODE_TYPE */
                                  FROM GT_SASF_FG X
                                 WHERE 1=1
                              ) B
                    ) SUB
                    WHERE 1=1
                      AND NOT EXISTS (
                                       SELECT 'X'
                                         FROM GT_SASF_FG Z
                                        WHERE 1=1
                                          AND Z.DIVISION_ID              = SUB.DIVISION_ID
                                          AND Z.PLAN_START_YYYYMMDD      = SUB.PLAN_START_YYYYMMDD
                                          AND Z.PLAN_TYPE                = SUB.PLAN_TYPE
                                          AND Z.SEQ    = SUB.SEQ
                                          AND Z.OPERATION_GROUP          = SUB.OPERATION_GROUP
                                          AND Z.PROJECT_CODE             = SUB.PROJECT_CODE
                                          AND Z.ITEM_ID                  = SUB.ITEM_ID
                                          AND Z.TO_SITE                  = SUB.TO_SITE
                                          AND Z.INCOTERMS                = SUB.INCOTERMS
                                          AND Z.MEASURE                  = X_MEASURE
                                          AND Z.YYYYMMDD                 = SUB.YYYYMMDD
                                          /* AND Z.ORIGIN_FROM_DIVISION_ID  = SUB.ORIGIN_FROM_DIVISION_ID */
                                          /* AND Z.ORIGIN_TO_DIVISION_ID    = SUB.ORIGIN_TO_DIVISION_ID */
                                          /* AND Z.ELECTRODE_TYPE           = SUB.ELECTRODE_TYPE */
                                     );

               X_INT := X_INT + 1;

           END LOOP;

          /*----------------------------------------------------------------------------------------------------------- */
          /* 7-2. MEASURE별 BUCKET일자별 0 채우기 */
          /*----------------------------------------------------------------------------------------------------------- */

            INSERT INTO GT_SASF_FG
                 (
                   DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,YYYYMMDD
                  /* ,ORIGIN_FROM_DIVISION_ID */
                  /* ,ORIGIN_TO_DIVISION_ID */
                  /* ,ELECTRODE_TYPE */
                  ,QTY
                  )
           SELECT
                  SUB.DIVISION_ID /* DIVISION_ID */
                 ,SUB.PLAN_START_YYYYMMDD /* PLAN_START_YYYYMMDD */
                 ,SUB.PLAN_TYPE /* PLAN_TYPE */
                 ,SUB.SEQ /* SEQ */
                 ,SUB.OPERATION_GROUP /* OPERATION_GROUP */
                 ,SUB.PROJECT_CODE /* PROJECT_CODE */
                 ,SUB.ITEM_ID /* ITEM_ID */
                 ,SUB.TO_SITE /* TO_SITE */
                 ,SUB.INCOTERMS /* INCOTERMS */
                 ,SUB.FROM_SITE /* FROM_SITE */
                 ,SUB.BOD_ID /* BOD_ID */
                 ,SUB.MEASURE /* MEASURE */
                 ,SUB.YYYYMMDD /* YYYYMMDD */
                 /* ,SUB.ORIGIN_FROM_DIVISION_ID */
                 /* ,SUB.ORIGIN_TO_DIVISION_ID */
                 /* ,SUB.ELECTRODE_TYPE */
                 ,0   AS QTY /* QTY */
            FROM
                (
                    SELECT
                           DIVISION_ID
                          ,PLAN_START_YYYYMMDD
                          ,PLAN_TYPE
                          ,SEQ
                          ,OPERATION_GROUP
                          ,PROJECT_CODE
                          ,ITEM_ID
                          ,TO_SITE
                          ,INCOTERMS
                          ,FROM_SITE
                          ,BOD_ID
                          ,MEASURE
                          ,YYYYMMDD
                          /* ,ORIGIN_FROM_DIVISION_ID */
                          /* ,ORIGIN_TO_DIVISION_ID */
                          /* ,ELECTRODE_TYPE */
                     FROM
                          ( /* 56 DAYS */
                             SELECT C.BASIS_YYYYMMDD AS YYYYMMDD
                               FROM SCM_SYS_CALENDAR_M    C
                             WHERE 1=1
                                AND C.BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
/* AND C.BASIS_YYYYMMDD <  CONVERT(VARCHAR,DATEADD(D,364,CONVERT(DATETIME,@p_plan_start_yyyymmdd,112)),112) */
                                AND C.BASIS_YYYYMMDD <  TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD') /* 8주(56일) */
                          ) A
                        , (
                             SELECT DISTINCT
                                    DIVISION_ID
                                   ,PLAN_START_YYYYMMDD
                                   ,PLAN_TYPE
                                   ,SEQ
                                   ,OPERATION_GROUP
                                   ,PROJECT_CODE
                                   ,ITEM_ID
                                   ,TO_SITE
                                   ,INCOTERMS
                                   ,FROM_SITE
                                   ,BOD_ID
                                   ,MEASURE
                                   /* ,ORIGIN_FROM_DIVISION_ID */
                                   /* ,ORIGIN_TO_DIVISION_ID */
                                   /* ,ELECTRODE_TYPE */
                              FROM GT_SASF_FG X
                             WHERE 1=1
                          ) B
                ) SUB
                WHERE 1=1
                  AND NOT EXISTS (
                                   SELECT 'X'
                                     FROM GT_SASF_FG Z
                                    WHERE 1=1
                                      AND Z.DIVISION_ID              = SUB.DIVISION_ID
                                      AND Z.PLAN_START_YYYYMMDD      = SUB.PLAN_START_YYYYMMDD
                                      AND Z.PLAN_TYPE                = SUB.PLAN_TYPE
                                      AND Z.SEQ          = SUB.SEQ
                                      AND Z.OPERATION_GROUP          = SUB.OPERATION_GROUP
                                      AND Z.PROJECT_CODE             = SUB.PROJECT_CODE
                                      AND Z.ITEM_ID                  = SUB.ITEM_ID
                                      AND Z.TO_SITE                  = SUB.TO_SITE
                                      AND Z.INCOTERMS                = SUB.INCOTERMS
                                      AND Z.FROM_SITE                = SUB.FROM_SITE
                                      AND Z.BOD_ID                   = SUB.BOD_ID
                                      AND Z.MEASURE                  = SUB.MEASURE
                                      AND Z.YYYYMMDD                 = SUB.YYYYMMDD
                                      /* AND Z.ORIGIN_FROM_DIVISION_ID  = SUB.ORIGIN_FROM_DIVISION_ID */
                                      /* AND Z.ORIGIN_TO_DIVISION_ID    = SUB.ORIGIN_TO_DIVISION_ID */
                                      /* AND Z.ELECTRODE_TYPE          = SUB.ELECTRODE_TYPE */
                                 );

          /*----------------------------------------------------------------------------------------------------------- */
          /* 8. BALANCE 계산값 생성 */
          /*----------------------------------------------------------------------------------------------------------- */
          /*----------------------------------------------------------------------------------------------------------- */
          /* 8.1 BALANCE에 사용할 MEASURE 임시테이블 생성  ('MKT_FCST','ALLOCATION') OR ('MKT_FCST','WH_IN')  = ('MKT_FCST','WH_IN','ALLOCATION') */
          /*---------------------------------------------------------------------------------------------------------- */
             DELETE FROM GT_SASF_Z;
             INSERT INTO GT_SASF_Z
                  (
                    DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,YYYYMMDD
                  )
             SELECT   DISTINCT
                    DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,YYYYMMDD
                  /* ,ORIGIN_FROM_DIVISION_ID */
                  /* ,ORIGIN_TO_DIVISION_ID */
                  /* ,ELECTRODE_TYPE */
              FROM GT_SASF_FG
              WHERE 1=1
                AND MEASURE            IN ('MKT_FCST','ALLOCATION')
                GROUP BY
                    DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,YYYYMMDD
                  ,OPERATION_GROUP
                  /* ,ORIGIN_FROM_DIVISION_ID */
                  /* ,ORIGIN_TO_DIVISION_ID */
                  /* ,ELECTRODE_TYPE */
                  ;

             DELETE FROM GT_SASF_Y;
             INSERT INTO GT_SASF_Y
                  (
                    DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,YYYYMMDD
                  )
         SELECT   DISTINCT
                    DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,OPERATION_GROUP
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,YYYYMMDD
                  /* ,ORIGIN_FROM_DIVISION_ID */
                  /* ,ORIGIN_TO_DIVISION_ID */
                  /* ,ELECTRODE_TYPE */
              FROM GT_SASF_FG
              WHERE 1=1
                AND MEASURE            IN ('MKT_FCST','WH_IN')
                GROUP BY
                    DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,TO_SITE
                  ,INCOTERMS
                  ,YYYYMMDD
                  ,OPERATION_GROUP
                  ;

          /*----------------------------------------------------------------------------------------------------------- */
          /* 8.2 BALANCE에 사용할 #BOH 임시테이블 생성 */
          /*---------------------------------------------------------------------------------------------------------- */
          /*
                select @x_site_type = site_type
                  from scm_mst_site     s with(nolock)
                 where 1=1
                   and s.division_id    = @p_division_id
                   and s.scm_site_id    = @p_scm_site_id
                   ;

               if @x_site_type = 'PLANT'
               begin

                    select @x_boh_qty = sum(isnull(psi_boh_qty,0))
                      from ssp_pln_plant_onhand with(nolock)
                     where division_id               = @p_division_id
                       and stock_type    NOT IN ( 'FOR_STOCKPLAN','FORMING','FORMED','CHARING','CHAR','A_MOVE_WH','A_OUT_WH')   --셀 활성화진행중 이후 특성,창고재고 제외
                       and plan_start_yyyymmdd       = @p_plan_start_yyyymmdd
                       and plan_type                 = @p_plan_type
                       and seq                       = @p_plan_seq
                       and site_id                   = @p_scm_site_id
                       and item_id                   = @p_item_id
                       and yyyymmdd                  = @p_yyyymmdd
                       ;

               end
            else
               begin

                    select @x_boh_qty = sum(isnull(psi_boh_qty,0))
                      from ssp_pln_sales_onhand with(nolock)
                     where division_id               = @p_division_id
                       and plan_start_yyyymmdd       = @p_plan_start_yyyymmdd
                       and plan_type                 = @p_plan_type
                       and seq                       = @p_plan_seq
                       and site_id                   = @p_scm_site_id
                       and item_id                   = @p_item_id
                       and yyyymmdd                  = @p_yyyymmdd
                       ;

               end
                */
             DELETE FROM GT_SASF_BOH;
             INSERT INTO GT_SASF_BOH
                  (
                    DIVISION_ID
                 ,PLAN_START_YYYYMMDD
                 ,PLAN_TYPE
                 ,SEQ
                 ,SITE_ID
                 ,ITEM_ID
                 ,PSI_BOH_QTY
                  )
           SELECT DIVISION_ID
                 ,PLAN_START_YYYYMMDD
                 ,PLAN_TYPE
                 ,SEQ
                 ,SITE_ID
                 ,ITEM_ID
                 ,PSI_BOH_QTY
             FROM SSP_PLN_SALES_ONHAND
            WHERE 0 = 0
              AND DIVISION_ID               = P_DIVISION_ID /* '81' */
/* and stock_type                NOT IN ( 'FOR_STOCKPLAN','FORMING','FORMED','CHARING','CHAR','A_MOVE_WH','A_OUT_WH')  --셀 활성화진행중 이후 특성,창고재고 제외 */
              AND PLAN_START_YYYYMMDD       = P_PLAN_START_YYYYMMDD /* '20180416' */
              AND PLAN_TYPE                 = P_PLAN_TYPE /* 'PR' */
              AND SEQ                       = P_SEQ /* 1 */
              AND YYYYMMDD                  = P_PLAN_START_YYYYMMDD /* 계획시작일 */
              ;

          /*----------------------------------------------------------------------------------------------------------- */
          /* 8.3 BALANCE 입력 */
          /*---------------------------------------------------------------------------------------------------------- */
          /* BALANCE 속도 때문에 CLUSTERED INDEX 추가 함. */
            /* DROP INDEX #tmp_SSP_ANL_SHIPMENT_PLAN_FG.IX01_#tmp_SSP_ANL_SHIPMENT_PLAN_FG */
          /* Oracle: GTT 세션 인덱스 런타임 생성 불가/불요(물리 최적화). 원본 CLUSTERED INDEX 정의는 배포시 GTT DDL에서 검토. */
          /* CREATE CLUSTERED INDEX IX01 ON #tmp ( DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, PROJECT_CODE, ITEM_ID, TO_SITE, INCOTERMS, MEASURE, YYYYMMDD ) */
              /* 00:27초 */
            /* PRINT N'BALANCE 계산전'; */


              INSERT INTO GT_SASF_FG
                      (
                        DIVISION_ID
                        ,PLAN_START_YYYYMMDD
                        ,PLAN_TYPE
                        ,SEQ
                        ,OPERATION_GROUP
                        ,PROJECT_CODE
                        ,ITEM_ID
                        ,TO_SITE
                        ,INCOTERMS
                        ,FROM_SITE
                        ,BOD_ID
                        ,MEASURE
                        ,YYYYMMDD
                        /* ,ORIGIN_FROM_DIVISION_ID */
                        /* ,ORIGIN_TO_DIVISION_ID */
                        /* ,ELECTRODE_TYPE */
                        ,QTY
                        )
                SELECT
                        Z.DIVISION_ID
                       ,Z.PLAN_START_YYYYMMDD
                       ,Z.PLAN_TYPE
                       ,Z.SEQ
                       ,Z.OPERATION_GROUP
                       ,Z.PROJECT_CODE
                       ,Z.ITEM_ID
                       ,Z.TO_SITE
                       ,Z.INCOTERMS
                       ,'-' AS FROM_SITE
                       ,'-' AS BOD_ID
                       ,'BALANCE' AS MEASURE
                       ,Z.YYYYMMDD
                       /* ,Z.ORIGIN_FROM_DIVISION_ID */
                       /* ,Z.ORIGIN_TO_DIVISION_ID */
                       /* ,Z.ELECTRODE_TYPE */
                       ,( SELECT
                               NVL( SUM(CASE MEASURE WHEN 'MKT_FCST'   THEN -1 * NVL(QTY,0)
                                                        WHEN 'ALLOCATION' THEN      NVL(QTY,0)
                                                 ELSE 0.0
                                     END),0)
                           FROM GT_SASF_FG X
                         WHERE 1=1
                           AND X.DIVISION_ID          = Z.DIVISION_ID
                           AND X.PLAN_START_YYYYMMDD  = Z.PLAN_START_YYYYMMDD
                           AND X.PLAN_TYPE            = Z.PLAN_TYPE
                           AND X.SEQ                  = Z.SEQ
                           AND X.PROJECT_CODE         = Z.PROJECT_CODE
                           AND X.ITEM_ID              = Z.ITEM_ID
                           AND X.TO_SITE              = Z.TO_SITE
                           AND X.INCOTERMS            = Z.INCOTERMS
                           AND X.MEASURE              IN ('MKT_FCST','ALLOCATION')
                           /* AND X.ORIGIN_FROM_DIVISION_ID   = Z.ORIGIN_FROM_DIVISION_ID */
                           /* AND X.ORIGIN_TO_DIVISION_ID     = Z.ORIGIN_TO_DIVISION_ID */
                           /* AND X.ELECTRODE_TYPE            = Z.ELECTRODE_TYPE */
                           AND X.YYYYMMDD            <= Z.YYYYMMDD
                         )     AS PSI_BOH_QTY
                 FROM GT_SASF_Z Z
                WHERE 1=1
                AND Z.YYYYMMDD   < TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD') /* 8주(56일) 추가 */
                ;

          /*----------------------------------------------------------------------------------------------------------- */
          /* 8.3 BALANCE 입력(소형(40)일 경우)  월별 BALANCE 적용 */
          /*---------------------------------------------------------------------------------------------------------- */
          /*
          IF @p_division_id = '40'  -- MEASURE ='BALANCE'
          BEGIN
                UPDATE XX
                SET XX.QTY   = ISNULL((YY.ALLOCATION_SUM_MONTH + MKT_FCST_SUM_MONTH), 0)
                FROM #tmp_SSP_ANL_SHIPMENT_PLAN_FG XX with (nolock)
                INNER JOIN  (
                               SELECT DISTINCT DIVISION_ID,PLAN_START_YYYYMMDD,PLAN_TYPE,SEQ
                                  ,PROJECT_CODE,ITEM_ID,TO_SITE,INCOTERMS,'BALANCE' AS MEASURE,YYYYMMDD
                               ,(SUM((CASE WHEN MEASURE ='ALLOCATION' THEN ISNULL(QTY,0) ELSE 0 END))  OVER (PARTITION BY PROJECT_CODE,ITEM_ID,TO_SITE,INCOTERMS,SUBSTRING(YYYYMMDD,1,6) ORDER BY PROJECT_CODE,ITEM_ID,TO_SITE,INCOTERMS,YYYYMMDD))       AS ALLOCATION_SUM_MONTH
                               ,(SUM((CASE WHEN MEASURE ='MKT_FCST'   THEN ISNULL(QTY,0) ELSE 0 END))  OVER (PARTITION BY PROJECT_CODE,ITEM_ID,TO_SITE,INCOTERMS,SUBSTRING(YYYYMMDD,1,6) ORDER BY PROJECT_CODE,ITEM_ID,TO_SITE,INCOTERMS,YYYYMMDD) * -1)  AS MKT_FCST_SUM_MONTH
                               FROM #tmp_SSP_ANL_SHIPMENT_PLAN_FG X with (nolock)
                               WHERE 0 = 0
                               AND  X.MEASURE in ('ALLOCATION','MKT_FCST')
                           ) YY
                       ON  XX.DIVISION_ID             = YY.DIVISION_ID
                       AND XX.PLAN_START_YYYYMMDD     = YY.PLAN_START_YYYYMMDD
                       AND XX.PLAN_TYPE               = YY.PLAN_TYPE
                       AND XX.SEQ                     = YY.SEQ
                       AND XX.PROJECT_CODE            = YY.PROJECT_CODE
                       AND XX.ITEM_ID                 = YY.ITEM_ID
                       AND XX.TO_SITE                 = YY.TO_SITE
                       AND XX.INCOTERMS               = YY.INCOTERMS
                       AND XX.YYYYMMDD                = YY.YYYYMMDD
                       AND XX.MEASURE                 = YY.MEASURE        -- 'MKT_FCST_SUM_MONTH'
                       AND XX.MEASURE                 = 'BALANCE'
          END  -- @p_division_id = '40'
          */
          /*----------------------------------------------------------------------------------------------------------- */
          /* 8.4 WH_IN_BALANCE 입력(to site기준의 BOH + 특정일자까지 누적 Fcst qty * (-1) + 특정일자까지 누적 WH_IN total 누적수량 ) */
          /*----------------------------------------------------------------------------------------------------------- */
          /* 기존의 RTF Balance는 Allocation에 대해서 Balance를 표현하였으며,WH_in total수량에 대한 Balance는 BOH( 기초재고)를 감안하여, Fcst매출을 차감한 실물기준 재고예상을 보여주는 것입니다. */
            /* FN_GET_SSP_ANL_BOH_QTY](division_id ,plan_start_yyyymmdd, plan_type, seq, to_site , item_id,from_yyyymmdd) , 1) as int) as boh */
          IF P_DIVISION_ID <>  '40' /* MEASURE ='BALANCE' */
          THEN
              INSERT INTO GT_SASF_FG
                      (
                        DIVISION_ID
                        ,PLAN_START_YYYYMMDD
                        ,PLAN_TYPE
                        ,SEQ
                        ,OPERATION_GROUP
                        ,PROJECT_CODE
                        ,ITEM_ID
                        ,TO_SITE
                        ,INCOTERMS
                        ,FROM_SITE
                        ,BOD_ID
                        ,MEASURE
                        ,YYYYMMDD
                        /* ,ORIGIN_FROM_DIVISION_ID */
                        /* ,ORIGIN_TO_DIVISION_ID */
                        /* ,ELECTRODE_TYPE */
                        ,QTY
                        )
                SELECT
                              Y.DIVISION_ID
                              ,Y.PLAN_START_YYYYMMDD
                              ,Y.PLAN_TYPE
                              ,Y.SEQ
                              ,Y.OPERATION_GROUP
                              ,Y.PROJECT_CODE
                              ,Y.ITEM_ID
                              ,Y.TO_SITE
                              ,Y.INCOTERMS
                              ,'-' AS FROM_SITE
                              ,'-' AS BOD_ID
                              ,'WH_IN_BALANCE' AS MEASURE
                              ,Y.YYYYMMDD
                              /* ,Y.ORIGIN_FROM_DIVISION_ID */
                              /* ,Y.ORIGIN_TO_DIVISION_ID */
                              /* ,Y.ELECTRODE_TYPE */
                              ,( SELECT
                                      NVL( SUM(CASE MEASURE WHEN 'MKT_FCST'  THEN -1 * NVL(QTY,0)
                                                                WHEN 'WH_IN'    THEN      NVL(QTY,0)
                                                        ELSE 0.0
                                            END),0)
                                  FROM GT_SASF_FG X
                                WHERE 1=1
                                  AND X.DIVISION_ID          = Y.DIVISION_ID
                                  AND X.PLAN_START_YYYYMMDD  = Y.PLAN_START_YYYYMMDD
                                  AND X.PLAN_TYPE            = Y.PLAN_TYPE
                                  AND X.SEQ                  = Y.SEQ
                                  AND X.PROJECT_CODE         = Y.PROJECT_CODE
                                  AND X.ITEM_ID              = Y.ITEM_ID
                                  AND X.TO_SITE              = Y.TO_SITE
                                  AND X.INCOTERMS            = Y.INCOTERMS
                                  AND X.MEASURE              IN ('MKT_FCST','WH_IN')
                                  /* AND X.ORIGIN_FROM_DIVISION_ID   = Y.ORIGIN_FROM_DIVISION_ID */
                                  /* AND X.ORIGIN_TO_DIVISION_ID     = Y.ORIGIN_TO_DIVISION_ID */
                                  /* AND X.ELECTRODE_TYPE            = Y.ELECTRODE_TYPE */
                                  AND X.YYYYMMDD             <= Y.YYYYMMDD
                                )  + NVL(BOH.PSI_BOH_QTY,0) AS PSI_BOH_QTY
                          FROM GT_SASF_Y Y
                             , GT_SASF_BOH BOH

                        WHERE 1=1
                          AND Y.DIVISION_ID          = BOH.DIVISION_ID(+)
                          AND Y.PLAN_START_YYYYMMDD  = BOH.PLAN_START_YYYYMMDD(+)
                          AND Y.PLAN_TYPE            = BOH.PLAN_TYPE(+)
                          AND Y.SEQ                  = BOH.SEQ(+)
                          AND Y.TO_SITE              = BOH.SITE_ID(+)
                          AND Y.ITEM_ID              = BOH.ITEM_ID(+)
                        AND Y.YYYYMMDD   < TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD') /* 8주(56일) 추가 */
                        ;
          END IF;
           /*----------------------------------------------------------------------------------------------------------- */
            /* 10. MKT_FCST ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID,ELECTRODE_TYPE UPDATE */
            /*----------------------------------------------------------------------------------------------------------- */

             UPDATE GT_SASF_FG X
               SET X.ORIGIN_FROM_DIVISION_ID =
                   ( SELECT MAX(Y.DIVISION_ID)
                       FROM SCM_MST_SITE Y /* from   PLANT_SITE_ID */
                      WHERE 0 = 0
/* AND Y.SITE_TYPE   = 'PLANT' */
                        AND (CASE WHEN X.DIVISION_ID = 'EE' THEN '0' ELSE X.DIVISION_ID END ) = (CASE WHEN X.DIVISION_ID = 'EE' THEN '0' ELSE Y.DIVISION_ID END )
                        AND Y.SCM_SITE_ID  = REPLACE(X.FROM_SITE,'-S','')
                        AND Y.VALID_YN ='Y' );

            UPDATE GT_SASF_FG X
               SET X.ORIGIN_TO_DIVISION_ID =
                   ( SELECT MAX(Y.DIVISION_ID)
                       FROM SCM_MST_SITE Y /* to   SALES_SITE_ID */
                      WHERE 0 = 0
/* AND Y.SITE_TYPE   = 'PLANT' */
                        AND (CASE WHEN X.DIVISION_ID = 'EE' THEN '0' ELSE X.DIVISION_ID END ) = (CASE WHEN X.DIVISION_ID = 'EE' THEN '0' ELSE Y.DIVISION_ID END )
                        AND Y.SCM_SITE_ID  = REPLACE(X.TO_SITE,'-S','')
                        AND Y.VALID_YN ='Y' );

            UPDATE GT_SASF_FG X
               SET ( X.ELECTRODE_TYPE, X.OPERATION_GROUP ) =
                   ( SELECT Y.ELECTRODE_TYPE, Y.OPERATION_GROUP
                       FROM SCP_MST_FINAL_ITEM_V Y
                      WHERE 0 = 0
                        AND X.ITEM_ID          = Y.ITEM_ID
                        AND ROWNUM = 1 )
             WHERE X.DIVISION_ID      = P_DIVISION_ID
               AND EXISTS ( SELECT 1
                              FROM SCP_MST_FINAL_ITEM_V Y2
                             WHERE X.ITEM_ID = Y2.ITEM_ID );
            V_ROWCOUNT := SQL%ROWCOUNT;

          /*----------------------------------------------------------------------------------------------------------- */
          /* 11. SSP_ANL_SHIPMENT_PLAN_FG 삭제 */
          /*----------------------------------------------------------------------------------------------------------- */
            /* DELETE FROM SSP_ANL_SHIPMENT_PLAN_FG */
            /* WHERE DIVISION_ID = @p_division_id AND PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd AND PLAN_TYPE = @p_plan_type AND SEQ = @p_seq */
            /* 소형(40) 삭제시 속도 계선. */
            /* SELECT @@ROWCOUNT */
            /* 1000 [1043::PR::2][07:23] */
            /* 10000 [1043::PR::2][10:12] */
            /* 100000 [1043::PR::2][05:38] */
            WHILE V_ROWCOUNT > 0 /* 상단의 UPDATE문 @@ROWCOUNT */
            LOOP
              DELETE
              FROM SSP_ANL_SHIPMENT_PLAN_FG
              WHERE DIVISION_ID = P_DIVISION_ID AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD AND PLAN_TYPE = P_PLAN_TYPE AND SEQ = P_SEQ
                AND ROWNUM <= 10000;
              V_ROWCOUNT := SQL%ROWCOUNT;
            END LOOP;

           /*----------------------------------------------------------------------------------------------------------- */
          /* 12. SSP_ANL_SHIPMENT_PLAN_FG 입력 */
          /*----------------------------------------------------------------------------------------------------------- */
          INSERT INTO /* PR_SSP_ANL_SHIPMENT_PLAN_FG */
                      SSP_ANL_SHIPMENT_PLAN_FG
                     (
                        DIVISION_ID
                       ,PLAN_START_YYYYMMDD
                       ,PLAN_TYPE
                       ,SEQ
                       ,BIZ_TYPE /* OPERATION_GROUP */
                       ,PROJECT_CODE
                       ,ITEM_ID
                       ,TO_SITE
                       ,INCOTERMS
                       ,FROM_SITE
                       ,BOD_ID
/* ,TRANSPORT_MODE */
                       ,MEASURE
                       ,YYYYMMDD
                       ,ORIGIN_FROM_DIVISION_ID
                       ,ORIGIN_TO_DIVISION_ID
                       ,ELECTRODE_TYPE
                       ,QTY
                       ,CREATED_BY
                       ,CREATION_DATE
                       ,LAST_UPDATED_BY
                       ,LAST_UPDATE_DATE
                       )
                    SELECT
                           DIVISION_ID
                          ,PLAN_START_YYYYMMDD
                          ,PLAN_TYPE
                          ,SEQ
                          ,NVL(NULLIF(RTRIM(OPERATION_GROUP),''), '/')
                          ,SUBSTR(NVL(PROJECT_CODE, '-'), 1, 50)
                          ,SUBSTR(ITEM_ID, 1, 50)
                          ,SUBSTR(TO_SITE, 1, 30)
/* ,MAX(ISNULL(INCOTERMS, '-'))  AS INCOTERMS */
                          ,SUBSTR(NVL(INCOTERMS, '-'), 1, 10)  AS INCOTERMS
                          ,SUBSTR(NVL(FROM_SITE, '-'), 1, 30)
                          ,NVL(BOD_ID,'-')
/* ,TRANSPORT_MODE */
                          ,MEASURE
                          ,YYYYMMDD
                          ,ORIGIN_FROM_DIVISION_ID
                          ,ORIGIN_TO_DIVISION_ID
                          ,ELECTRODE_TYPE
                          ,SUM(QTY) AS QTY
                          ,V_BATCH_USER AS CREATED_BY
                          ,SYSDATE       AS CREATION_DATE
                          ,V_BATCH_USER AS LAST_UPDATED_BY
                          ,SYSDATE       AS LAST_UPDATED_BY
                      FROM GT_SASF_FG
                     WHERE 1=1
                     AND YYYYMMDD < TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD') /* 8주(56일) 추가 */
                     GROUP BY DIVISION_ID
                          ,PLAN_START_YYYYMMDD
                          ,PLAN_TYPE
                          ,SEQ
                          ,NVL(NULLIF(RTRIM(OPERATION_GROUP),''), '/') /* [E20261009-GRPBYFIX] GROUP BY 식 = SELECT 식 */ /* GROUP BY 는 위 SELECT 적재식과 동일해야 함(ORA-00979 방지) */
                          ,NVL(PROJECT_CODE, '-') /* GROUP BY 는 위 SELECT 적재식과 동일해야 함(ORA-00979 방지 / PK 중복 ORA-00001 방지) */
                          ,ITEM_ID
                          ,TO_SITE
                          ,NVL(INCOTERMS, '-')
                          ,NVL(FROM_SITE, '-') /* GROUP BY 는 위 SELECT 적재식과 동일해야 함(ORA-00979 방지 / PK 중복 ORA-00001 방지) */
                          ,NVL(BOD_ID,'-')
                          ,MEASURE
                          ,YYYYMMDD
                          ,ORIGIN_FROM_DIVISION_ID
                          ,ORIGIN_TO_DIVISION_ID
                          ,ELECTRODE_TYPE
                          ;

        /*--------------------------------------------------------- */
        /* 실행 Logic END -- */
        /*--------------------------------------------------------- */
        /* IF @@TRANCOUNT > 0 */
        /* BEGIN */
        /* COMMIT TRAN TX_FG; */
        /* END; */


        /* TXN LOG */
        V_LOG_TYPE := 'TXN';
        N_LOG_COUNT := 1; /* 원본 @@ROWCOUNT : 직전 스칼라 SET(@v_log_type) 이후라 항상 1 */
        V_LOG_MESSAGE := 'INSERT INTO '||V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE := SYSDATE;

        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER
                            );

    EXCEPTION
      WHEN OTHERS THEN
      /* IF @@TRANCOUNT > 0 */
      /* BEGIN */
      /* ROLLBACK TRAN TX_FG */
      /* END; */

      /* ERROR LOG (하위단계 proc·무TRAN → 롤백/RAISE 신설 없음, 원본 CATCH 흡수형 return -1) */
        V_ERR_MSG := SQLERRM;
        V_LOG_TYPE := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(V_ERR_MSG, 1, 1000);
        V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        D_EVENT_DATE := SYSDATE;
        PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                            , P_LOG_TYPE      => V_LOG_TYPE
                            , P_LOG_COUNT     => N_LOG_COUNT
                            , P_LOG_MESSAGE   => V_LOG_MESSAGE
                            , P_DESCRIPTION   => V_DESCRIPTION
                            , P_EVENT_DATE    => D_EVENT_DATE
                            , P_USER_ID       => V_BATCH_USER
                            );
/* PRINT @@ERROR */
        RETURN;
    END;

/* 임시 운영반영시에 주석처리 할것. */
    V_TOTAL_SEC := TRUNC((SYSDATE - V_START_TIME) * 86400);
    V_MIN := TRUNC(V_TOTAL_SEC / 60);
    V_SEC := MOD(V_TOTAL_SEC, 60);

    V_EXEC_TIME := CASE WHEN LENGTH(TO_CHAR(V_MIN)) > 2 OR LENGTH(TO_CHAR(V_SEC)) > 2
                        THEN NULL
                        ELSE LPAD(TO_CHAR(V_MIN), 2, '0') || ':' || LPAD(TO_CHAR(V_SEC), 2, '0')
                   END;

    /* 종료 LOG */
    V_LOG_TYPE := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    /* 원본 '[' + @p_master_id + ']['+@p_engine_plan_id+'][' + @v_exec_time + ']' : + NULL 전파 재현(CASE 가드) */
    V_DESCRIPTION := CASE WHEN P_MASTER_ID IS NULL OR P_ENGINE_PLAN_ID IS NULL OR V_EXEC_TIME IS NULL
                          THEN NULL
                          ELSE '[' || P_MASTER_ID || '][' || P_ENGINE_PLAN_ID || '][' || V_EXEC_TIME || ']'
                     END;
    D_EVENT_DATE :=  SYSDATE  ;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );
    RETURN;

  END;
/

-- 적용 결과: 전부 VALID · APPLY ERR 0행 기대
SELECT 'APPLY | ' || object_type || ' ' || object_name || ' | ' || status || ' | ddl=' || TO_CHAR(last_ddl_time,'YYYY-MM-DD HH24:MI:SS') AS line
  FROM all_objects WHERE owner='SCM_MGR' AND object_name IN ('DMF0020_GET_SCM_MST_FUTURE_PRICE','PKG_DMF0021','PKG_DMF0045','PKG_SCP0013','PKG_SSP0045','PR_DM_DNM_EDI_CALLOFF_MKT_FCST','PR_DM_PLN_SALES_PLAN_RESULT_MOVE','PR_SSP_ANL_SHIPMENT_PLAN_FG') AND object_type IN ('PACKAGE BODY','PROCEDURE') ORDER BY object_name, object_type;
SELECT 'APPLY ERR | ' || type || ' ' || name || ' L' || line || ':' || position || ' | ' || SUBSTR(REPLACE(text,CHR(10),' '),1,200) AS line
  FROM all_errors WHERE owner='SCM_MGR' AND name IN ('DMF0020_GET_SCM_MST_FUTURE_PRICE','PKG_DMF0021','PKG_DMF0045','PKG_SCP0013','PKG_SSP0045','PR_DM_DNM_EDI_CALLOFF_MKT_FCST','PR_DM_PLN_SALES_PLAN_RESULT_MOVE','PR_SSP_ANL_SHIPMENT_PLAN_FG') AND attribute='ERROR' ORDER BY name, sequence;
